<?php
require_once __DIR__.'/ManagedNodeHelp.php';

trait BotMenuHelp
{
    public function menuHelpButton(string $topic, string $context = ''): array
    {
        return [['text' => $this->i18n('menu help'),
            'callback_data' => '/menuhelp ' . $topic . ' 0' . ($context === '' ? '' : ' ' . $context)]];
    }

    public function menuHelp(string $topic, int $page = 0, string $context = ''): void
    {
        $help = $this->menuHelpContent($topic, $context);
        if (!$help) return;
        [$title, $back, $pages] = $help;
        $titles = array_keys($pages);
        $count = count($pages);
        $page = max(0, min($page, $count));
        if ($count === 1) $page = 1;
        $callback = fn(int $n) => '/menuhelp ' . $topic . ' ' . $n . ($context === '' ? '' : ' ' . $context);
        $text = self::esc($title) . ' → ' . $this->i18n('menu help') . "\n\n";
        $data = [];
        if ($page === 0) {
            $text .= $this->i18n('menu help choose');
            foreach ($titles as $index => $name) $data[] = [['text' => ($index + 1) . '. ' . $name, 'callback_data' => $callback($index + 1)]];
        } else {
            $name = $titles[$page - 1];
            $text .= '<b>' . self::esc($name) . "</b>\n\n" . $pages[$name];
            if ($count > 1) {
                $nav = [];
                if ($page > 1) $nav[] = ['text' => '←', 'callback_data' => $callback($page - 1)];
                $nav[] = ['text' => "$page/$count", 'callback_data' => $callback($page)];
                if ($page < $count) $nav[] = ['text' => '→', 'callback_data' => $callback($page + 1)];
                $data[] = $nav;
                $data[] = [['text' => $this->i18n('menu help topics'), 'callback_data' => $callback(0)]];
            }
        }
        $data[] = [['text' => $this->i18n('back'), 'callback_data' => $back]];
        $this->update($this->input['chat'], $this->input['message_id'], $text, $data);
    }

    // Только справочные тексты и фиксированные маршруты возврата. Просмотр не
    // обращается к ядрам, не сохраняет настройки и не запускает перезагрузки.
    public function menuHelpContent(string $topic, string $context = ''): array
    {
        $ru = $this->language === 'ru';
        $t = static fn(string $ruText, string $enText) => $ru ? $ruText : $enText;
        switch ($topic) {
            case 'nodepeers':
                if (!preg_match('~^([a-f0-9]{8})(?:_([a-f0-9]{10}))?$~D', $context, $match)
                    || !isset($this->managedNodes()[$match[1]])
                    || (isset($match[2]) && !$this->managedNodePeer($match[1], $match[2]))) return [];
                $pages = [];
                foreach (ManagedNodeHelp::pages('peers') as $section) {
                    $pages[$t($section['ru'], $section['en'])] = $t($section['text']['ru'], $section['text']['en']);
                }
                return [$t('Ноды → Внешние подключения', 'Nodes → External connections'),
                    isset($match[2]) ? '/nodePeer '.$match[1].' '.$match[2] : '/nodePeers '.$match[1], $pages];
            case 'nodeconfig':
                if (!preg_match('~^([a-f0-9]{8})_([a-z]+)$~D', $context, $match)
                    || !isset($this->managedNodes()[$match[1]]) || !isset(ManagedNodeFields::GROUPS[$match[2]])) return [];
                $pages = [];
                foreach (ManagedNodeHelp::pages($match[2]) as $section) {
                    $pages[$t($section['ru'], $section['en'])] = $t($section['text']['ru'], $section['text']['en']);
                }
                return [$t('Ноды → ', 'Nodes → ') . $t(...array_values(ManagedNodeFields::GROUPS[$match[2]])),
                    '/nodeSettings '.$match[1].' '.$match[2], $pages];
            case 'navigation':
                return [$t('Управление ботом', 'Bot navigation'), '/menu', [
                    $t('Меню, ввод и сообщения', 'Menus, input and messages') => $t(
                        "Кнопки и «Назад» обычно обновляют текущее сообщение. <code>/menu</code> и <code>/start</code> отправляют новое меню и удаляют прежнее.\n\nОтвечайте на запрос ввода обычным сообщением или через ответ Telegram: в личном чате сообщение без пометки «ответ» относится к последнему запросу бота в течение 30 минут. В группе используйте ответ Telegram. После обработки запрос и ваш ответ удаляются. Кнопка или команда <code>/…</code> отменяет незавершённый ввод в этом чате. После обновления старый запрос без привязки к чату нужно открыть заново. При ошибке проверьте пояснение и повторите ввод соответствующей кнопкой.\n\nДополнительные части длинного экрана, временные подсказки и QR удаляются при следующем действии. Для временных файлов подписок сохраняйте копию перед переходом. Бэкапы, обычные выгрузки и фоновые уведомления не очищаются общей навигацией.\n\nTelegram может запретить удаление старых сообщений (обычно старше 48 часов) или отказать из-за прав в группе. Такие сообщения можно удалить вручную. Бот не очищает всю историю чата.",
                        "Buttons and Back normally edit the current message. <code>/menu</code> and <code>/start</code> send a new menu and remove the previous one.\n\nAnswer an input prompt with an ordinary message or with Telegram Reply: in a private chat, a message without the reply mark goes to the bot's latest prompt within 30 minutes. In a group, use Telegram Reply. After processing, the prompt and your answer are deleted. A button or a <code>/…</code> command cancels pending input in this chat. After an upgrade, reopen an old prompt without a chat binding. On an error, read the explanation and request input again using the corresponding button.\n\nExtra parts of long screens, temporary hints and QR codes are removed on the next action. Save temporary subscription files before navigating away. Backups, ordinary exports and background notifications are not cleared by general navigation.\n\nTelegram may forbid deleting old messages (usually older than 48 hours) or deny group permissions. Those messages can be removed manually. The bot does not sweep the chat history."),
                ]];
            case 'nodemaint':
                if (!isset($this->managedNodes()[$context])) return [];
                return [$t('Ноды → Обслуживание', 'Nodes → Maintenance'), '/nodeMaintenance '.$context, $this->managedNodeMaintenancePages()];
            case 'acme':
                return [$t('SSL автообновление', 'SSL auto-renewal'), '/acmeMenu', [
                    $t('Как это работает', 'How it works') => $t(
                        "Let's Encrypt подтверждает, что домен ваш, запросом на порт 80 сервера. Если firewall пускает на порт 80 только свои сети (ASN и список своих серверов), проверка не проходит и сертификат не продлить.\n\nСлужба хоста <b>acme-window</b> делает так: когда пора продлевать, она разрешает порт 80 для всех не дольше чем на 10 минут, принудительно выпускает сертификат и сразу снимает разрешение. Обычно порт открыт несколько секунд. Остальные правила firewall не меняются; чёрный список и ограничения для чужих адресов действуют и в это время, другие порты не открываются.\n\nЗакрытие гарантировано несколькими путями: разрешение снимается сразу после certbot; при сбое службы его снимает отдельная служба закрытия; если не сработало и это — ядро само удаляет разрешение через 10 минут. После перезагрузки сервера разрешений нет.",
                        "Let's Encrypt proves that you own a domain with a request to port 80 of the server. If the firewall lets only trusted networks reach port 80 (ASN and your own servers), the check fails and the certificate cannot be renewed.\n\nThe <b>acme-window</b> host service handles this: when renewal is due, it allows port 80 for everyone for at most 10 minutes, issues the certificate by force and removes the permission at once. Usually the port is open for a few seconds. Other firewall rules are not changed; the blacklist and limits for unknown addresses still apply, and no other port is opened.\n\nClosing is guaranteed in several ways: the permission is removed right after certbot; if the service fails, a separate close service removes it; if that also fails, the kernel deletes the permission after 10 minutes. After a reboot there is no permission at all."),
                    $t('Когда продлевается и повторы', 'When it renews and retries') => $t(
                        "Проверка идёт раз в час. Сертификат продлевается, когда осталась треть его срока: для сертификата на 90 дней — примерно за 30 дней до окончания. Время показывает строка «следующая попытка».\n\nЕсли выпуск не удался, следующая попытка — через 1 час, затем через 2, 4 и дальше каждые 6 часов; когда до окончания меньше 7 дней — каждый час. Об успехе приходит сообщение. О неудаче — первое сообщение сразу, повторные не чаще раза в сутки (за 7 дней до окончания — раз в 6 часов).\n\nЧтобы не упереться в ограничения Let's Encrypt, служба выпускает не больше 3 сертификатов за 7 дней и допускает не больше 3 неудачных проверок домена в час; выпуск вручную — не чаще раза в 10 минут. Плановая проверка при исчерпанном лимите просто ждёт, а ручной запрос сверх лимита отклоняется с сообщением; итог последней попытки при этом не затирается.",
                        "The check runs hourly. A certificate is renewed when a third of its lifetime is left: about 30 days before expiry for a 90-day certificate. The «next attempt» line shows the time.\n\nIf issuance fails, the next attempt comes after 1 hour, then 2, 4 and every 6 hours after that; with less than 7 days left, every hour. A success sends a message. A failure sends the first message at once and repeats at most once a day (every 6 hours in the last 7 days).\n\nTo stay within Let's Encrypt limits, the service issues at most 3 certificates in 7 days and allows at most 3 failed domain checks an hour; manual issuance at most once every 10 minutes. With a limit reached, the scheduled check simply waits, while a manual request is refused with a message; the result of the last attempt is kept."),
                    $t('Кнопки меню', 'Menu buttons') => $t(
                        "Для каждого сертификата сервера — своя строка: срок действия, автообновление, следующая и последняя попытки.\n\n<b>✅ / ⬜ авто</b> — включить или выключить автообновление этого сертификата. При выключенном служба его не продлевает; выпуск вручную остаётся.\n\n<b>♻️ обновить</b> — выпустить сертификат сейчас, даже если срок не подошёл (после подтверждения). Результат приходит отдельным сообщением через несколько минут; это один выпуск из лимита.\n\n<b>🔄</b> — перечитать состояние службы.\n\nКнопка «обновить SSL» в настройках при работающей службе тоже передаёт запрос службе, а не запускает certbot в боте; первый выпуск («Letsencrypt SSL») идёт так же. Загруженный вами собственный сертификат служба не трогает.",
                        "Each certificate of the server has its own line: validity, auto-renewal, next and last attempts.\n\n<b>✅ / ⬜ auto</b> turns auto-renewal of this certificate on or off. When off, the service does not renew it; manual issuance stays available.\n\n<b>♻️ renew</b> issues the certificate now, even if it is not due (after confirmation). The result arrives as a separate message in a few minutes; it uses one issuance from the limit.\n\n<b>🔄</b> rereads the service state.\n\nWith the service running, «renew SSL» in Settings also passes the request to the service instead of running certbot in the bot; the first issuance («Letsencrypt SSL») works the same way. A certificate you uploaded yourself is never touched by the service."),
                    $t('Итоги и ошибки', 'Results and errors') => $t(
                        "<b>✅ сертификат обновлён</b> — выпущен, установлен, сервер отдаёт новый.\n<b>⚠️ сервер отдаёт прежний</b> — выпуск прошёл, но проверка по адресу сервера видит старый сертификат. Повтора не будет (сертификат уже выпущен): проверьте nginx.\n<b>❌ Let's Encrypt не выдал</b> — проверка домена не прошла; в сообщении — ответ certbot.\n<b>❌ не установлен / файл не изменился</b> — сертификат выпущен, но установка не удалась; такой выпуск тоже идёт в лимит.\n<b>❌ имя в DNS указывает не на этот сервер</b> — порт не открывался; поправьте DNS всех имён сертификата.\n<b>❌ проверка перед выпуском</b> — нет контейнера nginx или php, либо nginx на другом адресе.\n<b>❌ порт 80 не открылся или не закрылся</b> — ошибка правил firewall на сервере; разрешение всё равно истечёт через 10 минут.\n<b>сертификат не от Let's Encrypt</b> — у бота свой сертификат или нет домена: служба ничего не делает.\n<b>⚠️ служба не отвечает больше трёх часов</b> — служба на сервере остановлена или удалена; «обновить SSL» тогда работает по-старому и при закрытом порте 80 не сработает.",
                        "<b>✅ certificate renewed</b>: issued, installed, and the server serves the new one.\n<b>⚠️ the server still serves the old one</b>: issuance passed, but a check at the server address sees the old certificate. It is not retried (the certificate is already issued): check nginx.\n<b>❌ Let's Encrypt did not issue</b>: the domain check failed; the message contains the certbot answer.\n<b>❌ not installed / the file did not change</b>: the certificate was issued but installation failed; such an issuance also counts towards the limit.\n<b>❌ a DNS name does not point to this server</b>: the port was not opened; fix DNS for every name of the certificate.\n<b>❌ the pre-issuance check failed</b>: the nginx or php container is missing, or nginx has another address.\n<b>❌ port 80 did not open or close in time</b>: a firewall rule problem on the server; the permission still expires after 10 minutes.\n<b>not a Let's Encrypt certificate</b>: the bot uses its own certificate or has no domain, so the service does nothing.\n<b>⚠️ the host service has not answered for over three hours</b>: the service is stopped or removed; «renew SSL» then works the old way and fails while port 80 is closed."),
                    $t('Другие сертификаты сервера', 'Other certificates of the server') => $t(
                        "Служба может продлевать и сертификаты соседних проектов на этом сервере (например, видеобота). Они видны в этом меню своими строками с теми же кнопками, а сообщения о них приходят от этого бота. Если у соседнего проекта тот же домен, на время его выпуска порт 80 ведёт к нему, и выпуски идут строго по очереди. Какие сертификаты продлевать, задаёт администратор сервера в настройках службы.",
                        "The service can also renew certificates of other projects on this server (a video bot, for example). They appear in this menu as separate lines with the same buttons, and their messages come from this bot. If another project uses the same domain, port 80 leads to it while its certificate is issued, and issuances run strictly one at a time. The server administrator chooses which certificates to renew in the service settings."),
                    $t('Для администратора сервера', 'For the server administrator') => $t(
                        "При штатной установке и обновлении бот сам устанавливает защиту источника контейнеров и проверяет окно ACME. Основной <code>/etc/nftables.conf</code> администратор готовит заранее по профилю nftables.conf. Если наборов окна нет, новая установка окна пропускается с предупреждением; если они исчезли у установленной службы, обновление сообщает об ошибке.\n\nWAN, публичный IPv4 и адрес nginx берутся из правил и проверяются по хосту. Для HTTP-01 все A-записи имён должны вести на этот сервер; текущая схема окна работает по IPv4 и отказывается от имён с AAAA. Наличие исходящего IPv6 само по себе сертификата не требует. Существующие цели, флажки автообновления и история сохраняются. Актуальная работающая служба не переустанавливается и открытое окно не прерывается.\n\nИз каталога бота от root:\n<code>python3 scripts/setup_acme.py check --bot-dir /root/vpnbot</code> — проверить;\n<code>python3 scripts/setup_acme.py ensure --bot-dir /root/vpnbot</code> — установить/обновить при необходимости;\n<code>python3 scripts/setup_acme.py test --bot-dir /root/vpnbot</code> — staging HTTP-01 без замены рабочего сертификата.\n\nСостояние: <code>acme-window status</code>. Журнал: <code>journalctl -u acme-window</code>. Защита контейнеров: <code>systemctl status vpnbot-origin</code>. Подробности и ручная установка — docs/HOST_SERVICES_RU.md. Бэкап бота не переносит настройки и состояние служб хоста.",
                        "Normal installation and updates install the container origin guard and check the ACME window automatically. The administrator prepares <code>/etc/nftables.conf</code> first using a supported nftables.conf profile. Without window sets, a fresh window installation is skipped with a warning; missing sets for an installed service are an error.\n\nWAN, public IPv4 and nginx address come from the rules and are checked against the host. Every A record must point to this server. The current HTTP-01 window uses IPv4 and refuses names with AAAA records. Outgoing IPv6 alone needs no certificate. Existing targets, auto-renewal flags and history are preserved. An up-to-date running service is not reinstalled and an open window is not interrupted.\n\nAs root, from the bot directory:\n<code>python3 scripts/setup_acme.py check --bot-dir /root/vpnbot</code>: validate;\n<code>python3 scripts/setup_acme.py ensure --bot-dir /root/vpnbot</code>: install/update if needed;\n<code>python3 scripts/setup_acme.py test --bot-dir /root/vpnbot</code>: staging HTTP-01 without replacing the live certificate.\n\nStatus: <code>acme-window status</code>. Log: <code>journalctl -u acme-window</code>. Container guard: <code>systemctl status vpnbot-origin</code>. Details and manual setup: docs/HOST_SERVICES_RU.md. Bot backups do not transfer host service settings or state."),
                ]];
            case 'tt':
                $back = preg_match('~^[a-zA-Z0-9_.\-]{1,40}$~D', $context) ? '/ttClientMenu ' . $context : '/menu tt';
                return ['TrustTunnel', $back, [
                    $t('Подключение и управление доступом', 'Connection and access') => $t(
                        "Откройте пользователя: ссылка и QR подходят для приложения TrustTunnel, файл TOML — для настройки CLI-клиента через setup_wizard. Оба варианта содержат пароль; передавайте их только владельцу доступа. После смены пароля выдайте новый профиль. Удаление после подтверждения отзывает доступ. Смена реквизитов и перезапуск переподключают остальных пользователей.\n\nСервер принимает HTTP/2 по TCP и HTTP/3 по UDP на указанном внешнем порту. Штатный экспорт использует HTTP/2. HTTP/3 можно выбрать в поддерживающем его клиенте; UDP-порт должен быть доступен. Нужны домен и действующий сертификат. При собственном сертификате используйте выданный ботом профиль с сертификатом, сохраняя проверку TLS.",
                        "Open a user: the link and QR import into the TrustTunnel app; the TOML file configures the CLI client through setup_wizard. Both contain credentials. After changing a password, issue a new profile. Confirmed deletion revokes access. Credential changes and restarts reconnect other users too.\n\nThe endpoint accepts HTTP/2 over TCP and HTTP/3 over UDP on the external port. Standard exports use HTTP/2. Select HTTP/3 in a compatible client with UDP reachable. A hostname and valid certificate are required. For a private certificate, use the exported profile containing it and keep TLS verification enabled."),
                    $t('Сессии, трафик и IP', 'Sessions, traffic and IP') => $t(
                        "🟢 — у пользователя есть активная сессия, ⚪ — сессий нет. 🔑 означает, что данные метрик недоступны; это не доказательство отключения пользователя. «Обновить» заново читает состояние, не перезапуская VPN. В списке показываются 20 пользователей на странице.\n\nВ карточке ↑ — байты, отправленные клиентом через сервер; ↓ — полученные клиентом. Это счётчики ядра с его последнего запуска. Перезапуск, смена реквизитов, выключение контейнера и восстановление с перезапуском обнуляют их. Это не месячная квота и не постоянный учёт для оплаты; резервная копия не сохраняет эти оперативные значения.\n\nСессии не равны числу устройств. Ядро возвращает один IP соединения, а не полный список устройств. За NGINX или relay это может быть адрес промежуточного сервера. Не используйте его как достоверный внешний IP клиента.",
                        "🟢 means an active session, ⚪ no active sessions. 🔑 means metrics are unavailable, not proof that the user is disconnected. Refresh reads status without restarting the VPN. Lists show 20 users per page.\n\n↑ counts bytes uploaded by the client; ↓ counts bytes downloaded. Counters cover the current core process lifetime and reset on restart, credential changes, container shutdown or a restore that restarts the core. They are not a monthly quota or persistent billing records; backups do not preserve these runtime counters.\n\nSessions are not a device count. The core returns one connection IP, not a complete device list. Behind NGINX or a relay it may be the intermediary address, not the client's public IP."),
                    $t('Если статистика недоступна', 'Unavailable statistics') => $t(
                        "Нужен TrustTunnel 1.1.0+ с per_client_metrics. При штатном запуске бот дополняет старый vpn.toml без ручной настройки метрик: адрес 127.0.0.1:1987, per_client_metrics = true. Данные считываются через SSH внутри контейнера; открывать порт снаружи не требуется.\n\nЕсли настройки metrics уже указаны вручную, бот сохраняет их. Для карточек нужен именно локальный адрес 127.0.0.1:1987 и включённый per_client_metrics. После ручной правки перезапустите TrustTunnel и обновите карточку. Недоступный API, старая версия, выключенный модуль или неправильный ответ показываются как «Статистика недоступна», а не как нулевой расход. Метрики содержат имена и IP: не публикуйте этот listener в Интернет.",
                        "Requires TrustTunnel 1.1.0+ with per_client_metrics. Normal startup adds loopback metrics to an older vpn.toml without a manual metrics policy: 127.0.0.1:1987 and per_client_metrics = true. The bot reads them via SSH inside the container; no public port is needed.\n\nExisting manual metrics settings are preserved. Cards require that loopback address and per_client_metrics enabled. Restart TrustTunnel after manual edits, then refresh. API failures, older versions, disabled modules and invalid responses display unavailable rather than zero traffic. Metrics contain usernames and IPs: never expose this listener publicly."),
                ]];
            case 'telemt_main':
                return ['TeleMT', '/telemt', [
                    $t('Статус и два способа подключения', 'Status and connection types') => $t(
                        "TeleMT предоставляет прокси для Telegram. Обычный MTProxy подключается к отдельному TCP-порту; WEB использует ваш HTTPS-поддомен на порту 443. Один пользователь может пользоваться обоими способами с общими квотой и Limit IP. Это не VPN для остальных приложений.\n\n<b>status</b> показывает наличие процесса ядра, а не успешность подключения до Telegram. <b>version</b> — версия образа TeleMT. <b>port</b> — внешний порт MTProxy, задаётся в «Настройки → Порты». WEB включается отдельно в своём меню. Общий выключатель модуля TeleMT находится в меню протоколов; он отключает оба способа подключения.\n\n<b>fast mode</b> в этой сборке включён постоянно: ядро использует прямое подключение к DC Telegram. Переключателя Middle-End в боте нет. Состояния masking и diagnostics означают включённые настройки, а не результат проверки обхода блокировок.",
                        "TeleMT is a Telegram proxy. Native MTProxy uses a separate TCP port; WEB uses your HTTPS hostname on port 443. Both share each user's quota and Limit IP. This is not a VPN for other applications.\n\n<b>status</b> reports the core process, not end-to-end Telegram connectivity. <b>version</b> is the TeleMT image version. <b>port</b> is the external MTProxy port, configured in Settings → Ports. Enable WEB in its own menu. The protocol module switch disables both connection types.\n\n<b>fast mode</b> is always enabled in this setup with direct Telegram DC connections; the bot has no Middle-End switch. Masking and diagnostics states describe settings, not successful block evasion."),
                    $t('Пользователи, ссылки и отзыв доступа', 'Users, links and access revocation') => $t(
                        "В «Пользователи» откройте имя: карточка содержит ссылки и QR для MTProxy и WEB, выключатель доступа, смену секрета, удаление и лимиты. Новые пользователи не имеют квоты или ограничения IP. Квоту можно сделать периодической: расход сам обнуляется ежедневно, еженедельно или ежемесячно по UTC (TeleMT 3.5.15+). Справка по ограничениям доступна в карточке → «Квота / Limit IP».\n\nВыключение пользователя закрывает оба способа подключения и сохраняет секрет, лимиты и расход. Повторное включение возвращает доступ по прежним ссылкам, если квота не исчерпана. «Сменить секрет» после подтверждения отзывает старые MTProxy- и WEB-ссылки и QR; выдайте новые. Расход при этом не сбрасывается. Удаление после подтверждения убирает пользователя. Эти действия применяются через перезапуск TeleMT: переподключатся и остальные пользователи.\n\nСсылки и QR содержат данные доступа. Выбранный relay меняет только адрес обычного MTProxy; WEB остаётся прямым. В WEB включаются первые 32 профиля, поэтому при большем числе пользователей проверяйте доступность WEB в карточке.",
                        "Open a user card for MTProxy and WEB links, QR codes, enable/disable, secret rotation, deletion and limits. New users have no quota or IP limit. A quota can be periodic: usage resets daily, weekly or monthly in UTC (TeleMT 3.5.15+). Detailed limit help is available inside the card.\n\nDisabling a user revokes both connection types while retaining their secret, limits and usage. Re-enabling restores existing links unless the quota is exhausted. Confirmed secret rotation revokes old links and QR codes without resetting usage; distribute the new links. Confirmed deletion removes the user. These changes restart TeleMT and reconnect other users too.\n\nLinks and QR codes contain credentials. A selected relay changes only native MTProxy; WEB remains direct. WEB includes the first 32 profiles, so check individual cards when there are more users."),
                ]];
            case 'telemt_mode':
                return ['TeleMT → ' . $this->i18n('telemt mode'), '/telemtMode', [
                    $t('Classic, Secure и Fake-TLS', 'Classic, Secure and Fake-TLS') => $t(
                        "Режим определяет формат обычного MTProxy, а не WEB. В боте активен один режим.\n\n<b>Classic</b> — базовый MTProto-прокси без TLS-маскировки. Секрет в ссылке без префикса.\n\n<b>Secure</b> — MTProto со случайным дополнением пакетов, секрет с префиксом <code>dd</code>. Название не означает, что сообщения в остальных режимах передаются открытым текстом.\n\n<b>Fake-TLS</b> — значение по умолчанию. Имитирует TLS-подключение к домену прикрытия, секрет с префиксом <code>ee</code> и доменом. Это не обычный HTTPS-сайт и не WEB-прокси.\n\nПосле смены режима ядро перезапускается; заново выдайте MTProxy-ссылки и QR из карточек. Сами пользовательские секреты, квоты и расход сохраняются. Формат секрета WEB (<code>dd/plain</code>) выбирается отдельно в WEB и от этого режима не меняется.",
                        "This selects native MTProxy mode, independently of WEB. One native mode is enabled at a time.\n\n<b>Classic</b>: basic MTProto proxy without TLS cover; no secret prefix.\n\n<b>Secure</b>: randomized packet padding with a <code>dd</code> secret. The name does not mean other modes transmit messages in plaintext.\n\n<b>Fake-TLS</b> is the default: it imitates a TLS connection to the cover hostname, using an <code>ee</code> secret containing the domain. This is not ordinary HTTPS or WEB proxying.\n\nChanging mode restarts the core. Distribute updated MTProxy links and QR codes. User secrets, quotas and usage are preserved. WEB's <code>dd/plain</code> format is configured separately and remains unchanged."),
                ]];
            case 'telemt_sni':
                return ['TeleMT → SNI', '/telemtSni', [
                    $t('Действие при чужом SNI', 'Unknown SNI action') => $t(
                        "SNI — имя сайта, которое клиент передаёт в начале TLS-подключения. Настройка определяет реакцию обычного MTProxy на ClientHello с именем, отличающимся от fake-TLS domain.\n\n<b>reject_handshake</b> — значение по умолчанию: отказ в TLS-рукопожатии, подобный веб-серверу без такого сайта.\n\n<b>mask</b> — передать проверочное подключение на сайт прикрытия, даже если SNI другой. Это меняет поведение при проверках и несовпадении домена; не гарантирует работоспособность любой старой ссылки.\n\n<b>drop</b> — закрыть соединение без TLS-ответа. Такой ответ тоже может быть отличим от обычного веб-сервера.\n\nОставьте reject_handshake, если нет конкретной причины менять. При ошибке Unknown TLS SNI сначала сверяйте домен в текущей MTProxy-ссылке с настройками бота. Изменение перезапускает TeleMT; ссылки не меняются. К сертификату HTTPS-поддомена WEB этот параметр не относится.",
                        "SNI is the hostname sent at the start of a TLS connection. This controls native MTProxy's response to ClientHello with a hostname different from the fake-TLS domain.\n\n<b>reject_handshake</b> is the default: a TLS handshake rejection, like a web server without that hostname.\n\n<b>mask</b> forwards the probe to the cover site despite the different SNI. It changes probe and mismatch handling; it does not guarantee all old links will work.\n\n<b>drop</b> closes without a TLS response, which may itself be distinguishable from a normal web server.\n\nKeep reject_handshake unless there is a specific reason to change it. For Unknown TLS SNI errors, first compare the current link's domain with bot settings. Changing this restarts TeleMT without changing links. It does not control WEB's HTTPS certificate."),
                ]];
            case 'telemt_settings':
                return ['TeleMT → ' . $this->i18n('telemt settings'), '/telemtSettings', [
                    $t('Домен прикрытия и порт', 'Cover hostname and port') => $t(
                        "<b>fake-TLS domain</b> — имя HTTPS-сайта, который TeleMT использует для TLS-маскировки обычного MTProxy. По умолчанию <code>www.google.com</code>; ввод <code>0</code> возвращает это значение. Вводите только домен, без https://, порта и пути. Сайт должен быть доступен с сервера по HTTPS. Бот проверяет формат имени, но это не гарантирует совместимость выбранного сайта.\n\nПосле изменения домена TeleMT перезапускается. Для режима Fake-TLS скачайте новые MTProxy-ссылки и QR: в них включён домен. Секрет пользователя, квота и расход сохраняются. WEB использует собственный поддомен и настоящий сертификат; этот домен прикрытия его не заменяет.\n\n<b>port</b> — внешний TCP-порт MTProxy. Меняется в «Настройки → Порты → TeleMT»; после смены выдайте новые ссылки и проверьте доступность порта извне. WEB использует HTTPS-порт 443 отдельно. <b>fast mode</b> отображается для информации и постоянно включён.",
                        "<b>fake-TLS domain</b> is the HTTPS cover hostname used by native MTProxy. Default: <code>www.google.com</code>; enter <code>0</code> to restore it. Enter only a domain, without scheme, port or path. The site must be reachable over HTTPS from the server. Syntax validation does not guarantee site compatibility.\n\nChanging it restarts TeleMT. In Fake-TLS mode, distribute fresh MTProxy links and QR codes because they embed the hostname. Secrets, quotas and usage remain intact. WEB requires its own hostname and a real certificate, independently of this cover domain.\n\n<b>port</b> is the external native MTProxy TCP port. Change it in Settings → Ports → TeleMT, distribute updated links and verify external reachability. WEB uses HTTPS port 443 separately. <b>fast mode</b> is informational and always enabled."),
                ]];
            case 'telemt_relays':
                return ['TeleMT → ' . $this->i18n('telemt relays'), '/telemtRelays', [
                    $t('Адрес, порт и карта портов', 'Address, port and port map') => $t(
                        "Relay — промежуточный сервер, на который указывает MTProxy-ссылка. Запись в боте только подставляет адрес и порт в ссылку; пересылку TCP с relay до основного TeleMT нужно настроить отдельно. Создание записи не устанавливает ПО и не открывает порты на другом сервере.\n\n<b>Имя</b> — метка записи. <b>Адрес</b> — IP или домен relay; <code>0</code> очищает адрес и убирает запись из выбора подключения.\n\n<b>Порт</b> — внешний порт relay (1–65535). Явно заданный порт имеет приоритет. Если он пуст, используется <b>карта портов</b>: например, <code>8443:443</code> заменит внешний порт TeleMT 8443 на порт relay 443. Без подходящей пары остаётся исходный порт TeleMT. Ввод <code>0</code> очищает порт или карту. Для одного TeleMT обычно достаточно явного порта.\n\nВыберите relay в списке пользователей и выдайте MTProxy-ссылки из карточек. Пользовательский секрет и домен Fake-TLS сохраняются. WEB через этот relay не идёт: его ссылка остаётся прямой. Если relay не сохраняет исходный IP, Limit IP видит адрес relay, а не отдельные устройства.",
                        "A relay is an intermediary named in the MTProxy link. The bot entry only substitutes its address and port; configure TCP forwarding to the main TeleMT server separately. Adding an entry does not install software or open ports on another server.\n\n<b>Name</b> is a label. <b>Address</b> is the relay IP or hostname; <code>0</code> clears it and removes the entry from connection choices.\n\nAn explicit <b>port</b> (1–65535) takes priority. Otherwise the <b>port map</b> is used: <code>8443:443</code> maps native TeleMT port 8443 to relay port 443. Without a matching entry, the original TeleMT port is retained. Enter <code>0</code> to clear the port or map. An explicit port usually suffices.\n\nSelect the relay in the users list and distribute the resulting MTProxy links. Secrets and Fake-TLS domains are retained. WEB stays direct. If the relay does not preserve the source IP, Limit IP sees the relay address instead of individual devices."),
                ]];
            case 'telemt_diagnostics':
                return ['TeleMT → ' . $this->i18n('telemt diagnostics'), '/telemtDiagnostics', [
                    $t('beobachten, retention и JA3/JA4', 'beobachten, retention and JA3/JA4') => $t(
                        "<b>beobachten</b> — наблюдение за TLS-отпечатками входящих подключений; по умолчанию выключено. JA3/JA4 описывают особенности TLS-рукопожатия и помогают сравнивать клиенты и проверочные подключения. Они не являются точным идентификатором устройства и не раскрывают содержимое сообщений Telegram. В наблюдениях могут быть сетевые адреса: учитывайте это при передаче журнала.\n\n<b>retention</b> — окно хранения групп отпечатков в памяти ядра. По умолчанию 10 минут; кнопка перебирает 5, 10, 30, 60, 180, 360, 720, 1440 минут. Это не срок доступа пользователя, период квоты или гарантия удаления строк из файла. Включение beobachten и смена окна перезапускают TeleMT.\n\nКнопка наблюдений показывает конец файла <code>config/telemt/data/beobachten.txt</code>. Если файл пуст, это может означать, что подходящих подключений ещё не было. Само включение диагностики не ускоряет прокси и не улучшает маскировку.",
                        "<b>beobachten</b> observes incoming TLS fingerprints; disabled by default. JA3/JA4 describe handshake characteristics and help compare clients and probes. They are not unique device identities and do not reveal Telegram message contents. Observations may contain network addresses, so consider this before sharing them.\n\n<b>retention</b> is the core's in-memory fingerprint bucket window. Default: 10 minutes. The button cycles 5, 10, 30, 60, 180, 360, 720 and 1440 minutes. This is not a user expiry, quota period or a guarantee of file log deletion. Toggling beobachten or changing retention restarts TeleMT.\n\nThe observations button shows the tail of <code>config/telemt/data/beobachten.txt</code>. An empty file may simply mean no relevant connections have arrived. Diagnostics do not improve speed or cover."),
                    $t('Отчёт и диагностика WEB', 'Report and WEB diagnostics') => $t(
                        "При включённом beobachten доступен отчёт: состояние ядра, трафик, пользователи, маскировка, защитные счётчики и WEB. Для данных используется Control API только для чтения на loopback внутри контейнера; наружу открывать его не требуется. API также нужен для квот и Limit IP, даже при выключенном beobachten.\n\n<b>WEB → Диагностика</b> — отдельная настройка: включает события работы браузерного бриджа, полезные при обрывах и выборе транспорта. В боте записываются события жизненного цикла, а захват заголовков, тела и фреймов выключен. Для просмотра отчёта включите также beobachten. После сбора информации диагностику можно выключить.\n\nОтсутствие событий WEB не доказывает отсутствие клиентов: конкретная сборка Telegram может не отправлять эти сведения. При ошибке сначала проверьте текущую версию ядра, DNS и сертификат WEB, затем статус и отчёт.",
                        "With beobachten enabled, the report shows core health, traffic, users, cover, security counters and WEB. It uses a read-only Control API on container loopback; no public API port is needed. Quotas and Limit IP also need this API, even with beobachten disabled.\n\n<b>WEB → Diagnostics</b> separately enables browser bridge events useful for disconnects and transport selection. The bot enables lifecycle events but disables header, body and frame capture. Enable beobachten as well to view the report. Diagnostics can be disabled after investigation.\n\nMissing WEB events do not prove there are no clients: a Telegram build may not emit them. Check the core version, WEB DNS and certificate, then status and the report."),
                ]];
            case 'telemt_limits':
                if (!preg_match('~^([a-f0-9]{12})\.(\d{1,6})\.(direct|[a-f0-9]{12})$~D', $context, $m)) return [];
                return ['TeleMT → ' . $this->i18n('telemt limits'), "/tuc {$m[1]} {$m[2]} {$m[3]} limits", [
                    $t('Квота: объём и сброс', 'Quota and reset') => $t(
                        "Квота относится к одному имени пользователя и суммирует передачу и приём в MTProxy и WEB. Ядро считает переданные данные прокси, а не весь трафик сетевой карты и не только полезные файлы Telegram.\n\nВведите <code>10</code> для 10 GiB или <code>0,5</code> для половины GiB. <code>0</code> отключает квоту. Новый доступ без ограничений. Первое включение квоты и повторное включение после безлимита начинают расход с нуля. Изменение уже действующей квоты сохраняет расход. Например, израсходовано 7 GiB: повышение с 10 до 20 оставляет 13 GiB; снижение до 5 запрещает дальнейший трафик.\n\nБез периода квота действует до ручного сброса; автоматический сброс по дням, неделям или месяцам включается кнопкой «Период сброса квоты». «Сбросить расход» после подтверждения начинает новый период, не меняя размер квоты, IP-лимит и ссылки. Расход сохраняется при смене секрета, отключении пользователя и штатном перезапуске. Изменения переподключают всех пользователей TeleMT.",
                        "A quota belongs to one username and combines uploaded and downloaded proxy data over MTProxy and WEB. It is not the entire network interface traffic or only Telegram file sizes.\n\nEnter <code>10</code> for 10 GiB, <code>0.5</code> for half a GiB, or <code>0</code> for unlimited. New users have no limits. Enabling a quota starts usage from zero; changing an active quota preserves usage. With 7 GiB used, increasing 10 to 20 leaves 13 GiB; lowering it to 5 blocks further traffic.\n\nWithout a period the quota lasts until a manual reset; daily, weekly or monthly automatic resets are set with “Quota reset period”. Confirmed reset starts a new accounting period and preserves limits and links. Usage survives secret rotation, user disable and graceful restart. Changes reconnect all TeleMT users."),
                    $t('Периодический сброс квоты', 'Periodic quota reset') => $t(
                        "Кнопка «Период сброса квоты» появляется, когда квота задана. Варианты: ежедневно — в 00:00 UTC, еженедельно — в понедельник 00:00 UTC, ежемесячно — 1-го числа 00:00 UTC (в Москве это 03:00). Сбрасывается только расход; размер квоты, Limit IP и ссылки не меняются, пользователь с исчерпанной квотой снова подключается.\n\nВключение и смена периода не обнуляют текущий расход: первый сброс будет на ближайшей границе. Ручной «Сбросить расход» начинает учёт заново и не сдвигает календарь. Если сервер был выключен несколько периодов, при запуске применяется один, последний пропущенный сброс. Выключенный пользователь продолжает сбрасываться по календарю, но сброс его не включает. Удаление и создание пользователя с тем же именем начинают учёт с нуля.\n\nВ меню показана дата следующего сброса от ядра. «ядро ещё применяет расписание» — сразу после изменения; «срок наступил» — сброс выполняется; «⚠️ не смогло сохранить» — ядро не записало файл расхода, расход в это время не сбрасывается. Отключение квоты (<code>0</code>) отключает и период, повторное включение квоты восстанавливает прежний выбор. Нужен TeleMT 3.5.15 или новее.",
                        "The “Quota reset period” button appears once a quota is set. Daily resets at 00:00 UTC, weekly on Monday 00:00 UTC, monthly on the 1st at 00:00 UTC. Only usage is reset; the quota size, Limit IP and links stay the same, and a user who ran out reconnects.\n\nEnabling or changing the period keeps current usage: the first reset is at the next boundary. A manual “Reset usage” restarts accounting without shifting the calendar. After several missed periods while the server was down, one latest reset is applied on start. A disabled user still rotates on schedule but is not re-enabled. Deleting and recreating a user with the same name starts from zero.\n\nThe menu shows the next reset reported by the core. “still applying” appears right after a change; “due” means the reset is in progress; “⚠️ could not persist” means the core failed to write the usage file and does not reset meanwhile. Disabling the quota (<code>0</code>) disables the period too; enabling the quota again restores the previous choice. Requires TeleMT 3.5.15 or newer."),
                    $t('Limit IP: адреса и устройства', 'Limit IP: addresses and devices') => $t(
                        "Считаются одновременно активные исходные IP одного пользователя: режим ядра <code>active_window</code>. Несколько соединений с одного IP занимают одно место. После закрытия последнего соединения с этого IP место освобождается. MTProxy и WEB используют общий лимит. <code>0</code> выключает его.\n\nНапример, при лимите <code>2</code> домашняя сеть и мобильная сеть могут работать одновременно; третьему адресу придётся подождать. Это не счётчик устройств: за одним NAT могут быть несколько телефонов; один телефон может использовать IPv4, IPv6 и менять мобильный адрес. Для начала разумнее 2–3, чем 1.\n\nЕсли устройство пропало из сети, не закрыв соединение (смена Wi-Fi на мобильную сеть, обрыв связи), ядро освобождает его адрес примерно через 100 секунд; при лимите <code>1</code> новый адрес этого пользователя всё это время не принимается.\n\nУ WEB адрес фиксируется при создании сессии: смена сети в уже открытой сессии не обязательно займёт новое место. За MTProxy-relay ядро может видеть IP самого relay. Поэтому Limit IP не гарантирует запрет передачи ссылки другому человеку и не заменяет личные доступы. WEB-relay в боте не реализован.",
                        "The core counts concurrent source IPs per user in <code>active_window</code> mode. Connections from the same IP share one slot; the last connection closing frees it. MTProxy and WEB share the limit. <code>0</code> disables it.\n\nWith <code>2</code>, home and mobile networks can connect together; a third address must wait. NAT can hide many devices behind one IP; one phone can use both IPv4 and IPv6 or change mobile addresses. Start with 2–3 rather than 1.\n\nWhen a device drops off the network without closing its connection (Wi-Fi to mobile, lost signal), the core frees its address after about 100 seconds; with a limit of <code>1</code> the user’s new address is refused until then.\n\nWEB records the address when a session is created; moving an existing session may not occupy another slot. MTProxy relays may expose only the relay IP. This is not a reliable device or anti-sharing limit. WEB relay is not implemented."),
                    $t('Сохранение и диагностика', 'Persistence and diagnostics') => $t(
                        "Расход сохраняется при штатной остановке TeleMT и в резервной копии бота. Дополнительно примерно раз в секунду записываются изменившиеся счётчики. При аварийном выключении или SIGKILL возможна потеря расхода после последней успешной записи; это не биллинговая система с гарантией каждого байта.\n\nВ меню показаны текущие данные ядра либо явно отмеченная последняя сохранённая запись. «Обновить» перечитывает значения. Если файл расхода пропал или повреждён, бот не запускает пользователей с квотой с нулевым счётчиком автоматически. Восстановите резервную копию. Не удаляйте <code>config/telemt/data</code> при обновлении.\n\nНужен обновлённый образ TeleMT. Control API доступен только внутри контейнера на loopback и остаётся только для чтения. При отказе применения проверьте контейнер и свободное место; интерфейс покажет ошибку.",
                        "Graceful shutdown and bot backups preserve usage. Changed counters are also checkpointed roughly every second. A crash or SIGKILL can lose traffic after the last successful checkpoint; this is not byte-perfect billing.\n\nThe menu shows live data or an explicitly labelled saved checkpoint. Refresh reloads it. Missing or corrupt state does not silently restart quota users with zero usage: restore a backup. Keep <code>config/telemt/data</code> across updates.\n\nAn updated TeleMT image is required. The Control API stays read-only on container loopback. Check container availability and free disk space if applying changes fails."),
                ]];
            case 'telemt_method':
            case 'telemt_conveyor':
                $setting = substr($topic, strlen('telemt_'));
                return ['TeleMT → WEB', '/telemtWebHttp ' . $setting, [
                    $this->i18n('telemt web ' . $setting) => $this->i18n('telemt web ' . $setting . ' help'),
                ]];
            case 'telemt':
            case 'telemt_carrier':
            case 'telemt_path':
                return ['TeleMT → WEB', match ($topic) { 'telemt_carrier' => '/telemtWebMode', 'telemt_path' => '/telemtWebPath', default => '/telemtWeb' }, [
                    $t('Как выбрать транспорт', 'Choosing a transport') => $t(
                        "<b>Авто · только HTTPS</b> — сначала <code>https-lanes</code>, затем <code>https</code>. Подходит для совместимых Android, Desktop и iOS.\n\n"
                        . "<b>Авто · HTTPS + WebSocket</b> — полный набор: <code>websocket-lanes → websocket → https-lanes → https</code>. Это не режим «только WebSocket»: HTTPS остаётся запасным вариантом. Ваш прежний «полный (WebSocket)» — именно этот режим.\n\n"
                        . "<b>Без подбора · HTTPS</b> — один общий транспорт <code>https</code>, в том числе для iOS-клиентов с поддержкой WEB.\n\n"
                        . "<b>Без подбора · HTTPS Lanes</b> — только <code>https-lanes</code>, без запасного HTTPS. Для iOS не подходит.\n\n"
                        . "В меню ✅ отмечен действующий выбор. Настройка общая для всех WEB-пользователей. Ссылки после смены транспорта остаются прежними; активный TeleMT перезапускается, соединения переподключаются.",
                        "<b>Auto · HTTPS only</b>: <code>https-lanes → https</code>. Supports compatible Android, Desktop and iOS clients.\n\n"
                        . "<b>Auto · HTTPS + WebSocket</b>: <code>websocket-lanes → websocket → https-lanes → https</code>. HTTPS remains the fallback; this is the former full (WebSocket) mode.\n\n"
                        . "<b>Fixed · HTTPS</b>: one <code>https</code> transport, including iOS clients with WEB support.\n\n"
                        . "<b>Fixed · HTTPS Lanes</b>: only <code>https-lanes</code>, with no fallback; incompatible with iOS.\n\n"
                        . "✅ marks the current choice. The setting applies to all WEB users. Links stay valid. Changing the active mode restarts TeleMT and reconnects sessions."),
                    $t('Подбор и совместимость клиентов', 'Negotiation and client compatibility') => $t(
                        "<b>Carrier</b> — способ передачи MTProto внутри HTTPS/WSS. <code>https</code> использует общий обмен HTTPS; варианты <code>-lanes</code> разделяют логические потоки. WebSocket использует постоянное двустороннее соединение, также поверх TLS.\n\n"
                        . "Подбор происходит при создании сессии: совместимый клиент сообщает свои возможности, а TeleMT выбирает из разрешённых вариантов. После начала передачи транспорт этой сессии уже не переключается; для повторного подбора нужна новая сессия. Обучение может менять предпочтение между рабочими вариантами.\n\n"
                        . "Клиент без метаданных подбора сразу получает фиксированный запасной <code>https</code>. Поэтому в обоих режимах «Авто» совместимый iOS работает через HTTPS, даже если Android использует WebSocket. Для iOS с явными метаданными TeleMT тоже ограничивает выбор HTTPS.\n\n"
                        . "Наличие кнопки не добавляет поддержку WEB самому Telegram. Если приложение не понимает <code>tg://webproxy</code>, используйте обычную MTProxy-ссылку. Автоподбор требует TeleMT 3.5.4+.",
                        "A <b>carrier</b> carries MTProto inside HTTPS/WSS. Lane variants separate logical streams; WebSocket maintains a bidirectional TLS connection.\n\n"
                        . "Negotiation happens when a session starts, using explicit client capabilities. Once real data commits a carrier, that session does not switch transports. Learning may adjust preferences between working candidates.\n\n"
                        . "Clients without negotiation metadata use the fixed HTTPS fallback in either Auto mode. WEB-capable iOS clients with explicit metadata are also restricted to HTTPS. Android can use WebSocket at the same time.\n\n"
                        . "Telegram itself must support WEB. Otherwise use a regular MTProxy link. Negotiation requires TeleMT 3.5.4+."),
                    $t('Свой поддомен, HTTPS и маскировка', 'Your subdomain, HTTPS and cover site') => $t(
                        "1. Скопируйте <b>host</b> из меню WEB. Запись DNS этого имени должна указывать на ваш сервер; бот не создаёт запись у DNS-провайдера.\n"
                        . "2. Включите WEB и выполните <b>Настройки → SSL → renew SSL</b>, чтобы сертификат включал этот поддомен.\n"
                        . "3. Откройте <code>https://ваш-поддомен/</code> в браузере: сертификат должен быть действительным, без предупреждений. Без секрета показывается сайт прикрытия.\n\n"
                        . "WEB использует настоящий HTTPS на порту 443. Чужой домен сюда подставлять нельзя: нужен действительный сертификат для вашего имени. Поле <b>fake-TLS domain</b> в настройках TeleMT относится к обычному MTProxy, а не к WEB.\n\n"
                        . "На сервере страницу прикрытия можно заменить в <code>config/telemt/decoy/index.html</code> внутри каталога VPNBot. Используйте обычную статическую страницу с локальными ресурсами; TeleMT загрузит её после перезапуска. Уже существующий файл бот не заменяет.\n\n"
                        . "HTTPS и сайт прикрытия помогают при проверочных запросах, но не скрывают IP сервера и обычно SNI. Гарантии обхода любого DPI нет.",
                        "1. Copy <b>host</b> from WEB settings and point its DNS record to your server. The bot does not register DNS records.\n"
                        . "2. Enable WEB, then use <b>Settings → SSL → renew SSL</b> to include that host in the certificate.\n"
                        . "3. Open its HTTPS address in a browser and verify the certificate. Requests without a valid secret receive the cover site.\n\n"
                        . "WEB uses real HTTPS on port 443. Use your own hostname with a valid certificate. TeleMT's fake-TLS domain belongs to native MTProxy, not WEB.\n\n"
                        . "Replace <code>config/telemt/decoy/index.html</code> in the VPNBot installation with a normal static page and local assets; restart TeleMT to load it. Existing files are preserved. HTTPS does not hide the server IP or usually SNI, and cannot guarantee DPI evasion."),
                    $t('Ссылки и формат секрета', 'Links and secret format') => $this->i18n('telemt web note') . "\n\n" . $t(
                        "Откройте <b>TeleMT → Пользователи → имя пользователя</b>: в карточке находятся обе ссылки, кнопки MTProxy и WEB, а также их QR-коды. Выбранный relay меняет только MTProxy; WEB подключается напрямую к своему HTTPS-поддомену.\n\n"
                        . "<code>dd</code> и <code>plain</code> — форматы секрета; <code>ee</code>/Fake-TLS для WEB не используется. После смены формата выдайте новые ссылки. Возврат к прежнему формату может снова включить соответствующие старые ссылки; для окончательного отзыва смените секрет пользователя. В WEB включаются первые 32 профиля.",
                        "Open <b>TeleMT → Users → user name</b> for both links, MTProxy and WEB buttons and their QR codes. The selected relay affects only MTProxy; WEB connects directly to its HTTPS hostname.\n\n"
                        . "WEB supports dd and plain secrets, not ee/Fake-TLS. Issue new links after changing the format. Restoring a previous format may reactivate matching old links; rotate the user's secret for permanent revocation. WEB includes the first 32 profiles."),
                    $t('Секретный путь path', 'Secret base path') => $this->i18n('telemt web path note') . "\n\n" . $t(
                        "<b>Сгенерировать новый путь</b> создаёт 16 случайных шестнадцатеричных символов, например <code>/a17b24c39d40e56f/</code>. Бот сам записывает base_path и обновляет ссылки 🌐. При включённом WEB TeleMT перезапускается. Повторная генерация сразу заменяет путь новым.\n\n"
                        . "<b>Использовать корень /</b> убирает префикс. Возврат к прежнему пути или к <code>/</code> может снова сделать действительными соответствующие старые ссылки. Для окончательного отзыва доступа смените секрет пользователя.\n\n"
                        . "Не нужно вручную менять nginx, DNS или сертификат: домен и порт 443 остаются прежними. До проверки поддержки пути в вашем Telegram используйте <code>/</code>.",
                        "<b>Generate a new path</b> creates 16 random hexadecimal characters, saves base_path and updates 🌐 links. Active WEB is restarted. Repeating generation replaces the path directly.\n\n"
                        . "<b>Use root /</b> removes the prefix. Restoring an old path or root may reactivate matching old links. Rotate the user's secret for permanent revocation. No nginx, DNS or certificate changes are needed; the hostname and port stay the same. Use root until client path support is verified."),
                    $this->i18n('telemt web method') => $this->i18n('telemt web method help'),
                    $this->i18n('telemt web conveyor') => $this->i18n('telemt web conveyor help'),
                    $t('Telegram для iOS: статус WEB', 'Telegram for iOS: WEB status') => $t(
                        "Проверено 04.10.2026. В репозитории Telegram Desktop описан <a href=\"https://github.com/telegramdesktop/tproxy-server/blob/master/IOS.md\">экспериментальный WEB-клиент для iOS</a> на основе отдельной сборки Telegram. Это подтверждает техническую реализацию, но не выпуск функции в обычном приложении из App Store.\n\nВ <a href=\"https://github.com/TelegramMessenger/Telegram-iOS/blob/6ad963e5b62d354da79040f388ae2b9132fb17b8/submodules/TelegramCore/Sources/SyncCore/SyncCore_ProxySettings.swift\">публичном коде официального iOS-клиента</a> перечислены SOCKS5 и MTProxy; WEB там не обнаружен. Публичный код может отставать от магазинной версии. Подтвердить поддержку WEB в App Store по доступным первичным источникам пока не удалось.\n\nЕсли ваша сборка не распознаёт <code>tg://webproxy</code>, используйте MTProxy-ссылку из карточки пользователя. Если поддержка WEB в конкретной сборке подтверждена, начните с «Без подбора · HTTPS» или «Авто · только HTTPS», POST и пути <code>/</code>. Настройки сервера не добавляют отсутствующую функцию в приложение. Физический iPhone в серверных испытаниях не использовался.",
                        "Checked on 2026-10-04. Telegram Desktop's repository describes an <a href=\"https://github.com/telegramdesktop/tproxy-server/blob/master/IOS.md\">experimental iOS WEB client</a> based on a separate Telegram build. This confirms a technical implementation, not an App Store release.\n\nThe <a href=\"https://github.com/TelegramMessenger/Telegram-iOS/blob/6ad963e5b62d354da79040f388ae2b9132fb17b8/submodules/TelegramCore/Sources/SyncCore/SyncCore_ProxySettings.swift\">public official iOS source</a> lists SOCKS5 and MTProxy, with no WEB type found. Public source can lag store releases. Available primary sources do not yet confirm WEB support in the App Store app.\n\nIf your build does not recognize <code>tg://webproxy</code>, use the user card's MTProxy link. With a confirmed WEB-capable iOS build, start with Fixed HTTPS or Auto HTTPS only, POST and root path <code>/</code>. Server settings cannot add a missing app feature. No physical iPhone was used in server tests."),
                    $t('Диагностика WEB', 'WEB diagnostics') => $this->i18n('telemt web diag note') . "\n\n" . $t(
                        "Диагностика помогает выяснить причину сбоя, но не улучшает маскировку. Для отчёта включите <b>TeleMT → Диагностика → beobachten</b>. Путь и диагностика бриджа требуют TeleMT 3.5.8+.",
                        "Diagnostics explain failures; they do not improve cover. Enable <b>TeleMT → Diagnostics → beobachten</b> for the report. Base paths and bridge diagnostics require TeleMT 3.5.8+."),
                ]];
            case 'telemt_mask':
                return ['TeleMT', '/telemtMasking', [
                    $t('Назначение и значения по умолчанию', 'Purpose and defaults') => $t(
                        "Эти четыре переключателя меняют обработку проверочных подключений на пути к сайту прикрытия обычного MTProxy. Они не фрагментируют трафик авторизованных клиентов и не настраивают WEB: у него отдельный HTTPS-поддомен и своя страница прикрытия. TLS-эмуляция MTProxy уже включена.\n\nПо умолчанию включён только <b>shape hardening</b>; aggressive hardening, above-cap blur и timing normalization выключены. Начните с этого набора. Дополнительные опции изменяют размеры или время проверочного обмена и могут увеличить его трафик или задержку. Гарантии обхода любого DPI нет.\n\nКаждое изменение перезапускает TeleMT и переподключает всех пользователей, включая WEB. Ссылки, секреты и расход сохраняются. Включение aggressive или blur автоматически включает shape hardening; выключение shape hardening отключает оба зависимых параметра. Timing normalization независим.",
                        "These four switches affect native MTProxy probe handling on the cover-site path. They do not fragment authenticated client traffic or configure WEB, which has a separate HTTPS hostname and cover page. MTProxy TLS emulation is already enabled.\n\nOnly <b>shape hardening</b> is enabled by default. Start there; aggressive hardening, above-cap blur and timing normalization are optional and may add probe traffic or delay. No setting guarantees DPI evasion.\n\nChanges restart TeleMT and reconnect all users, including WEB, while preserving links, secrets and usage. Enabling aggressive or blur also enables shape hardening; disabling shape hardening disables both dependent options. Timing normalization is independent."),
                    'shape hardening' => $t(
                        "Дополняет проверочный поток, пересылаемый на сайт прикрытия, до заданных размерных ступеней при штатном завершении. Близкие по длине запросы становятся менее различимыми по размеру. В боте нижняя ступень 512 байт, верхняя 4096 байт.\n\nВключён по умолчанию. В обычном режиме дополнение консервативное: не применяется ко всем вариантам тайм-аута. Цена — небольшой дополнительный исходящий трафик для проверочных запросов. Это не увеличение размера каждого пакета Telegram.",
                        "Pads the forwarded probe stream to size buckets on clean shutdown, making nearby probe sizes less distinguishable. The bot uses a 512-byte floor and a 4096-byte cap.\n\nEnabled by default. Normal mode applies padding conservatively, not to every timeout path. It adds some cover-path egress traffic, not padding to every Telegram packet."),
                    'aggressive hardening' => $t(
                        "Расширяет shape hardening на некоторые незавершённые и истёкшие по тайм-ауту проверочные подключения, если сайт прикрытия ещё не вернул данные. Вместе с above-cap blur добавляет минимум один байт вместо возможного нуля.\n\nПо умолчанию выключен. Делает обработку активных проверок менее консервативной; включайте для сравнения при конкретной проблеме, а не ради обещанного ускорения. Требует shape hardening: бот включит его автоматически.",
                        "Extends shaping to some non-EOF or timed-out probe paths when the cover backend has returned no data. With above-cap blur, it always adds at least one byte.\n\nDisabled by default. This is less conservative probe handling, not a speed feature. Enable to investigate a specific issue. Requires shape hardening, which the bot enables automatically."),
                    'above-cap blur' => $t(
                        "Добавляет случайный хвост к большим проверочным потокам, которые уже превышают верхнюю ступень shape hardening — 4096 байт. В боте хвост до 512 байт: 0–512 обычно, 1–512 при aggressive hardening. Так точная длина крупных проверок становится менее предсказуемой.\n\nПо умолчанию выключен. Увеличивает трафик пути прикрытия в указанных пределах. Требует shape hardening: бот включит его автоматически. Данные авторизованных MTProxy-пользователей этим хвостом не дополняются.",
                        "Adds a random tail to probe streams already above the 4096-byte shaping cap. The bot allows 0–512 extra bytes, or 1–512 with aggressive hardening, making exact oversized probe lengths less predictable.\n\nDisabled by default. Adds bounded cover-path traffic and requires shape hardening, enabled automatically. It does not append this tail to authenticated MTProxy user data."),
                    'timing normalization' => $t(
                        "Сглаживает различия во времени обработки проверочных подключений. Бот задаёт случайную целевую длительность 180–320 мс: быстрый ответ задерживается до выбранной границы. Уже медленное соединение не обрывается на 320 мс.\n\nПо умолчанию выключен. Может затруднить сравнение проверок по времени, но добавляет задержку на пути прикрытия. Не требует shape hardening. Это не регулировка пинга обычных клиентов Telegram.",
                        "Smooths probe timing differences. The bot selects a target duration of 180–320 ms and delays fast outcomes to that target. Already slow connections are not cut off at 320 ms.\n\nDisabled by default. It may make timing comparisons harder at the cost of cover-path delay. Independent of shape hardening; not a latency control for normal Telegram clients."),
                ]];
            case 'dpi':
                return ['Vless → DPI', '/dpiMenu', [
                    $t('Клиентская маскировка', 'Client-side masking') => $this->i18n('dpi hint'),
                    $t('TLS-фрагментация', 'TLS fragmentation') => $this->dpiFieldHint('fragment') . "\n\n" . $this->dpiFieldHint('fragment_maxSplit'),
                    $t('UDP-шум и примеры', 'UDP noise and examples') => $this->dpiFieldHint('noise') . "\n\n" . $this->noiseExamplesHint(),
                    $t('Формат в профилях', 'Format in profiles') => $this->i18n('dpi format help'),
                    'ML-KEM (REALITY)' => $this->i18n('reality require mlkem hint') . "\n\n" . $this->i18n('reality mlkem origin always'),
                ]];
            case 'smux':
                return ['Vless → SMUX', '/smuxMenu', [
                    $t('Назначение и подписки', 'Purpose and subscriptions') => $this->i18n('smux hint') . "\n\n" . $this->i18n('smux link warn') . "\n\n" . $this->i18n('smux sing compatibility'),
                    'half-close' => $this->i18n('smux halfclose hint'),
                    'TCP Brutal' => $this->i18n('smux brutal hint') . "\n\n" . $this->i18n('smux brutal warn'),
                ]];
            case 'finalmask':
                return ['Vless → finalmask', '/finalmaskMenu', [
                    $t('Серверная маскировка', 'Server-side masking') => $this->i18n('finalmask hint') . "\n\n" . $this->i18n('finalmask fragment hint'),
                    $t('UDP-шум, exp и примеры', 'UDP noise, exp and examples') => $this->i18n('finalmask noise hint') . "\n\n" . $this->finalmaskNoiseHint(),
                ]];
            case 'dpi_frag':
            case 'finalmask_frag':
                return ['Vless → ' . $t('Шаблоны фрагментации', 'Fragment presets'), $topic === 'dpi_frag' ? '/dpiFragPresets' : '/finalmaskFragPresets', [$t('Значения шаблонов', 'Preset values') => $this->fragmentPresetsHint()]];
            case 'dpi_noise':
            case 'finalmask_noise':
                return ['Vless → ' . $t('Шаблоны UDP-шума', 'UDP noise presets'), $topic === 'dpi_noise' ? '/dpiNoisePresets' : '/finalmaskNoisePresets', [
                    $t('Формат пакетов и примеры', 'Packet format and examples') => $topic === 'dpi_noise' ? $this->noiseExamplesHint() : $this->finalmaskNoiseHint(),
                    $t('Значения шаблонов', 'Preset values') => $this->noisePresetsHint(),
                ]];
            case 'encryption':
                // Формат и алгоритмы: XTLS/Xray-core v26.9.30,
                // proxy/vless/encryption/{client,server,common}.go; документация VLESS.
                return ['Vless → Encryption', '/vlessEncryption', [
                    $t('Что именно шифруется', 'What is encrypted') => $t(
                        "VLESS Encryption защищает данные между VPN-клиентом и ядром Xray сервера. Ключи сеанса согласуются гибридным обменом ML-KEM-768 + X25519. Данные шифруются с проверкой целостности: изменение зашифрованного блока обнаруживается и соединение прерывается. Шифрование до конечного сайта, например HTTPS, остаётся отдельным уровнем.\n\nИспользуется <b>AES-256-GCM</b> при подходящей аппаратной поддержке клиента либо <b>ChaCha20-Poly1305</b> без неё. AES шифрует блоки, GCM проверяет подлинность; ChaCha20 создаёт поток для шифрования, Poly1305 проверяет подлинность. Выбор выполняет ядро автоматически: отдельных кнопок этих шифров в боте нет.\n\nШесть кнопок — комбинации двух способов проверки сервера и трёх вариантов внешнего вида потока. Они не означают шесть разных шифров данных.",
                        "VLESS Encryption protects data between the VPN client and the server's Xray core. Session keys use a hybrid ML-KEM-768 + X25519 exchange. Authenticated encryption detects modified encrypted records and terminates the connection. End-to-end website encryption such as HTTPS remains a separate layer.\n\nThe core automatically chooses <b>AES-256-GCM</b> with suitable client hardware support or <b>ChaCha20-Poly1305</b> otherwise. AES encrypts blocks and GCM authenticates them; ChaCha20 supplies the encryption stream and Poly1305 authenticates the data. There are no separate cipher buttons in this bot.\n\nThe six buttons combine two server authentication methods with three stream appearances; they are not six different data ciphers."),
                    $t('X25519 и ML-KEM-768', 'X25519 and ML-KEM-768') => $t(
                        "<b>X25519</b> — проверка сервера с ключом на эллиптической кривой. Клиентский параметр короткий: 32 байта до кодирования, поэтому ссылки и QR компактнее. Этот постоянный ключ не рассчитан на защиту от будущего криптографически значимого квантового компьютера.\n\n<b>ML-KEM-768</b> — проверка сервера с постквантовым механизмом инкапсуляции ключа. Клиентский открытый параметр значительно больше: 1184 байта до кодирования. Ссылки и QR длиннее; нужен клиент с поддержкой этого формата. Назначение — в том числе противодействовать будущему квантовому восстановлению секрета сервера по клиентскому параметру. Это не гарантия безопасности при краже самого секрета.\n\nВ <b>обоих</b> вариантах обмен временными ключами сеанса остаётся гибридным ML-KEM-768 + X25519. Переключатель меняет постоянную проверку сервера, а не убирает ML-KEM из обмена ключами. UUID пользователя также сохраняет свою роль контроля доступа.",
                        "<b>X25519</b> authenticates the server using an elliptic-curve key. Its client parameter is 32 bytes before encoding, keeping links and QR codes shorter. This persistent key is not designed to resist a future cryptographically relevant quantum computer.\n\n<b>ML-KEM-768</b> authenticates the server using post-quantum key encapsulation. The public client parameter is 1184 bytes before encoding, making links and QR codes larger. A compatible client is required. One purpose is to resist future quantum recovery of the server secret from the client parameter; it does not protect a stolen server secret.\n\n<b>Both</b> options still exchange ephemeral session keys using hybrid ML-KEM-768 + X25519. This setting changes persistent server authentication, not the hybrid exchange. The user's UUID continues to control access."),
                    'native' => $t(
                        "<b>X25519 / native</b> и <b>ML-KEM-768 / native</b> используют исходный формат VLESS Encryption без дополнительного скрытия открытых параметров обмена. Содержимое по-прежнему защищено AES-GCM или ChaCha20-Poly1305.\n\nВ записях есть заголовки, похожие на TLS. Сам по себе native не превращает соединение в настоящий HTTPS и не даёт сертификат сайта. Это исходный режим для проверки совместимости; устойчивость к фильтрации зависит также от транспорта и сети.",
                        "<b>X25519 / native</b> and <b>ML-KEM-768 / native</b> retain the original VLESS Encryption format without additional masking of public handshake parameters. Data is still protected by AES-GCM or ChaCha20-Poly1305.\n\nRecords contain TLS-like headers. Native alone does not create genuine HTTPS or a website certificate. It is the baseline appearance for compatibility checks; filtering resistance also depends on the transport and network."),
                    'xorpub' => $t(
                        "<b>X25519 / xorpub</b> и <b>ML-KEM-768 / xorpub</b> дополнительно маскируют открытые части обмена ключами. Это меняет узнаваемый вид начала соединения; шифрование данных остаётся тем же, что в native.\n\nМаскировка выводится из параметров подключения. Получивший профиль может её снять; это не дополнительный секретный шифр и не защита скомпрометированного профиля. В остальной части потока сохраняется исходное обрамление. Клиент и сервер должны выбрать одинаковый режим.",
                        "<b>X25519 / xorpub</b> and <b>ML-KEM-768 / xorpub</b> additionally mask public parts of the key exchange, changing the connection's initial appearance. Data encryption stays the same as native.\n\nMasking is derived from connection parameters. Someone with the profile can reverse it; this is not an extra secret data cipher or protection for a compromised profile. The remaining stream keeps its original framing. Client and server modes must match."),
                    'random' => $t(
                        "<b>X25519 / random</b> и <b>ML-KEM-768 / random</b> маскируют и открытые части обмена, и дальнейшее обрамление потока. Снаружи поток имеет случайный вид, без исходных узнаваемых заголовков native. Проверка целостности и основной шифр данных не меняются.\n\nРежим не имитирует обычный сайт HTTPS. Случайный поток тоже может фильтроваться сетью; обещать обход любого DPI нельзя. Сравнивайте режимы на своей сети, сохраняя одинаковую настройку на клиенте и сервере.",
                        "<b>X25519 / random</b> and <b>ML-KEM-768 / random</b> mask both public handshake parts and the subsequent stream framing. The wire stream looks random instead of retaining native's recognizable headers. Data encryption and integrity checks remain unchanged.\n\nThis does not imitate a normal HTTPS website. Networks may filter random-looking streams too; no mode guarantees DPI evasion. Compare modes on your network and keep client and server settings identical."),
                    $t('0-RTT, билеты и padding', '0-RTT, tickets and padding') => $t(
                        "Бот генерирует серверный параметр <code>600s</code> и клиентский <code>0rtt</code>. Сервер выдаёт билет возобновления со случайным сроком 300–600 секунд. При действительном сохранённом билете клиент может отправить данные без полного повторного обмена ключами, сокращая задержку подключения. Первое соединение требует обычного обмена; 0-RTT не означает нулевой ping или постоянно большую скорость.\n\nPadding — добавочные случайные байты и возможные короткие паузы при установлении соединения, скрывающие часть признаков длины. Бот оставляет штатное поведение ядра. Это расходует немного трафика и может увеличить стартовую задержку. Отдельных переключателей срока билета, 0-RTT и padding в этом меню нет.",
                        "The bot generates server parameter <code>600s</code> and client parameter <code>0rtt</code>. The server issues a resumption ticket valid for a random 300–600 seconds. With a valid cached ticket, the client can send data without a full new key exchange, reducing setup latency. The first connection still needs a normal handshake; 0-RTT does not mean zero ping or higher sustained throughput.\n\nPadding adds random bytes and possible short setup delays to obscure length patterns. The bot retains core defaults. This consumes extra traffic and may increase initial latency. Ticket lifetime, 0-RTT and padding have no separate controls in this menu."),
                    $t('Клиенты, смена ключа и выключение', 'Clients, key rotation and disabling') => $t(
                        "Нужен клиент, поддерживающий именно VLESS Encryption: совместимые версии Xray или Mihomo. Официальный sing-box, для которого бот формирует подписки, этот параметр не поддерживает; бот сообщает о несовместимости вместо выдачи нерабочего профиля. Название приложения само по себе не гарантирует поддержку — важна версия его ядра.\n\nПосле включения, выключения, выбора другого режима или смены ключа обновите подписки либо заново импортируйте профили. «Сменить ключ» заменяет ключ VLESS Encryption для всех пользователей этого входа; старые профили перестают подключаться. UUID пользователей и ключи REALITY — отдельные параметры.\n\nВыключение убирает только слой VLESS Encryption, сохраняя настройки TLS/REALITY выбранного транспорта. Для Trojan/gRPC эта настройка не применяется. Проверка конфигурации перед сохранением отклоняет неподдерживаемую ядром комбинацию.",
                        "Use a client that specifically supports VLESS Encryption, such as compatible Xray or Mihomo releases. Official sing-box targeted by the bot's exports does not support this parameter; the bot reports incompatibility instead of exporting a broken profile. The application's name alone is insufficient: its core version matters.\n\nRefresh subscriptions or re-import profiles after enabling, disabling, changing mode or rotating keys. Rotate key replaces the VLESS Encryption key for every user on this inbound; old profiles stop connecting. User UUIDs and REALITY keys are separate settings.\n\nDisabling removes only VLESS Encryption while preserving the transport's TLS/REALITY settings. This setting does not apply to Trojan/gRPC. Configuration validation rejects combinations unsupported by the selected core."),
                ]];
            case 'hy':
                return ['Hysteria', '/menu hy', [
                    $t('Протокол и подключение', 'Protocol and connection') => $t(
                        "Hysteria 2 работает поверх QUIC, то есть по <b>UDP</b>. Он хорошо держит скорость на каналах с потерями и большой задержкой — мобильная сеть, дальний сервер. Если провайдер пользователя блокирует или сильно режет UDP, Hysteria работать не будет: тогда нужен другой протокол бота.\n\n<b>Что показывает меню.</b> Версию ядра, адрес и порт сервера, общий пароль, сайт маскировки, состояние обфускации, режим скорости (cc), флаг insecure, смену портов и готовую ссылку <code>hysteria2://…</code>.\n\n<b>Как подключить устройство.</b> Скопируйте ссылку из меню либо выдайте пользователю персональную (раздел «Персональные доступы»: ссылка файлом или QR). Ссылку понимают официальный клиент Hysteria и большинство приложений с поддержкой Hysteria 2. В ссылке уже есть адрес, порт, пароль, имя сервера для TLS и параметры обфускации.\n\n<b>Сертификат.</b> Клиент проверяет сертификат сервера по домену бота. Если домена нет и сертификат самоподписанный, включите <b>insecure</b> — в ссылку добавится разрешение не проверять сертификат. Это снижает защиту от подмены сервера, поэтому с настоящим доменом и сертификатом insecure должен быть выключен. На сам сервер кнопка не влияет, меняется только ссылка.\n\nЛюбое изменение настроек перезапускает ядро: активные соединения переподключатся сами.",
                        "Hysteria 2 runs over QUIC, that is over <b>UDP</b>. It keeps speed well on lossy, high-latency links such as mobile networks or a distant server. If the user's provider blocks or heavily throttles UDP, Hysteria will not work; use another protocol of the bot then.\n\n<b>What the menu shows.</b> The core version, server address and port, shared password, masquerade site, obfuscation state, speed mode (cc), the insecure flag, port hopping and a ready <code>hysteria2://…</code> link.\n\n<b>How to connect a device.</b> Copy the link from the menu or give the user a personal one (Personal access section: link as a file or QR). The link works in the official Hysteria client and most apps with Hysteria 2 support. It already contains the address, port, password, TLS server name and obfuscation parameters.\n\n<b>Certificate.</b> The client verifies the server certificate against the bot's domain. If there is no domain and the certificate is self-signed, turn on <b>insecure</b>: the link then allows skipping certificate verification. This weakens protection against a spoofed server, so with a real domain and certificate keep insecure off. The button does not affect the server, only the link.\n\nAny settings change restarts the core: active connections reconnect by themselves."),
                    $t('Общий пароль и персональные доступы', 'Shared password and personal access') => $t(
                        "<b>Общий пароль</b> — один на всех: кто знает ссылку из главного меню, тот подключается. Его нельзя ограничить по сроку или трафику, а отозвать у одного человека можно, только сменив пароль всем. «Сменить пароль» задаёт свой, «Сгенерировать пароль» создаёт случайный; после смены старая ссылка перестаёт работать у всех.\n\n<b>Персональные доступы</b> — отдельная запись на каждого пользователя со своей ссылкой и QR. В карточке пользователя:\n• <b>Имя</b> — подпись для вас.\n• <b>Срок</b> — дата и время в UTC, после которых доступ закрывается; <code>0</code> снимает ограничение.\n• <b>Квота</b> — общий объём переданного и принятого трафика в GiB (например <code>10</code> или <code>0,5</code>); <code>0</code> — без ограничения. Карточка показывает остаток.\n• <b>Выключить / Включить</b> — временно закрыть доступ, не удаляя запись.\n• <b>Сменить реквизиты</b> — новый пароль этому пользователю: старая ссылка перестаёт работать, остальных это не касается.\n• <b>Сбросить расход</b> — начать учёт квоты с нуля.\n• <b>Календарь и уведомления</b> — автоматический сброс расхода по периодам и предупреждения о расходе и окончании срока.\n• <b>Удалить</b> — отозвать доступ совсем.\n\n«Групповые действия» меняют срок, квоту или состояние сразу у нескольких пользователей.\n\nСсылка и QR не выдаются, если доступ выключен, срок истёк или квота исчерпана.\n\n<b>Как перейти на персональные доступы.</b> Создайте каждому пользователю запись, раздайте ссылки, убедитесь, что все подключились, и нажмите «Отключить общий пароль». Действие требует подтверждения: после него общая ссылка перестаёт работать.\n\nПерсональным доступам нужен обновлённый образ Hysteria. Резервная копия бота сохраняет пользователей, ограничения и накопленный расход.",
                        "The <b>shared password</b> is one for everyone: whoever knows the link from the main menu can connect. It cannot be limited by time or traffic, and it can be revoked from one person only by changing it for everyone. Change password sets your own, Generate password creates a random one; after a change the old link stops working for everyone.\n\n<b>Personal access</b> is a separate entry per user with its own link and QR. In the user card:\n• <b>Name</b>: a label for you.\n• <b>Expiry</b>: date and time in UTC after which access closes; <code>0</code> removes the limit.\n• <b>Quota</b>: total sent and received traffic in GiB (e.g. <code>10</code> or <code>0.5</code>); <code>0</code> means unlimited. The card shows what remains.\n• <b>Disable / Enable</b>: temporarily close access without deleting the entry.\n• <b>Change credentials</b>: a new password for this user; the old link stops working, others are not affected.\n• <b>Reset usage</b>: start counting the quota from zero.\n• <b>Calendar and notifications</b>: automatic periodic usage reset and warnings about usage and expiry.\n• <b>Delete</b>: revoke access completely.\n\nBulk actions change expiry, quota or state for several users at once.\n\nThe link and QR are not issued if access is disabled, expired or the quota is used up.\n\n<b>How to move to personal access.</b> Create an entry for each user, hand out the links, make sure everyone has connected, and tap Disable shared password. The action needs confirmation: after it the shared link stops working.\n\nPersonal access needs an updated Hysteria image. The bot backup keeps the users, limits and accumulated usage."),
                    $t('Маскировка под сайт', 'Website masquerade') => $t(
                        "Сервер Hysteria слушает UDP-порт. Если к нему обращается не клиент с правильным паролем, а сканер или провайдер, сервер должен ответить как обычный сайт — иначе по ответу видно, что здесь прокси.\n\n<b>Маскировка</b> задаёт сайт, который увидит такой посторонний: сервер молча пересылает его запросы на выбранный сайт и возвращает ответ, как будто он сам этот сайт.\n\n<b>Как выбрать.</b> Откройте «маскировка» и выберите сайт из списка либо задайте свой («custom»). Берите настоящий крупный сторонний сайт, который открывается по HTTPS. Указывать собственный домен или IP сервера — слабая маскировка: посторонний получит ваш же сервер. Ответ <code>0</code> в «custom» возвращает домен бота.\n\n<b>Чего маскировка не делает.</b>\n• Не меняет имя сервера в клиентской ссылке — клиент по-прежнему проверяет сертификат вашего домена.\n• Не скрывает сам факт UDP-трафика большого объёма на ваш сервер.\n• Не действует при включённой обфускации: с ней сервер вообще не отвечает как сайт HTTP/3, и посторонний видит только шум.\n\nКлиентам после смены сайта маскировки ничего менять не нужно.",
                        "The Hysteria server listens on a UDP port. If it is contacted not by a client with the right password but by a scanner or the provider, the server must answer like an ordinary website, otherwise the response reveals a proxy.\n\n<b>Masquerade</b> sets the site such a stranger sees: the server silently forwards their requests to the chosen site and returns the response as if it were that site.\n\n<b>How to choose.</b> Open masquerade and pick a site from the list or set your own (custom). Use a real large third-party site served over HTTPS. Your own domain or the server IP is a weak masquerade: the stranger just gets your server. Answering <code>0</code> in custom restores the bot's domain.\n\n<b>What masquerade does not do.</b>\n• It does not change the server name in the client link: the client still verifies your domain's certificate.\n• It does not hide the fact of heavy UDP traffic to your server.\n• It has no effect with obfuscation on: then the server does not answer as an HTTP/3 site at all and a stranger sees only noise.\n\nClients do not need to change anything after the masquerade site changes."),
                    $t('Обфускация и скорость', 'Obfuscation and speed') => $t(
                        "<b>obfs</b> — обфускация. Без неё трафик Hysteria выглядит как HTTP/3. Если провайдер блокирует именно QUIC или HTTP/3, включите obfs: пакеты превращаются в случайный на вид шум. Бот создаёт пароль обфускации и добавляет его в ссылку; он общий для всех пользователей. «Пароль obfs» создаёт новый.\n\nВключение, выключение и смена пароля обфускации требуют <b>новой ссылки у каждого клиента</b>: со старой соединение не установится. При выключении бот запоминает пароль и вернёт его при повторном включении. Способ обфускации (salamander или gecko) выбирается в «Тонких настройках».\n\n<b>cc</b> — как сервер управляет скоростью.\n• По умолчанию работает BBR: сервер сам подстраивается под канал. Подходит большинству.\n• Если нажать <b>cc</b> и ввести два числа — скорость отдачи и приёма в Мбит/с, например <code>200 200</code>, — включается <b>Brutal</b>: сервер и клиент держат заданную скорость, не снижая её при потерях. Помогает на перегруженных каналах, где BBR заметно проседает. Числа должны соответствовать реальной скорости канала сервера: завышенные значения вызовут потери и ухудшат связь всем.\n• Ответ <code>0</code> возвращает BBR.\n\nBrutal заработает только у клиентов, которые указали свою скорость в приложении; остальные продолжат работать на BBR.\n\nВыбор профиля BBR, компенсация потерь Brutal и запрет клиентам заявлять свою скорость находятся в «Тонких настройках» — у них своя справка.",
                        "<b>obfs</b> is obfuscation. Without it Hysteria traffic looks like HTTP/3. If the provider blocks QUIC or HTTP/3 specifically, turn obfs on: packets become random-looking noise. The bot creates an obfuscation password and adds it to the link; it is shared by all users. obfs password creates a new one.\n\nEnabling, disabling and changing the obfuscation password require <b>a new link for every client</b>: the old one will not connect. When disabled, the bot remembers the password and restores it when re-enabled. The obfuscation method (salamander or gecko) is chosen in Fine tuning.\n\n<b>cc</b>: how the server controls speed.\n• BBR works by default: the server adapts to the link by itself. It suits most cases.\n• If you tap <b>cc</b> and enter two numbers, upload and download speed in Mbit/s such as <code>200 200</code>, <b>Brutal</b> turns on: the server and client hold the given speed without slowing down on losses. It helps on congested links where BBR drops noticeably. The numbers must match the real speed of the server link: inflated values cause losses and make things worse for everyone.\n• Answering <code>0</code> restores BBR.\n\nBrutal only works for clients that set their own speed in the app; the rest keep using BBR.\n\nThe BBR profile, Brutal loss compensation and forbidding clients to declare their speed are in Fine tuning, which has its own help."),
                    $t('Смена портов (port hopping)', 'Port hopping') => $t(
                        "Некоторые провайдеры замедляют или блокируют UDP-соединение, которое долго и активно идёт на один порт. <b>Смена портов</b> заставляет клиента регулярно переходить с порта на порт внутри заданного диапазона, так что блокировка по одному порту перестаёт работать.\n\n<b>Как включить.</b>\n1. Нажмите «port hopping» и введите диапазон, например <code>20000-50000</code>. Можно перечислить несколько портов и диапазонов через запятую: <code>1234,5000-6000</code>.\n2. Бот покажет готовое правило <b>nft</b>. Его нужно добавить в firewall сервера самостоятельно: бот не управляет firewall хоста. Правило перенаправляет весь диапазон на настоящий порт Hysteria.\n3. Раздайте пользователям новые ссылки — в них вместо одного порта теперь записан диапазон.\n\nБез правила firewall смена портов работать не будет: клиент станет стучаться в порты, на которых никто не слушает. Правило можно показать ещё раз кнопкой «nft rule».\n\n<b>Что важно.</b>\n• Сам сервер продолжает слушать один порт, его настройки не меняются — поэтому перезапуск не нужен.\n• Диапазон в ссылке и в правиле firewall должен совпадать. Изменили диапазон — обновите и правило, и ссылки.\n• Порты диапазона не должны быть заняты другими сервисами сервера.\n• Клиент должен поддерживать диапазон портов в ссылке; официальный клиент Hysteria поддерживает.\n\n<b>Как выключить.</b> Ответьте <code>0</code> на запрос диапазона, удалите правило из firewall и раздайте ссылки с одним портом.",
                        "Some providers slow down or block a UDP connection that runs long and busy to one port. <b>Port hopping</b> makes the client regularly move from port to port within a given range, so blocking a single port stops working.\n\n<b>How to enable.</b>\n1. Tap port hopping and enter a range, e.g. <code>20000-50000</code>. Several ports and ranges can be listed with commas: <code>1234,5000-6000</code>.\n2. The bot shows a ready <b>nft</b> rule. Add it to the server firewall yourself: the bot does not manage the host firewall. The rule redirects the whole range to the real Hysteria port.\n3. Hand out new links to users: they now contain the range instead of one port.\n\nWithout the firewall rule port hopping does not work: the client will knock on ports where nobody listens. The rule can be shown again with the nft rule button.\n\n<b>What matters.</b>\n• The server itself keeps listening on one port and its settings do not change, so no restart is needed.\n• The range in the link and in the firewall rule must match. Changed the range? Update both the rule and the links.\n• Ports of the range must not be used by other services on the server.\n• The client must support a port range in the link; the official Hysteria client does.\n\n<b>How to disable.</b> Answer <code>0</code> to the range prompt, remove the rule from the firewall and hand out links with a single port."),
                    $t('Подключение через relay', 'Connecting through a relay') => $t(
                        "Relay — промежуточный сервер, через который клиент подключается к вашему. Он нужен, когда адрес основного сервера у пользователя заблокирован или до него плохой маршрут, а до relay — хороший.\n\n<b>Как это устроено.</b> Relay ничего не расшифровывает: он просто пересылает UDP-пакеты на основной сервер. Пароль, сертификат и обфускация остаются от основного сервера, поэтому relay не видит содержимое трафика.\n\n<b>Как настроить.</b>\n1. Relay добавляются в меню VLESS (xray). В карточке relay задайте адрес Hysteria и при необходимости порт или соответствие портов.\n2. На самом relay настройте перенаправление UDP-порта Hysteria на основной сервер. Если включена смена портов — перенаправить нужно весь диапазон.\n3. В меню Hysteria появится кнопка «relay»: выберите relay и получите ссылку, в которой адрес и порт заменены на адрес relay.\n\n<b>Порты.</b> Если в карточке relay явно задан порт Hysteria, в ссылке будет только он, даже когда на основном сервере включена смена портов. Если задано соответствие портов, одиночные порты заменяются по нему, а диапазоны остаются как есть — relay должен перенаправлять тот же диапазон.\n\nКнопка «relay» видна, только когда хотя бы у одного relay задан адрес Hysteria. Имя сервера для проверки сертификата в такой ссылке остаётся доменом основного сервера.",
                        "A relay is an intermediate server through which the client connects to yours. It is needed when the main server's address is blocked for the user or has a poor route, while the relay has a good one.\n\n<b>How it works.</b> The relay decrypts nothing: it just forwards UDP packets to the main server. The password, certificate and obfuscation are those of the main server, so the relay cannot see the traffic contents.\n\n<b>How to set up.</b>\n1. Relays are added in the VLESS (xray) menu. In the relay card set the Hysteria address and, if needed, the port or a port map.\n2. On the relay itself forward the Hysteria UDP port to the main server. With port hopping on, forward the whole range.\n3. A relay button appears in the Hysteria menu: pick a relay and get a link where the address and port are replaced with the relay's.\n\n<b>Ports.</b> If the relay card sets a Hysteria port explicitly, the link contains only that port, even when port hopping is on at the main server. If a port map is set, single ports are replaced through it while ranges stay as they are, so the relay must forward the same range.\n\nThe relay button is visible only when at least one relay has a Hysteria address. The server name used for certificate verification in such a link stays the main server's domain."),
                    $t('Диагностика, config и неполадки', 'Diagnostics, config and troubleshooting') => $t(
                        "<b>Диагностика</b> проверяет состояние сервиса Hysteria и показывает, что именно не в порядке. <b>config</b> присылает текущую конфигурацию сервера отдельным сообщением — в ней видны все действующие параметры. В конфигурации есть пароли: не пересылайте её посторонним.\n\n<b>Никто не подключается.</b>\n• Проверьте строку server: если вместо порта написано, что порт недоступен, Hysteria выключена или её порт не опубликован.\n• UDP-порт должен быть открыт в firewall сервера и у хостинга. Hysteria не работает по TCP.\n• После смены пароля, обфускации или диапазона портов у клиентов должны быть новые ссылки.\n\n<b>Не подключается один пользователь.</b>\n• Его провайдер может блокировать UDP — проверьте другую сеть (например, мобильную).\n• У персонального доступа проверьте срок, квоту и что он включён.\n• Ошибка сертификата в приложении: домен бота не совпадает с сертификатом либо сертификат самоподписанный. Нужен действующий сертификат на домен или включённый insecure.\n\n<b>Подключается, но медленно или рвётся.</b>\n• При заданной полосе (cc: brutal) проверьте, что числа не выше реальной скорости канала.\n• Попробуйте включить смену портов или обфускацию — провайдер может замедлять распознанный трафик.\n• В «Тонких настройках» можно сменить профиль BBR.\n\n<b>Не открываются внутренние адреса.</b> Это намеренно: клиентам Hysteria закрыт доступ к служебным адресам сервера и частным сетям. DNS-запросы идут через AdGuard бота.\n\n<b>После обновления бота.</b> Настройки, пароли, обфускация и ссылки сохраняются; новая версия ядра показана в первой строке меню.",
                        "<b>Diagnostics</b> checks the state of the Hysteria service and shows what exactly is wrong. <b>config</b> sends the current server configuration as a separate message, with all active parameters. The configuration contains passwords: do not forward it to others.\n\n<b>Nobody connects.</b>\n• Check the server line: if it says the port is unavailable instead of showing the port, Hysteria is off or its port is not published.\n• The UDP port must be open in the server firewall and at the hosting provider. Hysteria does not work over TCP.\n• After changing the password, obfuscation or port range clients need new links.\n\n<b>One user cannot connect.</b>\n• Their provider may block UDP: try another network (mobile, for example).\n• For personal access check the expiry, quota and that it is enabled.\n• A certificate error in the app: the bot's domain does not match the certificate or the certificate is self-signed. A valid certificate for the domain or insecure turned on is required.\n\n<b>Connects, but slow or drops.</b>\n• With a fixed bandwidth (cc: brutal) check that the numbers do not exceed the real link speed.\n• Try port hopping or obfuscation: the provider may slow down recognised traffic.\n• The BBR profile can be changed in Fine tuning.\n\n<b>Internal addresses do not open.</b> This is intentional: Hysteria clients cannot reach the server's service addresses and private networks. DNS queries go through the bot's AdGuard.\n\n<b>After a bot update.</b> Settings, passwords, obfuscation and links are kept; the new core version is shown in the first line of the menu."),
                ]];
            case 'hy_tune':
                return ['Hysteria → ' . $this->i18n('hy tune'), '/hyTune', [
                    $t('Что здесь настраивается', 'What is configured here') => $t(
                        "В «Тонких настройках» собраны параметры ядра Hysteria, которые меняют поведение сервера: чем маскировать трафик, как делить канал между пользователями и как фильтровать запросы.\n\nКаждая кнопка сразу применяет настройку: бот записывает конфигурацию и ядро перезапускается, активные соединения Hysteria переподключатся сами. Если конфигурацию записать не удалось, настройка возвращается к прежнему значению и меню сообщает об этом.\n\n<b>Что нужно менять у клиентов.</b> Только тип обфускации — он записан в ссылке, поэтому после его смены каждому пользователю нужна новая ссылка или QR. Остальные четыре настройки серверные: ссылки и приложения остаются прежними.\n\n<b>С чего начать.</b> Если всё работает — ничего менять не нужно, значения по умолчанию подходят большинству. Настройки стоит трогать, когда есть конкретная причина: провайдер режет Hysteria, скорость «плавает» или нужна фильтрация AdGuard.",
                        "Fine tuning collects Hysteria core parameters that change server behaviour: how traffic is disguised, how the link is shared between users and how requests are filtered.\n\nEach button applies the setting at once: the bot writes the configuration and the core restarts; active Hysteria connections reconnect by themselves. If the configuration could not be written, the setting returns to its previous value and the menu says so.\n\n<b>What clients must change.</b> Only the obfuscation type: it is part of the link, so after changing it every user needs a new link or QR. The other four settings are server-side: links and apps stay the same.\n\n<b>Where to start.</b> If everything works, change nothing: the defaults suit most cases. Touch these settings when there is a specific reason: the provider cuts Hysteria, speed fluctuates or AdGuard filtering is needed."),
                    $t('Обфускация: salamander и gecko', 'Obfuscation: salamander and gecko') => $t(
                        "Без обфускации Hysteria выглядит как обычный HTTP/3. Если провайдер блокирует именно QUIC или HTTP/3, включите <b>obfs</b> в главном меню Hysteria — пакеты станут похожи на случайный шум. Пароль обфускации общий для всех пользователей и входит в ссылку.\n\nКнопка <b>obfs: …</b> в этом меню выбирает способ:\n\n• <b>salamander</b> — проверенный вариант, его понимают официальный клиент Hysteria и большинство сторонних приложений. Выбирайте его по умолчанию.\n\n• <b>gecko</b> — экспериментальный: кроме шума, дробит первые пакеты соединения на куски случайного размера. Помогает там, где провайдер распознаёт рукопожатие даже под salamander. Работает только с ядром 2.9.2+ и <b>только с официальным клиентом Hysteria 2.9.2 или новее</b>; сторонние приложения могут его не знать.\n\n<b>Как применять.</b> Смените тип, затем выдайте всем пользователям новые ссылки: со старой ссылкой соединение не установится вообще. Перед переводом всех на gecko проверьте его на одном своём устройстве. Вернуться на salamander можно той же кнопкой — и снова раздать ссылки.\n\nКнопки нет, пока обфускация выключена. С включённой обфускацией сервер перестаёт отвечать как обычный сайт HTTP/3.",
                        "Without obfuscation Hysteria looks like ordinary HTTP/3. If the provider blocks QUIC or HTTP/3 specifically, turn on <b>obfs</b> in the main Hysteria menu: packets will look like random noise. The obfuscation password is shared by all users and is part of the link.\n\nThe <b>obfs: …</b> button in this menu selects the method:\n\n• <b>salamander</b> is the proven option, understood by the official Hysteria client and most third-party apps. Choose it by default.\n\n• <b>gecko</b> is experimental: besides noise, it splits the first packets of a connection into pieces of random size. It helps where the provider recognises the handshake even under salamander. It works only with core 2.9.2+ and <b>only with the official Hysteria client 2.9.2 or newer</b>; third-party apps may not know it.\n\n<b>How to apply.</b> Change the type, then give all users new links: with the old link the connection will not be established at all. Before moving everyone to gecko, test it on one of your own devices. You can return to salamander with the same button, and hand out links again.\n\nThe button is hidden while obfuscation is off. With obfuscation on the server no longer answers like an ordinary HTTP/3 site."),
                    $t('Контроллер перегрузки (cc)', 'Congestion controller (cc)') => $t(
                        "Контроллер решает, с какой скоростью сервер отправляет данные и как реагирует на потери пакетов. Кнопка <b>cc: …</b> переключает варианты по кругу:\n\n• <b>bbr</b> — стандартный, подходит почти всегда.\n• <b>bbr-conservative</b> — осторожнее набирает скорость и мягче к остальному трафику на том же канале. Пробуйте, если на сервере много пользователей и они мешают друг другу.\n• <b>bbr-aggressive</b> — напористее держит скорость при потерях. Пробуйте на канале с потерями, когда скорость ниже ожидаемой; расход трафика и нагрузка на канал вырастут.\n• <b>reno</b> — классический алгоритм: при потере резко сбрасывает скорость. Нужен редко — когда важнее не мешать соседям, чем скорость.\n\nНастройка серверная: у клиентов ничего менять не нужно, достаточно переподключения.\n\n<b>Когда она не действует.</b> Если в главном меню задана полоса (cc: brutal), скоростью управляет Brutal, а выбранный здесь контроллер остаётся запасным — он включается, когда клиент не сообщил свою полосу или включено «Игнорировать полосу клиента».\n\nМеняйте по одному шагу и сравнивайте скорость на одном и том же устройстве и сети: универсально лучшего варианта нет.",
                        "The controller decides how fast the server sends data and how it reacts to packet loss. The <b>cc: …</b> button cycles through the options:\n\n• <b>bbr</b>: the standard one, fits almost always.\n• <b>bbr-conservative</b>: ramps up more carefully and is gentler to other traffic on the same link. Try it if the server has many users who get in each other's way.\n• <b>bbr-aggressive</b>: holds speed more assertively under loss. Try it on a lossy link when speed is below expectations; traffic use and link load will grow.\n• <b>reno</b>: the classic algorithm that cuts speed sharply on loss. Rarely needed: when not disturbing neighbours matters more than speed.\n\nThe setting is server-side: clients need nothing but a reconnect.\n\n<b>When it has no effect.</b> If a bandwidth is set in the main menu (cc: brutal), Brutal controls the speed, and the controller chosen here is the fallback: it is used when the client did not report its bandwidth or Ignore client bandwidth is on.\n\nChange one step at a time and compare speed on the same device and network: there is no universally best option."),
                    $t('Brutal: компенсация потерь и полоса клиента', 'Brutal: loss compensation and client bandwidth') => $t(
                        "Brutal — режим, в котором сервер и клиент не подстраиваются под канал, а держат заданную скорость. Он включается, когда в главном меню задана полоса (кнопка cc → два числа в Мбит/с) и клиент указал свою.\n\n<b>Компенсация потерь Brutal.</b> По умолчанию включена: при потере пакетов Brutal шлёт немного быстрее заданного, чтобы итоговая скорость осталась прежней. На плохом канале это может усилить потери и сделать скорость рваной. Если с заданной полосой скорость «скачет» или соединение рвётся — выключите компенсацию и сравните. Настройка действует только при заданной полосе; без неё кнопка ничего не меняет.\n\n<b>Игнорировать полосу клиента.</b> По умолчанию выключено: клиент сам сообщает, какую скорость хочет, и сервер ему верит. Пользователь может вписать завышенное значение и занять канал в ущерб остальным. Включите эту настройку, если доступ выдаётся другим людям: сервер перестанет учитывать заявленную полосу и будет использовать выбранный контроллер (cc) для всех одинаково.\n\nОбе настройки серверные, клиентам менять ничего не нужно.\n\nУчтите: при включённом «Игнорировать полосу клиента» Brutal не используется вовсе, поэтому заданная в главном меню полоса перестаёт работать как режим скорости.",
                        "Brutal is a mode in which the server and client do not adapt to the link but hold a given speed. It turns on when a bandwidth is set in the main menu (cc button → two numbers in Mbit/s) and the client has set its own.\n\n<b>Brutal loss compensation.</b> On by default: on packet loss Brutal sends a bit faster than set so that the resulting speed stays the same. On a poor link this may increase losses and make speed choppy. If speed jumps or the connection drops with a set bandwidth, turn compensation off and compare. The setting applies only with a set bandwidth; without one the button changes nothing.\n\n<b>Ignore client bandwidth.</b> Off by default: the client reports the speed it wants and the server trusts it. A user may enter an inflated value and take over the link at the expense of others. Turn this on if access is given to other people: the server stops honouring the declared bandwidth and uses the selected controller (cc) for everyone alike.\n\nBoth settings are server-side; clients need not change anything.\n\nNote: with Ignore client bandwidth on, Brutal is not used at all, so the bandwidth set in the main menu no longer works as a speed mode."),
                    $t('sniff и фильтры AdGuard', 'sniff and AdGuard filters') => $t(
                        "Обычно приложение пользователя само превращает имя сайта в IP-адрес и просит сервер соединить его с этим адресом. Сервер видит только цифры, поэтому списки блокировки AdGuard, которые работают по именам сайтов, на такие запросы не действуют.\n\n<b>sniff</b> заставляет сервер заглянуть в начало соединения и достать оттуда имя сайта — из заголовка HTTP, из TLS или из QUIC. Дальше сервер сам узнаёт адрес этого сайта через AdGuard бота. Итог: фильтры AdGuard (реклама, трекеры, ваши списки) начинают действовать на пользователей Hysteria так же, как на остальные протоколы.\n\n<b>Когда включать.</b> Если вы пользуетесь блокировками AdGuard и хотите, чтобы они распространялись на Hysteria.\n\n<b>Что учесть.</b>\n• Первое соединение с каждым сайтом становится чуть медленнее: сервер ждёт начало данных, до 2 секунд для TCP.\n• Соединения, где имени сайта нет (игры, мессенджеры со своим протоколом), идут как раньше — по адресу.\n• Адрес сайта теперь выбирает сервер, а не устройство пользователя. Для сайтов, которые выдают разным странам разные адреса, это обычно даже лучше.\n\nЗащита внутренних адресов сервера не ослабляется: если имя сайта ведёт на адрес контейнера бота или частной сети, соединение отклоняется так же, как без sniff.\n\nНастройка серверная. Версия 2.13.0 исправила распознавание QUIC у современных браузеров.",
                        "Usually the user's app resolves the site name to an IP address itself and asks the server to connect to that address. The server sees only numbers, so AdGuard block lists, which work by site names, do not apply to such requests.\n\n<b>sniff</b> makes the server look into the start of the connection and extract the site name from the HTTP header, TLS or QUIC. Then the server resolves the site through the bot's AdGuard itself. As a result AdGuard filters (ads, trackers, your lists) apply to Hysteria users the same way as to other protocols.\n\n<b>When to enable.</b> If you use AdGuard blocking and want it to cover Hysteria.\n\n<b>What to keep in mind.</b>\n• The first connection to each site gets slightly slower: the server waits for the start of data, up to 2 seconds for TCP.\n• Connections without a site name (games, messengers with their own protocol) work as before, by address.\n• The site address is now chosen by the server, not the user's device. For sites that give different countries different addresses this is usually even better.\n\nProtection of the server's internal addresses is not weakened: if a site name leads to a bot container address or a private network, the connection is rejected just as without sniff.\n\nThe setting is server-side. Version 2.13.0 fixed QUIC detection for modern browsers."),
                    $t('Если после изменения не подключается', 'If nothing connects after a change') => $t(
                        "<b>Не подключается никто, после смены типа обфускации.</b> Это ожидаемо: старые ссылки больше не подходят. Раздайте новые ссылки или верните прежний тип той же кнопкой.\n\n<b>Не подключается только часть пользователей при gecko.</b> Их приложение не поддерживает gecko. Нужен официальный клиент Hysteria 2.9.2+ либо возврат на salamander.\n\n<b>Меню пишет, что Gecko требует ядро 2.9.2.</b> Образ Hysteria старый: обновите бота, версия ядра показана в главном меню Hysteria.\n\n<b>Скорость стала хуже после смены cc.</b> Верните bbr. Профили отличаются поведением на конкретном канале; для большинства bbr остаётся лучшим.\n\n<b>Заданная полоса перестала влиять на скорость.</b> Проверьте, не включено ли «Игнорировать полосу клиента»: с ним Brutal отключён.\n\n<b>Перестали открываться некоторые сайты после включения sniff.</b> Скорее всего, их блокирует список AdGuard — раньше он на Hysteria не действовал. Проверьте журнал запросов AdGuard либо выключите sniff.\n\n<b>Меню сообщает, что настройку применить не удалось.</b> Бот не смог записать конфигурацию, прежнее значение сохранено. Откройте «Диагностика» в главном меню Hysteria.\n\nТекущую конфигурацию сервера показывает кнопка <b>config</b> в главном меню: в ней видны блоки obfs, congestion, bandwidth и sniff.",
                        "<b>Nobody connects after changing the obfuscation type.</b> This is expected: old links no longer fit. Hand out new links or return the previous type with the same button.\n\n<b>Only some users fail with gecko.</b> Their app does not support gecko. They need the official Hysteria client 2.9.2+, or go back to salamander.\n\n<b>The menu says Gecko needs core 2.9.2.</b> The Hysteria image is old: update the bot; the core version is shown in the main Hysteria menu.\n\n<b>Speed got worse after changing cc.</b> Return to bbr. Profiles behave differently on a particular link; for most, bbr remains the best.\n\n<b>The set bandwidth no longer affects speed.</b> Check whether Ignore client bandwidth is on: Brutal is disabled with it.\n\n<b>Some sites stopped opening after enabling sniff.</b> Most likely an AdGuard list blocks them; earlier it did not apply to Hysteria. Check the AdGuard query log or turn sniff off.\n\n<b>The menu says the setting could not be applied.</b> The bot could not write the configuration; the previous value is kept. Open Diagnostics in the main Hysteria menu.\n\nThe <b>config</b> button in the main menu shows the current server configuration, including the obfs, congestion, bandwidth and sniff blocks."),
                ]];
            case 'ovpn':
                $back = preg_match('~^[a-zA-Z0-9_.\-]{1,40}$~D', $context) ? '/ovpnClientMenu ' . $context : '/menu ovpn';
                return ['OpenVPN', $back, [
                $t('Что такое OpenVPN и когда он нужен', 'What OpenVPN is and when to use it') => $t(
                    "OpenVPN — классический VPN с сертификатами. Он не маскируется под обычный сайт, поэтому там, где VPN целенаправленно блокируют, выбирайте Xray, Hysteria или NaiveProxy. Зато его клиент есть почти везде: Windows, macOS, Linux, Android, iOS, роутеры Keenetic, MikroTik, OpenWrt.\n\n<b>Как устроено в боте.</b> У каждого клиента свой сертификат и свой файл <code>.ovpn</code> — в нём уже лежат адрес сервера, ключи и настройки. Пароля нет: кто владеет файлом, тот и подключается, поэтому передавайте файл лично и не публикуйте.\n\n<b>Главный экран</b> показывает адрес и порт сервера, протокол, число клиентов и кто сейчас в сети: внутренний адрес, адрес, с которого пришёл клиент, принятый и отданный объём за текущую сессию.\n\n<b>Значки в списке:</b> 🟢 в сети, ⚪ не подключён, 🚫 заблокирован, ⚠ сертификат истекает в ближайшие 30 дней, ❌ сертификат истёк.",
                    "OpenVPN is a classic certificate-based VPN. It does not disguise itself as an ordinary website, so where VPNs are deliberately blocked choose Xray, Hysteria or NaiveProxy. On the other hand its client exists almost everywhere: Windows, macOS, Linux, Android, iOS, Keenetic, MikroTik and OpenWrt routers.\n\n<b>How it works in the bot.</b> Each client has its own certificate and its own <code>.ovpn</code> file containing the server address, keys and settings. There is no password: whoever has the file can connect, so hand the file over personally and do not publish it.\n\n<b>The main screen</b> shows the server address and port, the protocol, the number of clients and who is online now: internal address, the address the client came from, and data received and sent in the current session.\n\n<b>Icons in the list:</b> 🟢 online, ⚪ not connected, 🚫 blocked, ⚠ certificate expires within 30 days, ❌ certificate expired."),
                $t('Клиенты: добавить, выдать файл, заблокировать', 'Clients: add, issue a file, block') => $t(
                    "<b>Добавить.</b> «добавить клиента» → введите имя латиницей (буквы, цифры, точка, дефис, подчёркивание, до 40 символов). Бот выпустит сертификат на 10 лет и сразу пришлёт файл <code>имя.ovpn</code>.\n\n<b>Подключение.</b> Установите OpenVPN Connect (телефон, Windows, macOS) или пакет openvpn (Linux, роутер) и импортируйте файл. Больше ничего вводить не нужно.\n\n<b>Меню клиента</b> открывается нажатием на имя:\n• <b>скачать .ovpn</b> — прислать файл ещё раз;\n• <b>заблокировать / разблокировать</b> — временная блокировка, сертификат остаётся действующим;\n• <b>отключить</b> — разорвать текущую сессию (клиент подключится снова, если не заблокирован);\n• <b>история</b> — когда клиент подключался и отключался;\n• <b>удалить</b> — отозвать сертификат навсегда.\n\nОдин файл рассчитан на одно устройство. Если подключить второе устройство с тем же файлом, первое будет отключаться — выдайте каждому устройству своего клиента.",
                    "<b>Add.</b> add peer → enter a name in Latin characters (letters, digits, dot, hyphen, underscore, up to 40 characters). The bot issues a 10-year certificate and immediately sends the <code>name.ovpn</code> file.\n\n<b>Connecting.</b> Install OpenVPN Connect (phone, Windows, macOS) or the openvpn package (Linux, router) and import the file. Nothing else needs to be entered.\n\n<b>The client menu</b> opens when you tap the name:\n• <b>download</b>: send the file again;\n• <b>disable / enable</b>: a temporary block, the certificate stays valid;\n• <b>kick</b>: drop the current session (the client reconnects unless blocked);\n• <b>history</b>: when the client connected and disconnected;\n• <b>delete</b>: revoke the certificate for good.\n\nOne file is meant for one device. If a second device connects with the same file, the first one gets disconnected: give each device its own client."),
                $t('Перевыпуск сертификата', 'Certificate reissue') => $t(
                    "Сертификат клиента действует 10 лет. В меню клиента видны дата выпуска и дата окончания; за 30 дней до конца появляется ⚠.\n\n<b>«перевыпустить сертификат»</b> отзывает действующий сертификат и выпускает новый под тем же именем. Нужен в двух случаях:\n• срок подходит к концу;\n• файл <code>.ovpn</code> мог попасть в чужие руки — после перевыпуска старый файл бесполезен.\n\n<b>Что произойдёт:</b>\n1. Прежний файл перестанет работать сразу, активная сессия закроется.\n2. Бот пришлёт новый <code>.ovpn</code> — его нужно передать клиенту и импортировать заново.\n3. Блокировка, счётчик трафика и лимит клиента сохранятся.\n\nБот спросит подтверждение. Если отзыв не удался — ничего не меняется. Если отзыв прошёл, а новый сертификат выпустить не получилось (редкий сбой), бот сообщит об этом: клиента нужно будет добавить заново тем же именем.",
                    "A client certificate is valid for 10 years. The client menu shows the issue and expiry dates; ⚠ appears 30 days before the end.\n\n<b>reissue certificate</b> revokes the current certificate and issues a new one under the same name. It is needed in two cases:\n• the expiry is approaching;\n• the <code>.ovpn</code> file may have fallen into the wrong hands: after a reissue the old file is useless.\n\n<b>What happens:</b>\n1. The previous file stops working at once and the active session closes.\n2. The bot sends a new <code>.ovpn</code>: pass it to the client and import it again.\n3. The client's block, traffic counter and limit are kept.\n\nThe bot asks for confirmation. If the revocation fails, nothing changes. If the revocation succeeded but the new certificate could not be issued (a rare failure), the bot says so: then add the client again under the same name."),
                $t('Протокол: udp, tcp или оба', 'Protocol: udp, tcp or both') => $t(
                    "Кнопка <b>«протокол»</b> переключает по кругу: <b>udp → tcp → udp+tcp</b>.\n\n• <b>udp</b> — быстрее и устойчивее к потерям, вариант по умолчанию.\n• <b>tcp</b> — медленнее, но проходит там, где провайдер или сеть в гостинице режут UDP.\n• <b>udp+tcp</b> — сервер принимает оба на одном порту. В файле клиента записаны оба адреса: сначала он пробует UDP и, если за 8 секунд ответа нет, сам переходит на TCP. Удобно, когда клиенты подключаются из разных сетей.\n\n<b>Важно.</b> Протокол записан в файле клиента. После переключения прежние файлы подходят не всегда:\n• с udp или tcp на udp+tcp — старые файлы продолжают работать, но запасного варианта в них нет; чтобы он появился, выдайте файл заново;\n• с udp+tcp на один протокол или между udp и tcp — файлы с другим протоколом перестают подключаться, их нужно выдать заново.\n\nПереключение перезапускает OpenVPN: все сессии кратко прерываются. <b>«сменить порт»</b> меняет внешний порт для всех выбранных протоколов сразу; файлы после смены порта тоже нужно выдать заново.",
                    "The <b>protocol</b> button cycles: <b>udp → tcp → udp+tcp</b>.\n\n• <b>udp</b>: faster and more tolerant of loss, the default.\n• <b>tcp</b>: slower, but gets through where the provider or a hotel network cuts UDP.\n• <b>udp+tcp</b>: the server accepts both on one port. The client file has both addresses: it tries UDP first and, if there is no answer within 8 seconds, switches to TCP by itself. Handy when clients connect from different networks.\n\n<b>Important.</b> The protocol is written in the client file. After switching, old files do not always fit:\n• from udp or tcp to udp+tcp: old files keep working, but have no fallback; issue the file again to get it;\n• from udp+tcp to a single protocol, or between udp and tcp: files with the other protocol stop connecting and must be issued again.\n\nSwitching restarts OpenVPN: all sessions are briefly interrupted. <b>change port</b> changes the external port for all selected protocols at once; after a port change the files must be issued again too."),
                $t('Весь трафик или выбранные сети, MSS', 'All traffic or selected networks, MSS') => $t(
                    "<b>«весь трафик через VPN: 🟢»</b> (по умолчанию) — после подключения весь интернет клиента идёт через сервер.\n\n<b>🔴</b> — через VPN идут только сети из списка, остальной трафик клиента идёт напрямую, как без VPN. Это нужно, когда VPN используется для доступа к нескольким адресам, а не для всего.\n\n<b>«сети»</b> — список сетей в записи CIDR, например <code>203.0.113.0/24</code>; адрес без префикса — один узел. До 40 записей, <code>-</code> очищает список. Если переключатель выключен, а сетей нет, через туннель идёт только DNS — бот предупредит об этом.\n\nDNS клиентам всегда выдаётся свой (AdGuard сборки), поэтому фильтрация и запросы имён работают в обоих режимах.\n\n<b>MSS</b> — предельный размер TCP-сегмента внутри туннеля. «авто» подходит почти всегда. Уменьшайте (1360 → 1280 → 1200), если у части клиентов сайты открываются наполовину, зависают загрузки или не проходят большие страницы — так бывает в мобильных сетях и за некоторыми роутерами. Настройка действует на стороне сервера, файлы клиентов менять не нужно.\n\nВсе три настройки перезапускают OpenVPN; клиенты получают их при следующем подключении.",
                    "<b>all traffic via VPN: 🟢</b> (default): after connecting, all of the client's Internet traffic goes through the server.\n\n<b>🔴</b>: only networks from the list go through the VPN; the rest of the client's traffic goes direct, as without a VPN. Use it when the VPN is for reaching a few addresses rather than everything.\n\n<b>networks</b>: a list of networks in CIDR form, e.g. <code>203.0.113.0/24</code>; an address without a prefix is a single host. Up to 40 entries, <code>-</code> clears the list. If the switch is off and there are no networks, only DNS goes through the tunnel; the bot warns about it.\n\nClients always get the bot's own DNS (the build's AdGuard), so filtering and name lookups work in both modes.\n\n<b>MSS</b> is the maximum TCP segment size inside the tunnel. auto fits almost always. Lower it (1360 → 1280 → 1200) if for some clients sites open halfway, downloads hang or large pages do not load; this happens on mobile networks and behind some routers. The setting applies on the server side; client files need not change.\n\nAll three settings restart OpenVPN; clients get them on the next connection."),
                $t('Учёт трафика и лимит', 'Traffic accounting and limit') => $t(
                    "OpenVPN сам считает трафик только за текущую сессию. Бот складывает сессии и ведёт <b>накопительный счётчик</b> по каждому клиенту — строка «трафик всего» в меню клиента, с датой начала отсчёта.\n\n<b>Точность.</b> Счётчик обновляется раз в несколько секунд. При аварийной остановке сервера может потеряться трафик последних секунд сессии — считайте цифру близкой оценкой, а не биллингом.\n\n<b>«сбросить счётчик»</b> начинает отсчёт заново с текущего момента.\n\n<b>«лимит трафика»</b> — объём в гигабайтах (приём плюс отдача), например <code>50</code> или <code>0.5</code>; <code>0</code> снимает лимит. Когда счётчик доходит до лимита:\n1. клиент блокируется (🚫) и его сессия закрывается;\n2. вам приходит сообщение.\n\n<b>Как вернуть доступ:</b> увеличьте лимит или сбросьте счётчик, затем нажмите «разблокировать». Пока лимит исчерпан, кнопка «разблокировать» не сработает и объяснит почему.\n\nЛимиты входят в резервную копию, а счётчики нет: восстановление не откатывает их назад. Счётчики переживают перевыпуск сертификата. При удалении клиента его счётчик удаляется.",
                    "OpenVPN itself counts traffic only for the current session. The bot adds up sessions and keeps a <b>cumulative counter</b> per client: the traffic total line in the client menu, with the date counting started.\n\n<b>Accuracy.</b> The counter updates every few seconds. If the server stops abnormally, the last seconds of a session may be lost: treat the figure as a close estimate, not billing.\n\n<b>reset counter</b> starts counting again from now.\n\n<b>traffic limit</b>: a volume in gigabytes (download plus upload), e.g. <code>50</code> or <code>0.5</code>; <code>0</code> removes the limit. When the counter reaches the limit:\n1. the client is blocked (🚫) and its session closes;\n2. you get a message.\n\n<b>How to restore access:</b> raise the limit or reset the counter, then tap enable. While the limit is used up, enable will not work and will explain why.\n\nLimits are part of the backup, counters are not: a restore does not roll them back. Counters survive a certificate reissue. Deleting a client deletes its counter."),
                $t('Изоляция клиентов и block-outside-dns', 'Client isolation and block-outside-dns') => $t(
                    "<b>«трафик между клиентами»</b>. По умолчанию выключен: клиенты VPN не видят друг друга, каждый ходит только в интернет. Включайте, если клиентам нужно обращаться друг к другу — общая папка, игра по сети, удалённый рабочий стол.\n\n<b>«block-outside-dns (Windows)»</b>. Windows умеет отправлять запросы имён мимо VPN, через DNS провайдера. Включённая защита запрещает это.\n\n⚠ Настройку понимают <b>только клиенты Windows</b>. Любой другой клиент — телефон, macOS, Linux, роутер — получив её, <b>не подключится вовсе</b>. Включайте только если все ваши клиенты на Windows.\n\nОбе настройки перезапускают OpenVPN.",
                    "<b>inter-client routing</b>. Off by default: VPN clients cannot see each other, each one only reaches the Internet. Turn it on if clients need to reach each other: a shared folder, a LAN game, remote desktop.\n\n<b>block-outside-dns (Windows)</b>. Windows can send name lookups around the VPN through the provider's DNS. This protection forbids that.\n\n⚠ Only <b>Windows clients</b> understand this setting. Any other client (phone, macOS, Linux, router) that receives it <b>will not connect at all</b>. Turn it on only if all your clients are on Windows.\n\nBoth settings restart OpenVPN."),
                $t('Если не работает', 'If it does not work') => $t(
                    "<b>Клиент не подключается.</b>\n• Проверьте, что OpenVPN включён: на главном экране должно быть «🟢 openvpn». Если 🔴 — нажмите «перезагрузка» и посмотрите «журнал».\n• Сравните протокол и порт в файле клиента с главным экраном. После смены протокола или порта файл нужно выдать заново.\n• Клиент заблокирован (🚫) — разблокируйте его. Если не получается, исчерпан лимит трафика.\n• Сертификат истёк (❌) — перевыпустите.\n• В сети клиента режется UDP — переключите протокол на udp+tcp и выдайте файл заново.\n\n<b>Подключается, но сайты не открываются.</b>\n• «весь трафик через VPN» выключен, а нужные сети не заданы.\n• Сайты открываются частично или висят — уменьшите MSS.\n• Включён «block-outside-dns (Windows)», а клиент не Windows.\n\n<b>В списке у всех один и тот же адрес.</b> Трафик приходит через nginx сборки, и OpenVPN видит его адрес вместо настоящего — бот пишет об этом под списком. На работу это не влияет.\n\n<b>«PKI неполный».</b> Контейнер не закончил первую инициализацию ключей. Перезапустите контейнер ovpn командой из сообщения.\n\n<b>Где смотреть.</b> «журнал» — журнал сервера; «подключения» — кто и когда подключался; «история» в меню клиента — то же по одному клиенту.",
                    "<b>The client does not connect.</b>\n• Check that OpenVPN is on: the main screen must show 🟢 openvpn. If it is 🔴, tap restart and look at log tail.\n• Compare the protocol and port in the client file with the main screen. After a protocol or port change the file must be issued again.\n• The client is blocked (🚫): enable it. If that fails, the traffic limit is used up.\n• The certificate has expired (❌): reissue it.\n• The client's network cuts UDP: switch the protocol to udp+tcp and issue the file again.\n\n<b>Connects, but sites do not open.</b>\n• all traffic via VPN is off and the needed networks are not set.\n• Sites open partially or hang: lower MSS.\n• block-outside-dns (Windows) is on and the client is not Windows.\n\n<b>Everyone in the list has the same address.</b> Traffic arrives through the build's nginx, and OpenVPN sees its address instead of the real one; the bot notes this under the list. It does not affect operation.\n\n<b>PKI is incomplete.</b> The container has not finished the initial key setup. Restart the ovpn container with the command from the message.\n\n<b>Where to look.</b> log tail: the server log; connections: who connected and when; history in the client menu: the same for one client."),
                ]];
            case 'managednodes':
                $nodeBack = $context === '' ? '/nodes' : '/node ' . $context;
                if (preg_match('~^t_([a-f0-9]{8})$~D', $context, $origin)) {
                    $nodeBack = '/nt' . $origin[1] . ' xtlsdat';
                } elseif (preg_match('~^([rud])_([a-f0-9]{8})$~D', $context, $origin)) {
                    $nodeBack = '/n' . $origin[1] . (['r'=>'', 'u'=>'Users', 'd'=>'Diag'][$origin[1]]) . ' ' . $origin[2] . ($origin[1] === 'u' ? ' 0' : '');
                } elseif ($context !== '' && !preg_match('~^[a-f0-9]{8}$~D', $context)) return [];
                return [$t('Управляемые ноды', 'Managed nodes'), $nodeBack, [
                    $t('Установка и SSH', 'Installation and SSH') => $t(
                        "В Menu → Ноды добавьте сервер. Основной бот создаёт отдельный ключ управления и показывает его публичную часть. На чистом сервере запустите <code>bash init.sh --mode node</code>, передайте публичный ключ и разрешённые адреса серверов. Затем введите в карточке IP, порт SSH и публичный ключ хоста из доверенной консоли или установщика. Приватные ключи копировать в чат не нужно.\n\nПосле удаления ноды бот сохраняет её ключ управления. При повторном добавлении того же сервера (тот же публичный ключ сервера) бот сначала пробует новый ключ из карточки, а если сервер его не принимает — сохранённый, без ручной замены на ноде. На переустановленный сервер передайте установщику новый ключ из карточки. Заменить ключ на уже установленной ноде вручную: <code>python3 -I scripts/node_setup.py --controller-key файл</code>.\n\nНа ноде нет Telegram-бота и его токена. Обязателен контейнер Xray; NGINX добавляется для собственного сайта, отдельный помощник AmneziaWG — при его включении. Управляющий SSH-пользователь выполняет только ограниченные команды ноды, без оболочки и перенаправления портов.\n\nДля управления по IPv6 сначала подготовьте IPv6 основного бота. SSH проходит через его Xray-контейнер с проверкой обоих ключей серверов. Смена обычного SSH-адреса сохраняет прежний ключ хоста; другой сервер автоматически не принимается.",
                        "Add a server in Menu → Nodes. The main bot creates a dedicated controller key and displays its public half. On a clean server run <code>bash init.sh --mode node</code>, supply that public key and permitted server addresses. Then enter the IP, SSH port and host public key obtained from a trusted console or installer. Do not paste private keys into chat.\n\nAfter a node is removed, the bot keeps its management key. When the same server is added again (same server public key), the bot first tries the new key from the card and, if the server rejects it, the kept key, with no manual change on the node. Give a reinstalled server the new key from the card. To replace the key on an installed node manually: <code>python3 -I scripts/node_setup.py --controller-key file</code>.\n\nThe node has no Telegram bot or token. Xray is required; NGINX is added for an own website, and a separate AmneziaWG helper when enabled. The SSH controller can execute only limited node operations, with no shell or port forwarding.\n\nPrepare the main bot's IPv6 before managing a node over IPv6. SSH passes through its Xray container and verifies both host keys. Ordinary SSH address changes retain the previous host pin; another server is never accepted automatically."),
                    $t('Транспорт, IPv6 и свой сайт', 'Transport, IPv6 and own website') => $t(
                        "Связь основной бот → нода и выход нода → сайт выбираются независимо: IPv4 или IPv6. Поддерживаются REALITY, WS, gRPC, Trojan-gRPC и XHTTP. Для WS/gRPC/XHTTP с TLS нужен собственный домен и сертификат. REALITY может использовать внешний сайт; для собственного сайта с паролем включите заглушку и задайте свой домен. Это не гарантия незаметности для DPI.\n\nОтпечаток Chrome/Firefox относится к основному боту как TLS-клиенту ноды. Обратные данные идут по уже установленному соединению: второй клиентский TLS-сеанс ноде для них не нужен.\n\nНастройки Xray включают выбор ядра, VLESS Encryption, ML-DSA и маскировку — доступность зависит от ядра и транспорта. SMUX/h2mux требуют fork-ядро с обеих сторон, включая WS/XHTTP; XMUX у XHTTP — отдельная настройка. Изменения сначала сохраняются в черновик, затем применяются одной операцией. Подтверждение происходит после передачи реального трафика; при отказе нода откатывает изменение.\n\nВ меню IPv4/IPv6 показаны пары: первая часть — бот → нода, вторая — нода → интернет. В выборе ядра выводятся версии с ноды. В «Домены и сертификат» можно добавить поддомены; их DNS должен указывать на ноду. В карточке виден срок сертификата.\n\nHTTP-01 временно открывает только TCP/80. SSH и VPN сохраняют ограничения источников. Публичные адреса и доверенный IPv6-маршрутизатор задаются на самом сервере.",
                        "Select main bot → node and node → website address families independently: IPv4 or IPv6. REALITY, WS, gRPC, Trojan-gRPC and XHTTP are supported. TLS over WS/gRPC/XHTTP needs an own domain and certificate. REALITY can use an external website; enable the password-protected cover and supply your domain for an own website. This does not guarantee invisibility to DPI.\n\nThe Chrome/Firefox fingerprint belongs to the main bot as the node's TLS client. Replies use the established connection; the node does not need a second client TLS session for them.\n\nXray settings include core selection, VLESS Encryption, ML-DSA and masking, depending on core and transport. SMUX/h2mux require the fork on both ends, including WS/XHTTP; XHTTP XMUX is a separate option. Edits stay in a draft until applied together. Confirmation follows a real traffic probe; failure makes the node roll back.\n\nThe IPv4/IPv6 menu shows pairs: bot → node first, node → internet second. Core choices display the node’s versions. Domains and certificate accepts additional names resolving to the node; the card displays certificate expiry.\n\nHTTP-01 temporarily opens TCP/80 only. SSH and VPN keep their source restrictions. Configure public addresses and trusted IPv6 router on the server."),
                    $t('Маршруты и файлы правил', 'Routes and rule files') => $t(
                        "В карточке откройте «Маршруты и наборы», задайте назначения и пользователей основного бота. Это работает для любых сервисов. Маршрутизацию выполняет основной бот; ноде не требуется отдельная копия его пользовательских лимитов или DNS-фильтров.\n\nПоддерживаются домены, IPv4/IPv6-подсети, sing-box .srs, Mihomo .mrs и Xray .dat. .srs/.mrs скачиваются по HTTPS, преобразуются в домены/подсети и обновляются ежедневно. В меню наборов для .dat откройте общий реестр источников, добавьте <code>name.dat:https://…</code>, затем выберите файл, тип GeoSite/GeoIP и категории. Используются также записи <code>ext:file.dat:category</code> и <code>extip:file.dat:category</code>. Это разные форматы; .srs/.mrs не заменяют все .dat.\n\nДля новой управляемой ноды по умолчанию выбран «При отказе: блок». Прямой запасной выход включается отдельно. При потере обязательных правил строгий режим блокирует трафик назначенных пользователей до восстановления. QUIC можно разрешить отдельно; это не гарантирует обход блокировки или отсутствие рекламы.",
                        "Open Routes and rule sets in the card, select destinations and main-bot users. This works for any service. The main bot routes traffic; the node does not need a duplicate of its user limits or DNS filters.\n\nDomains, IPv4/IPv6 networks, sing-box .srs, Mihomo .mrs and Xray .dat are supported. HTTPS .srs/.mrs downloads are converted into domains/networks and refreshed daily. For .dat open the shared source registry from the sets menu, add <code>name.dat:https://…</code>, then select the file, GeoSite/GeoIP type and categories. Entries <code>ext:file.dat:category</code> and <code>extip:file.dat:category</code> also work. These are different formats; .srs/.mrs do not replace every .dat.\n\nNew managed nodes default to On failure: block. Direct fallback is a separate opt-in. Missing required rules make strict mode block assigned users until recovery. QUIC can be allowed separately; it does not guarantee bypassing a block or removing ads."),
                    $t('Бэкап и переустановка ноды', 'Backup and node reinstall') => $t(
                        "Создавайте бэкап через Telegram основного бота. Он включает настройки маршрутов и нод, отдельный SSH-ключ управления, закреплённый ключ хоста и последнюю подтверждённую копию ноды: настройки Xray, ключи подключений, сертификат, внешних клиентов и резервные каналы. Недоступная нода сохраняет предыдущую копию; её время видно в карточке.\n\n«Обслуживание → Восстановить сохранённую копию» возвращает ноду к этой копии после подтверждения и проверки трафика. После переустановки ОС сначала установите режим ноды с прежним публичным ключом управления. Затем выберите «Привязать SSH после переустановки», сверьте новый публичный ключ хоста через доверенную консоль и восстановите копию. До успешного восстановления бот сохраняет старую копию и блокирует остальные изменения.\n\nЭто не образ ОС: firewall хоста, адреса, SSH администратора и сеть на новом сервере настраиваются заново. Кэши .dat/.srs/.mrs не входят в бэкап: сохраняются источники и правила, файлы скачиваются повторно. Недоступный источник может помешать полному восстановлению правил; бот сообщает об ошибке. Бэкап содержит данные доступа — храните его как секрет.",
                        "Create backups through the main bot in Telegram. They include routes and node settings, the dedicated SSH controller key, pinned host key and last confirmed node snapshot: Xray settings, connection identities, certificate, external peers and backup carriers. An offline node retains its previous snapshot; its time is shown in the card.\n\nMaintenance → Restore saved node snapshot restores it after confirmation and a traffic test. After reinstalling the OS, install node mode with the previous public controller key first. Then choose Rebind SSH after reinstall, verify the new host public key using a trusted console and restore the snapshot. Until recovery succeeds, the bot preserves the old snapshot and blocks other changes.\n\nThis is not an OS image: reconfigure host firewall, addresses, administrator SSH and networking. .dat/.srs/.mrs caches are excluded: sources and rules are saved and files downloaded again. An unavailable source can prevent complete rule recovery; the bot reports the error. Backups contain credentials and must be stored as secrets."),
                    $t('Резервные каналы и внешние панели', 'Backup carriers and external panels') => $t(
                        "WireGuard и AmneziaWG включаются отдельно как альтернативная связь основного бота с нодой; одновременно активен один из них. Для WireGuard нужен доступ по UDP/51820, для AmneziaWG — UDP/51821 из разрешённых адресов. AmneziaWG переносит внутри защищённое VLESS-соединение. Рабочий канал выбирается в «Резервный канал». Автоматической смены при DPI-блокировке нет. В отдельных разделах WireGuard/AmneziaWG доступны MTU, Keepalive, а для AmneziaWG — padding, таймеры, H1–H4 и CPS-пакеты I1–I5. Защита cookie остаётся включённой.\n\nВ «Внешние панели и подключения» создаётся до 32 отдельных клиентов. Выдаются VLESS-ссылка, JSON outbound и файл подписки base64 для совместимых панелей/клиентов, включая ручной импорт в 3x-ui. Кнопка «HTTPS-подписка (3x-ui)» отправляет личный URL в приватный чат. Для него нужны домен и SSL основного бота. После смены транспорта обновите подписку в панели; после смены ключа внешнего подключения получите новый URL. При недоступной ноде или незавершённой операции выдаётся временная ошибка HTTP 503. Для SMUX и других расширений используйте JSON и совместимое ядро. Выключение, удаление и смена ключа отзывают прежний доступ; доступ основного бота остаётся отдельным. Совместимость шифрования и транспорта зависит от ядра внешней панели. Её исходящий адрес должен быть разрешён firewall ноды.\n\nDNS-фильтрацию обычно оставляют в AdGuard Home основного бота. Отдельный AdGuard Home на ноде не обязателен; DNS-фильтр не гарантирует удаления рекламы YouTube, размещённой вместе с видео.",
                        "Enable WireGuard or AmneziaWG as an alternative link from the main bot to the node; only one can be active at a time. WireGuard requires UDP/51820 and AmneziaWG UDP/51821 from permitted addresses. AmneziaWG carries the authenticated VLESS connection inside it. Select the working carrier in Backup channel; switching on DPI blocking is manual. Separate WireGuard/AmneziaWG screens offer MTU and Keepalive; AmneziaWG also offers padding, timers, H1–H4 and CPS packets I1–I5. Cookie protection stays enabled.\n\nExternal panels and connections supports up to 32 separate peers. Export a VLESS URI, JSON outbound or base64 subscription file for compatible panels/clients, including manual 3x-ui import. HTTPS subscription (3x-ui) sends a private URL to your direct chat. The main bot needs a domain and SSL. Refresh the panel subscription after transport changes; obtain a new URL after rotating the external identity. An unavailable node or pending change returns temporary HTTP 503. Use JSON and a compatible core for SMUX and other extensions. Disable, delete or rotate a peer to revoke its previous access; the main bot has a separate identity. Encryption/transport support depends on the external panel's core. Its source address must be permitted by the node firewall.\n\nDNS filtering usually remains in the main bot's AdGuard Home. A separate AdGuard Home on the node is optional; DNS filtering cannot guarantee removal of YouTube ads delivered with video."),
                    $t('Диагностика и обслуживание', 'Diagnostics and maintenance') => $t(
                        "Диагностика проверяет передачу трафика через ноду, задержку ответа, страну выхода и скорость. Измерение скорости относится к серверам, а не к телевизору или телефону; оно расходует трафик. Проверка SSH-состояния и успешная передача VPN-трафика — разные проверки. При смене доступности основной бот уведомляет администраторов.\n\nПосле успешной операции карточка показывает результат и время. Смена ключей отключённого протокола отклоняется; сначала включите его. Основной бот обновляет свой профиль автоматически, внешние панели требуют обновления подписки/профиля после смены общих ключей.\n\nВ обслуживании доступны перезапуск, обновление с веток master/dev, откат, создание и восстановление копии, смена ключей. Меню сертификата включает обычное продление, принудительный выпуск, новый домен и удаление неиспользуемого сертификата. Подробные пояснения — в справке обслуживания. Шаблоны AmneziaWG и их автогенерация находятся в настройках AmneziaWG; автоматическая генерация заменяет ручные параметры обфускации. Нода не скачивает произвольный исполняемый файл по ссылке из Telegram. Во время операции дождитесь проверки или автоматического отката; не запускайте параллельную ручную замену контейнеров.\n\nHWID, Limit IP, подписки пользователей и правила основного бота остаются на основном сервере. На межсерверном соединении нода видит профиль основного бота, а не исходные устройства; повторять там эти лимиты для каждого конечного пользователя некорректно.",
                        "Diagnostics tests traffic through the node, response latency, exit country and speed. Speed tests measure the servers, not the TV or phone, and consume traffic. SSH status and successful VPN traffic are separate checks. The main bot notifies administrators when availability changes.\n\nAfter success the card displays the verified result and time. Rotating keys of a disabled feature is rejected; enable it first. The main bot updates its profile automatically; external panels need a refreshed subscription/profile after shared-key rotation.\n\nMaintenance offers restart, master/dev updates, rollback, snapshot creation and restore, and key rotation. Its certificate menu includes renewal, forced issuance, new domains and deletion of unused certificates. Read Maintenance Help for details. AmneziaWG templates and scheduled generation are in AmneziaWG settings; scheduled generation replaces manual obfuscation overrides. The node does not download arbitrary executable URLs from Telegram. Wait for validation or automatic rollback during changes; avoid simultaneous manual container replacement.\n\nHWID, Limit IP, user subscriptions and main-bot routing remain on the main server. The node sees the main bot's inter-server profile rather than original devices; duplicating those limits per end user there would be incorrect."),
                ]];
            case 'exitnodes':
                $back = '/exits';
                if ($context === 'create') $back = '/exitCreate';
                elseif ($context === 'order') $back = '/exitOrder';
                elseif (preg_match('~^relay_(\d{1,6})$~D', $context, $m)) $back = '/exitRelayLink ' . $m[1];
                elseif (preg_match('~^(node|settings|diag|group)_([a-f0-9]{8})$~D', $context, $m)) {
                    $back = ['node' => '/exit ', 'settings' => '/exitSettings ', 'diag' => '/exitDiag ', 'group' => '/exitGroup '][$m[1]] . $m[2];
                } elseif ($context !== '') return [];
                return [$t('Узлы выхода', 'Exit nodes'), $back, [
                    $t('Два сервера через IPv6', 'Two servers over IPv6') => $t(
                        "Два независимых участка: основной бот → узел и узел → сайт. На узле в «Принимать трафик других ботов» создайте профиль, включите <b>Связь с узлом: IPv6</b> и <b>Выход: только IPv6</b>. Первый переключатель меняет адрес в ссылке и подписке на буквальный IPv6 узла, второй запрещает выход к сайтам через IPv4. Для полной цепочки нужны оба.\n\nМежсерверный IPv6 сейчас поддерживается для <b>Reality TCP/443</b>. На обоих серверах подготовьте сеть IPv6; на узле настройте <code>node6_sources</code> (публичный IPv6 основного сервера) и <code>node6_public</code> (IPv6 узла) в nftables. Пустые наборы закрывают вход. Бот сам firewall не открывает. После смены транспорта IPv6-ссылка перестаёт выдаваться.\n\nНа основном боте добавьте ссылку/подписку профиля, домены или наборы YouTube, назначьте пользователей и выберите <b>При отказе: блок</b>. Прямой запасной выход разрешается отдельно и нарушает требование «вся цепочка только IPv6».\n\nДоменам назначения нужны AAAA-записи. Буквальный IPv4 и IPv4 CIDR не превращаются в IPv6. AAAA для имени самого VPN-сервера не требуется: ссылка использует IPv6 напрямую и сохраняет SNI. Отдельный сертификат на IPv6 не нужен. Инструкция: <code>docs/IPV6_NODE_RU.md</code>.",
                        "Two independent legs: main bot → node and node → website. On the node, create a profile under Accept traffic from other bots and enable <b>Node connection: IPv6</b> and <b>Egress: IPv6 only</b>. The first changes the link and subscription endpoint to the node’s literal IPv6; the second forbids IPv4 website egress. Both are needed for the complete chain.\n\nInter-server IPv6 currently supports <b>Reality TCP/443</b>. Prepare the IPv6 network on both servers. On the node configure nftables <code>node6_sources</code> (main server public IPv6) and <code>node6_public</code> (node IPv6). Empty sets close ingress. The bot does not open the firewall. After a transport change the IPv6 link is no longer issued.\n\nOn the main bot add the profile link/subscription, YouTube domains or sets, assign users and select <b>On failure: block</b>. Direct fallback is a separate permission and breaks the all-IPv6 chain requirement.\n\nDestination domains need AAAA records. Literal IPv4 addresses and IPv4 CIDRs are not converted to IPv6. The VPN hostname itself needs no AAAA: the link uses literal IPv6 and keeps SNI. No separate IPv6 certificate is needed. Guide: <code>docs/IPV6_NODE_RU.md</code>."),
                    $t("Как устроено меню", "Menu layout") => $t(
                        "Список показывает тип выхода, число маршрутов, наборов и пользователей. Цвет — итог последней проверки; в карточке видно время, а устаревшая проверка отмечена отдельно.\n\n<b>Добавить выход</b> → удалённый сервер, группа или IPv6 этого сервера. На карточке сначала настройте <b>Маршруты / Наборы .srs/.mrs/.dat</b>, затем <b>Пользователи</b>. У группы сначала выберите участников. Без пользователей выход не влияет на клиентский трафик.\n\n<b>Настройки</b> — имя, поведение при отказе, QUIC, назначение новым пользователям, ссылка и подписка узла, удаление с подтверждением. Старые кнопки продолжают открывать действия; старый переключатель отказа теперь открывает явный выбор режима.\n\n<b>Диагностика</b> — доступность, история, скорость, обновление наборов и сброс счётчика с подтверждением. «Обновить наборы» не меняет ссылку соединения: для неё в настройках есть «Проверить обновление ссылки».\n\n<b>Принимать трафик других ботов</b> создаёт «Профиль для узла» на этом сервере: его ссылку добавляют на другом боте.",
                        "The list shows exit type and route, rule-set and user counts. Color is the last check result; the card shows its time and marks stale checks.\n\n<b>Add exit</b> → remote server, group or this server’s IPv6. On its card, set <b>Routes / Sets .srs/.mrs/.dat</b>, then <b>Users</b>. For a group, select members first. An exit without assigned users does not affect client traffic.\n\n<b>Settings</b>: name, failure policy, QUIC, assignment to new users, link and node subscription, confirmed deletion. Old buttons still open actions; the old failure toggle now opens an explicit policy choice.\n\n<b>Diagnostics</b>: availability, history, speed, set refresh and confirmed counter reset. Refresh sets does not change the connection link: use Check link update in Settings for that.\n\n<b>Accept traffic from other bots</b> creates a Node profile on this server; add its link on the other bot."),
                    $t("Группы и ручной выбор", "Groups and manual selection") => $t(
                        "Группа выбирает выход из уже добавленных удалённых узлов. В «Состав и выбор узла» слева включают участника в группу или убирают, справа выбирают его вручную. Сами участники должны быть включены; их маршруты и пользователи в группу не копируются. Маршруты и пользователей задайте самой группе.\n\n<b>Автоматически</b> — живой участник с минимальной задержкой до контрольного HTTP-адреса (leastPing). Это не гарантия наибольшей пропускной способности. Первые результаты появляются после проб Xray.\n\n<b>Ручной выбор</b> — новые соединения идут через выбранного участника. Если он выключен, удалён или не работает, маршрут блокируется; автоматической замены нет. «Напрямую с этого сервера» доступно только при разрешённом прямом запасном выходе.\n\nНовая группа строгая: при отказе всех участников выбранные назначения блокируются. Проверка автоматической группы не использует прямой запасной выход. Трафик группы учитывается у участников.\n\nЛокальный IPv6 и вложенные группы в состав не входят. Общий предел — 8 записей, включая группы.",
                        "A group selects an exit among existing remote nodes. In Members and selection, the left button includes or removes a member; the right button selects it manually. Members must be enabled. Their routes and users are not copied: assign routes and users to the group itself.\n\n<b>Automatic</b>: a live member with the lowest latency to the HTTP probe endpoint (leastPing). This does not guarantee the highest throughput. Initial results require Xray probes.\n\n<b>Manual selection</b>: new connections use the selected member. If it is disabled, deleted or unavailable, the route is blocked; there is no automatic substitution. Direct from this server is available only when direct fallback is allowed.\n\nNew groups are strict: if all members fail, selected destinations are blocked. Automatic group checks do not use direct fallback. Group traffic is counted at its members.\n\nLocal IPv6 and nested groups cannot be members. The total limit is 8 entries, including groups."),
                    $t("Отказ, прямой выход и восстановление", "Failure, direct fallback and recovery") => $t(
                        "Обычный удалённый узел по умолчанию разрешает прямой запасной выход. В «Настройки → При отказе» можно явно выбрать блокировку. Локальный IPv6 и новая группа всегда начинаются со строгого режима.\n\nXray проверяет узел контрольным HTTP-запросом. Наблюдателю нужно время, чтобы признать отказ. При разрешённом запасном выходе новые соединения затем идут напрямую, а после успешных проб снова через узел. До первых успешных проб после запуска тоже действует запасной выход.\n\nОткрытые TCP-сеансы между путями не переносятся: приложение переподключается. Блокировка только контрольного адреса может пометить работающий узел недоступным. Успешная проба не гарантирует доступ к любому сайту.\n\n«Проверить» проверяет сам узел без его прямого запасного выхода. Ручной выбор участника группы не переключается автоматически на другого участника или напрямую. Выключение или удаление выхода снимает его маршруты — это отличается от строгого отказа включённого узла.",
                        "An ordinary remote node allows direct fallback by default. Settings → On failure offers an explicit blocking policy. Local IPv6 and new groups start strict.\n\nXray probes the node with a control HTTP request. The observer takes time to recognize a failure. If direct fallback is allowed, new connections then go directly and return through the node after successful probes. Before successful startup probes, the selected fallback also applies.\n\nOpen TCP sessions are not moved between paths: the application reconnects. A blocked control endpoint may mark an otherwise working node unavailable. A successful probe does not guarantee access to every website.\n\nCheck probes the node itself without its direct fallback. A manually selected group member never switches automatically to another member or direct egress. Disabling or deleting an exit removes its routes, unlike a strict failure of an enabled node."),
                    $t("Приоритет и применение изменений", "Priority and applying changes") => $t(
                        "<b>Приоритет маршрутов</b> в списке выходов меняет их порядок стрелками ↑/↓. При пересечении правил у одного пользователя срабатывает первый подходящий выход. Блок-лист и защитные правила выше узлов. Переименование приоритет не меняет. Старая кнопка после изменения списка не перемещает другую запись: откройте меню заново.\n\n<b>Без перезапуска</b> бот применяет поддерживаемые изменения маршрутов, ручной выбор участника, добавление выходов и новых пользователей VLESS/VMess/Trojan. Существующие соединения сохраняются, новые используют новые правила.\n\nПолный перезапуск нужен при удалении или изменении существующего выхода/пользователя, смене транспорта, DNS, ядра, наблюдателя и некоторых изменениях состава/приоритета. Он разрывает соединения. При ошибке API бот также выполняет полный перезапуск с проверенным конфигом.\n\nГорячее применение проверено для 26.9.30, 26.10.29, 26.10.31 и форков 26.10.28-1202 и 26.11.1-1424. Ядро 26.7.28, неизвестные версии и старый образ без помощника используют полный перезапуск. Служебный API доступен только внутри контейнера; вручную менять работающий Xray через API вне бота нельзя.",
                        "<b>Route priority</b> in the exit list reorders entries using ↑/↓. When a user has overlapping rules, the first matching exit wins. Block lists and security rules remain above nodes. Renaming does not change priority. A stale button cannot reorder a different entry: reopen the menu after the list changes.\n\n<b>Without restart</b>, the bot applies supported routing changes, manual member selection, new outbounds and new VLESS/VMess/Trojan users. Existing connections stay; new ones use the new rules.\n\nA full restart is required for changes or removal of existing outbounds/users, transport, DNS, core, observatory, and some membership/priority changes. It disconnects sessions. An API error also falls back to a full restart with a validated configuration.\n\nHot apply is verified for 26.9.30, 26.10.29, 26.10.31 and forks 26.10.28-1202 and 26.11.1-1424. Core 26.7.28, unknown versions and old images without the helper use a full restart. The service API is container-internal; manual changes to the running Xray through an outside API client are unsupported."),
                    $t('Что это и как работает', 'What it is') => $t(
                        "Узел выхода — другой сервер с vpnbot или IPv6 этого сервера. Выбранные назначения выбранных пользователей Xray уходят через него: например, чтобы изменить адрес выхода. Маршрут выбирает этот сервер по пользователю и домену, поэтому клиентам (Xray, sing-box, Mihomo, Shadowrocket) ничего настраивать не нужно.\n\nПо умолчанию при отказе удалённой ноды трафик идёт напрямую. Кнопка «При отказе» позволяет вместо этого блокировать выбранные назначения. Локальный IPv6 всегда работает без запасного IPv4. Если строгому узлу не хватает набора/.dat, трафик назначенных пользователей блокируется целиком до восстановления правил; карточка узла показывает предупреждение. Проверка узла идёт каждые 30 секунд внутри Xray и раз в 5 минут ботом; о смене состояния бот пишет администраторам.\n\nПорядок правил: защита и торренты → блок-лист → узлы → WARP → свои правила. Запись из блок-листа блокируется, даже если она есть у узла.",
                        "An exit node is another server running vpnbot or this server’s IPv6. Selected destinations of selected Xray users leave through it, for example to change the exit address. This server chooses the route by user and domain, so clients (Xray, sing-box, Mihomo, Shadowrocket) need no changes.\n\nRemote nodes default to direct fallback. The On failure button can block selected destinations instead. Local IPv6 never falls back to IPv4. If a strict node is missing a set/.dat, all traffic of its assigned users is blocked until the rules recover; its card shows a warning. Xray probes the node every 30 seconds and the bot every 5 minutes; administrators are notified about state changes.\n\nRule order: guards and torrents → block list → nodes → WARP → custom rules. A block-list entry stays blocked even if a node lists it."),
                    $t('Как подключить узел', 'Adding a node') => $t(
                        "1. На сервере-узле: Xray → Узлы выхода → «Профиль для узла» → создайте профиль. Это служебная учётка без срока и лимита; её трафик никогда не уходит на узлы того бота, поэтому два бота, указывающие друг на друга, не образуют петлю.\n2. Добавьте адрес этого сервера в список «своих» адресов межсетевого экрана узла (my_server в профилях nftables nftables). Иначе с этого адреса узел примет не больше 30 одновременных соединений и 30 новых в секунду, а весь трафик пользователей идёт с одного адреса — YouTube у нескольких человек упрётся в лимит.\n3. Здесь: «Добавить выход → Удалённый сервер» и вставьте ссылку. Сообщение со ссылкой бот удалит. Принимаются REALITY, WebSocket/XHTTP с TLS, Trojan gRPC с TLS; ссылки без проверки сервера не принимаются.\n4. «Маршруты» → например «YouTube», затем «Пользователи» — отметьте, кому включить. По умолчанию узел не включён никому. Флажок «Новым пользователям: да» включает узел каждому новому пользователю сразу при создании.",
                        "1. On the node server: Xray → Exit nodes → Node profile → create one. It is a service account without expiry or limits whose traffic never goes to that bot's own nodes, so two bots pointing at each other do not loop.\n2. Add this server's address to the node firewall list of own addresses (my_server in the nftables nftables profiles). Otherwise the node accepts at most 30 concurrent connections and 30 new ones per second from this address, while all users' traffic comes from one address, so YouTube for several people hits the limit.\n3. Here: Add exit → Remote server and paste the link; the bot deletes the message. REALITY, WebSocket/XHTTP with TLS and Trojan gRPC with TLS are accepted; links without server verification are rejected.\n4. Routes → e.g. YouTube, then Users — select who gets it. Nodes are enabled for nobody by default; “New users: yes” enables the node for every newly created user."),
                    $t('Подписка узла, трафик, диагностика', 'Node subscription, traffic, diagnostics') => $t(
                        "<b>«🔄 Подписка узла»</b> — адрес подписки его «Профиля для узла» (на сервере-узле: профиль → «Подписка для автообновления»). Когда на узле нажимают «Новые ключи» или меняют транспорт, прежняя ссылка перестаёт работать, а строгий узел при этом блокирует назначения. С подпиской бот сам берёт новую ссылку: раз в 6 часов и сразу после неудачной проверки узла, и пишет об этом администраторам. Подписка скачивается только по https и только с публичного адреса; новая ссылка проходит те же проверки, что вставленная вручную (поддерживаемый формат, проверка сервера, не этот же сервер). Если в подписке нет подходящей ссылки, прежняя остаётся, а карточка показывает ошибку. <code>0</code> отключает подписку. Подписка — это доверие к администратору узла: он и так получает трафик выбранных назначений.\n\n<b>Трафик через узел</b> копится с момента сброса и не обнуляется при перезапуске Xray (раньше показывался только с последнего запуска, а частые правки узлов перезапускали Xray). Учитываются и пробы живости. «🧹 Сбросить счётчик трафика» начинает подсчёт заново.\n\n<b>Если узел не отвечает</b>, бот дополнительно проверяет, открывается ли TCP до его адреса. «Адрес узла недоступен по TCP» — сервер выключен, порт закрыт или адрес сменился. «TCP до узла есть» — сервер жив, но подключение не работает: обычно устарела ссылка (новые ключи, другой транспорт), межсетевой экран узла ограничивает адрес этого сервера или профиль на узле в режиме «Выход: только IPv6» без подготовленной сети.",
                        "<b>“🔄 Node subscription”</b> is the subscription address of its Node profile (on the node server: the profile → Subscription for auto-update). When New keys is pressed or the transport changes on the node, the old link stops working, and a strict node then blocks its destinations. With a subscription the bot takes the new link itself: every 6 hours and right after a failed node check, and tells the admins. The subscription is downloaded only over https and only from a public address; the new link passes the same checks as one pasted by hand (supported format, server verification, not this very server). If the subscription has no suitable link, the old one stays and the card shows the error. <code>0</code> turns the subscription off. A subscription means trusting the node admin, who receives the traffic of the selected destinations anyway.\n\n<b>Traffic through the node</b> accumulates since the last reset and is not zeroed when Xray restarts (before, only the current run was shown, and node changes used to restart Xray). Liveness probes are counted too. Diagnostics → Reset traffic counter starts counting again after confirmation; user counters stay unchanged.\n\n<b>If the node does not answer</b>, the bot also checks whether TCP to its address opens. “The node address is unreachable over TCP” means the server is down, the port is closed or the address changed. “TCP to the node works” means the server is alive but the connection does not work: usually the link is outdated (new keys, another transport), the node firewall limits this server's address, or the profile on the node is in “Egress: IPv6 only” mode without a prepared network."),
                    $t('Выход через IPv6', 'IPv6 egress') => $t(
                        "«IPv6 этого сервера» создаёт локальный выход. Маршруты, наборы .srs/.mrs и выбор пользователей работают как у удалённой ноды. Сначала администратор готовит IPv6 и firewall по инструкции README; без сети выбранные назначения остаются недоступны.\n\nНа сервере с IPv6 можно создать «Профиль для узла» и переключить его на «Выход: только IPv6». На другом сервере добавьте его ссылку как обычную ноду и выберите «При отказе: блокировать», чтобы не возвращаться на IPv4. Между серверами соединение может идти по IPv4.\n\nДомен должен иметь AAAA-запись. IP/CIDR выбирает маршрут, но не преобразует IPv4 в IPv6. Если клиент передаёт IPv4, нужен sniffing с заменой назначения доменом (routeOnly выключен); если домен распознать нельзя, соединение будет закрыто. Сервис сам определяет страну и показ рекламы: IPv6 не гарантирует ни страну, ни отсутствие рекламы.",
                        "This server IPv6 creates a local exit with the same routes, .srs/.mrs sets and user selection. The administrator must prepare host IPv6 and the firewall using the README first; selected destinations stay unavailable without it.\n\nOn the IPv6 server, create a Node profile and select Egress: IPv6 only. Add its link as a node on another server and select On failure: block to prevent IPv4 fallback. The connection between servers can use IPv4.\n\nDomains need AAAA records. IP/CIDR selects a route without translating IPv4 into IPv6. If the client sends an IPv4 address, sniffing must replace it with a domain (routeOnly off); an unrecognized domain fails closed. The service decides location and advertising; IPv6 guarantees neither a country nor absence of ads."),
                    $t('Строгий режим', 'Strict mode') => $t(
                        "Строгий узел — локальный IPv6 или нода с «При отказе: блок». Запасного выхода у него нет, поэтому без полного списка маршрутов нельзя понять, какой трафик можно выпустить: бот тогда блокирует весь трафик назначенных пользователей.\n\nЧтобы этого не случалось по ошибке ввода, строгий узел не принимает записи, которые нельзя собрать: набор .srs/.mrs, который не скачался или пуст, запись geosite:/geoip:/ext: без нужного .dat и неверную запись. Для geosite:/geoip: и ext: из routes → dat бот сначала сам скачивает .dat. Непринятые записи перечислены в ответе. Включить строгий режим, сам узел, запись или набор тоже нельзя, пока они не готовы.\n\nЕсли готовность пропала позже (кэш набора удалён, .dat пропал), блокировка включается сама, карточка узла показывает ⛔, а после восстановления правил блок снимается. Если строгий узел не отвечает, его назначения блокируются, и бот пишет об этом администраторам; «Куда пойдёт домен» тоже показывает, что соединение будет закрыто.\n\nСлужебный профиль с «Выход: только IPv6» без подготовленной сети IPv6 блокирует весь свой трафик: карточка профиля предупреждает об этом. Файл config/ipv6-egress.json подключает сеть IPv6 к контейнеру xr. Если он повреждён, сеть остаётся подключённой, обычный выход по-прежнему только IPv4, а бот просит повторить подготовку.",
                        "A strict node is the local IPv6 exit or a node set to On failure: block. It has no fallback, so without a complete route list the bot cannot tell which traffic may leave and blocks all traffic of the assigned users.\n\nTo keep a typo from doing that, a strict node rejects entries it cannot build: a .srs/.mrs set that failed to download or is empty, a geosite:/geoip:/ext: entry without its .dat and an invalid entry. For geosite:/geoip: and ext: from routes → dat the bot downloads the .dat first. Rejected entries are listed in the reply. Strict mode, the node, an entry or a set also cannot be turned on while they are not ready.\n\nIf readiness is lost later (the set cache is removed, a .dat disappears), the block turns on by itself, the node card shows ⛔, and the block is lifted once the rules recover. If a strict node does not answer, its destinations are blocked and administrators are notified; Where a domain goes also says that the connection will be closed.\n\nA node profile set to Egress: IPv6 only blocks all its traffic until the IPv6 network is prepared; the profile card warns about it. The config/ipv6-egress.json file attaches the IPv6 network to the xr container. If it is damaged, the network stays attached, the regular exit stays IPv4 only and the bot asks to repeat the preparation."),
                    $t('Маршруты и наборы правил', 'Routes and rule sets') => $t(
                        "Записи как в Vless → routes: domain:, full:, keyword:, regexp:, IPv4/IPv6[/cidr], geosite:/geoip: (встроенные .dat) и ext:/extip: (свои .dat из routes → dat). Запись с ⏳ ждёт скачивания .dat и пока не действует. «Очистить всё» после подтверждения удаляет все записи маршрутов узла; наборы .srs/.mrs и пользователи остаются.\n\nДля Xray .dat в меню наборов есть отдельная кнопка: источник HTTPS, тип GeoSite/GeoIP и категории. Обновление — в общем реестре .dat и по его расписанию.\n\n«Наборы .srs/.mrs» — ссылки https:// на наборы sing-box и Mihomo. Серверный Xray этих форматов не читает: бот скачивает набор, раскладывает его на домены и подсети и обновляет раз в сутки и по «Обновить». Для .mrs укажите тип: domain или ipcidr. Ограничения: скачивание до 16 МиБ, распаковка до 32 МиБ, разобранный набор до 8 МиБ и 200 000 записей. При ошибке или превышении лимита сохраняется прежний рабочий набор.\n\n«Копировать из WARP» и «Копировать из списка VPN (pac)» берут включённые записи из Vless → routes. «Перенести из WARP» ещё и убирает их из WARP: подписки sing-box и Mihomo сами отправляют домены WARP в WARP, и до узла такие домены бы не дошли.\n\nQUIC к доменам узла по умолчанию блокируется: браузер сразу переходит на TCP, и тот идёт через узел.",
                        "Entries as in Vless → routes: domain:, full:, keyword:, regexp:, IPv4/IPv6[/cidr], geosite:/geoip: (built-in .dat) and ext:/extip: (own .dat from routes → dat). ⏳ means the .dat is not downloaded yet. Clear all deletes all route entries of the node after confirmation; sets .srs/.mrs and users stay.\n\nFor Xray .dat use the separate button in the sets menu: HTTPS source, GeoSite/GeoIP type and categories. Update files in the shared .dat registry or on its schedule.\n\nRule sets are https:// links to sing-box (.srs) and Mihomo (.mrs) sets. Server-side Xray cannot read them, so the bot downloads, expands them to domains and subnets and refreshes daily and on Refresh. For .mrs set the type: domain or ipcidr. Limits: download up to 16 MiB, decompression up to 32 MiB, parsed set up to 8 MiB and 200,000 entries. A failure or exceeded limit keeps the previous working set.\n\nCopy from WARP / Copy from the VPN list (pac) take enabled entries from Vless → routes. Move from WARP also removes them from WARP: sing-box and Mihomo subscriptions send WARP domains to WARP themselves, so they would never reach the node.\n\nQUIC to node domains is blocked by default so browsers fall back to TCP through the node."),
                    $t('Сервисы, копирование, экспорт и импорт', 'Services, copying, export and import') => $t(
                        "<b>«📚 Сервисы»</b> в «Маршрутах» — готовые списки доменов одной кнопкой: YouTube, ChatGPT/OpenAI, Gemini, Netflix, Spotify, Discord, Instagram. ✅ — все записи набора уже есть у узла; повторное нажатие убирает записи этого набора, остальные маршруты не трогает. Наборы не зависят от geosite.dat. У Instagram в наборе и <code>fbcdn.net</code> — через узел пойдут и картинки Facebook. Голосовые звонки Discord идут по UDP на адреса без домена и через узел не пройдут.\n\n<b>«📋 В другой узел»</b> добавляет маршруты (с их состоянием ✅/⏸) и наборы .srs/.mrs к выбранному узлу; повторы пропускаются, его собственные записи остаются, пользователи не копируются.\n\n<b>«📤 Экспорт»</b> присылает файл <code>.txt</code>: запись на строку, выключенные — с <code># off: </code>, наборы — строки <code>set: ссылка</code> (для .mrs — <code>set: ipcidr ссылка</code>). <b>«📥 Импорт»</b> принимает такой файл или тот же текст сообщением — так маршруты переносятся на другой узел или сервер. Записи добавляются к имеющимся, неверные строки пропускаются и считаются в итоге.",
                        "<b>📚 Services</b> in Routes adds ready domain lists with one tap: YouTube, ChatGPT/OpenAI, Gemini, Netflix, Spotify, Discord, Instagram. ✅ means the node already has every entry of the set; tapping again removes that set's entries and leaves other routes alone. The sets do not depend on geosite.dat. The Instagram set includes <code>fbcdn.net</code>, so Facebook images go through the node too. Discord voice calls use UDP to addresses without a domain and do not go through the node.\n\n<b>📋 To another node</b> adds the routes (with their ✅/⏸ state) and .srs/.mrs sets to the chosen node; duplicates are skipped, its own entries stay, users are not copied.\n\n<b>📤 Export</b> sends a <code>.txt</code> file: one entry per line, disabled ones with <code># off: </code>, sets as <code>set: link</code> lines (for .mrs, <code>set: ipcidr link</code>). <b>📥 Import</b> takes such a file or the same text as a message, so routes move to another node or server. Entries are added to the existing ones; invalid lines are skipped and counted in the result."),
                    $t('Куда пойдёт домен, скорость, доступность', 'Where a domain goes, speed, availability') => $t(
                        "<b>«🧭 Куда пойдёт домен»</b> (в списке узлов): введите домен или адрес, а через пробел — пользователя Xray, например <code>chatgpt.com alice</code>. Без пользователя бот покажет маршрут для пользователя без узлов и для пользователей каждого узла. Ответ даёт само ядро Xray: бот запускает в контейнере xr временный Xray с правилами сервера в том же порядке и смотрит, какое правило сработало, поэтому учитываются geosite/ext, regexp и разрешение домена в адрес. Итог: через узел, блокировка, WARP или напрямую, каким правилом и какой записью. Проверяется TCP 443; правила по источнику, протоколу и процессу без настоящего соединения не проверить, они не участвуют.\n\n<b>«⚡ Скорость»</b> в диагностике узла скачивает до 50 МБ с Cloudflare через узел и ещё до 50 МБ напрямую с этого сервера (до 20 секунд на каждый путь). Показывает среднюю скорость одного соединения в Мбит/с с учётом подключения и разгона TCP. Это приблизительная оценка: результат зависит от сети и сервера Cloudflare и не измеряет скорость YouTube или вашего устройства. При повторе цифры могут отличаться; обрыв соединения показывается как ошибка.\n\n<b>Доступность за 24 ч</b> в карточке узла — доля удачных проверок (бот проверяет узел каждые 5 минут, «Проверить» тоже считается) и время последних сбоев; подряд идущие отказы показываются одним сбоем «начало–конец».\n\n<b>Страна YouTube.</b> Раз в сутки бот делает полную проверку узла и, если YouTube стал видеть через узел другую страну, пишет администраторам.",
                        "<b>🧭 Where a domain goes</b> (in the node list): enter a domain or address and, after a space, an Xray user, e.g. <code>chatgpt.com alice</code>. Without a user the bot shows the route for a user without nodes and for users of each node. The answer comes from the Xray core itself: the bot starts a temporary Xray in the xr container with the server's rules in the same order and sees which rule matched, so geosite/ext, regexp and resolving the domain to an address are all taken into account. Result: through a node, blocked, WARP or direct, by which rule and which entry. TCP 443 is checked; rules by source, protocol or process cannot be checked without a real connection and do not take part.\n\n<b>⚡ Speed</b> in node diagnostics downloads up to 50 MB from Cloudflare through the node and up to another 50 MB directly from this server (up to 20 seconds per path). It shows the average speed of one connection in Mbit/s, including connection setup and TCP ramp-up. This is an estimate: the result depends on the network and the Cloudflare server and does not measure YouTube or your device. Repeated results may differ; a broken connection is reported as an error.\n\n<b>Availability over 24 h</b> in the node card is the share of successful checks (the bot checks the node every 5 minutes, Check counts too) and the time of the last outages; consecutive failures are shown as one start–end outage.\n\n<b>YouTube country.</b> Once a day the bot runs a full node check and messages administrators if YouTube starts seeing another country through the node."),
                    $t('Важно', 'Notes') => $t(
                        "• Нужно распознавание доменов (Xray → DPI → sniffing) без routeOnly: иначе правила по доменам не сработают или видео пойдёт с серверов страны этого сервера.\n• Трафик через узел проходит через оба сервера и считается на обоих.\n• Работает для пользователей Xray. Пользователи других протоколов могут подключаться к боту на узле напрямую.\n• Если клиентская программа сама отправляет часть доменов мимо VPN, до этого сервера такой трафик не дойдёт.\n• «Проверить» показывает страну выхода и страну, которую видит YouTube: она может отличаться от страны сервера.\n• Живость узла Xray проверяет пробой раз в 10 секунд. Если узел не ответил на все пробы за минуту, трафик идёт напрямую, а после восстановления сам возвращается на узел. При этом режиме после перезапуска Xray первые 5–10 секунд трафик также идёт напрямую до успешной пробы. В режиме «При отказе: блок» он блокируется; локальный IPv6 не использует балансировщик.",
                        "• Domain sniffing (Xray → DPI) must be on and not routeOnly, otherwise domain rules do not match or video is served from this server's country.\n• Node traffic passes both servers and counts on both.\n• Works for Xray users. Users of other protocols can connect to the node's bot directly.\n• Domains a client sends outside the VPN never reach this server.\n• Check shows the exit country and the country YouTube sees; they can differ.\n• Xray checks the node with a probe every 10 seconds. With direct fallback enabled, if the node failed all probes within a minute, traffic goes direct and returns to the node by itself once it recovers. In this mode, after an Xray restart traffic also goes direct for the first 5–10 seconds until a successful probe. On failure: block blocks it instead; local IPv6 has no balancer."),
                ]];
            case 'xdrive':
                return ['XDRIVE', '/xdrive', [
                $t('Что такое XDRIVE и когда он нужен', 'What XDRIVE is and when to use it') => $t(
                    "Обычно клиент подключается к серверу напрямую: по адресу и порту. Если адрес сервера заблокирован или провайдер пускает только к разрешённому списку сайтов (белые списки), такое подключение не проходит, как бы оно ни было замаскировано.\n\n<b>XDRIVE</b> устроен иначе. Сервер и клиент не соединяются друг с другом вообще: оба читают и пишут небольшие файлы в одной папке облачного хранилища — Яндекс Диска, Google Drive, своего Nextcloud. Клиент кладёт в папку запрос, сервер забирает его, выполняет и кладёт ответ.\n\n<b>Что это даёт:</b>\n• клиенту нужен доступ только к хранилищу — адрес вашего сервера он не знает и к нему не обращается;\n• сервер не открывает для XDRIVE ни одного порта;\n• снаружи видно лишь обычную работу с облачным диском.\n\n<b>Чем приходится платить:</b>\n• скорость и отклик хуже прямого подключения и зависят от хранилища;\n• клиент — только Xray, другие приложения этот транспорт не знают;\n• в профиле клиента лежит доступ к хранилищу, поэтому XDRIVE годится для себя и близких, а не для раздачи посторонним.\n\nЭто запасной канал на случай, когда остальные протоколы бота не проходят, а не замена им.",
                    "Normally a client connects to the server directly, by address and port. If the server address is blocked or the provider only allows a list of approved sites (allowlists), such a connection fails no matter how well it is disguised.\n\n<b>XDRIVE</b> works differently. The server and client never connect to each other at all: both read and write small files in one folder of a cloud storage such as Yandex Disk, Google Drive or your own Nextcloud. The client puts a request into the folder, the server picks it up, executes it and puts the response back.\n\n<b>What this gives:</b>\n• the client only needs access to the storage: it does not know your server address and never contacts it;\n• the server opens no ports for XDRIVE;\n• from outside it looks like ordinary work with a cloud drive.\n\n<b>The price:</b>\n• speed and latency are worse than a direct connection and depend on the storage;\n• the client can only be Xray; other apps do not know this transport;\n• the client profile contains access to the storage, so XDRIVE is for yourself and people close to you, not for handing out to strangers.\n\nIt is a fallback channel for when the bot's other protocols do not get through, not a replacement for them."),
                $t('Что понадобится', 'What you need') => $t(
                    "<b>1. Ядро Xray с XDRIVE.</b> Транспорт появился в оригинальном ядре 26.9.30 и в форке 26.10.5. Откройте Xray → «версии» и выберите подходящее ядро. Со старым ядром бот не даст включить XDRIVE, а если переключить ядро на старое позже — вход XDRIVE отключится сам, остальное продолжит работать.\n\n<b>2. Основной вход VLESS.</b> XDRIVE обслуживает тех же пользователей, что и основной вход Xray: отдельно заводить никого не нужно, трафик и лимиты считаются общие. Если выбран транспорт с другим протоколом (например, Trojan), XDRIVE не включится.\n\n<b>3. Хранилище.</b> Подойдёт любое с доступом по WebDAV (Яндекс Диск, Nextcloud, ownCloud и другие) или Google Drive. Заведите под XDRIVE <b>отдельную учётную запись или хотя бы отдельную пустую папку</b>: сервер и клиенты постоянно создают и удаляют в ней файлы.\n\n<b>4. Клиент Xray.</b> На устройстве пользователя нужен Xray той же версии или новее (26.9.30+) либо приложение на его основе, которое принимает готовый конфиг JSON.\n\n<b>5. Доступ сервера в Интернет к хранилищу.</b> Сервер сам обращается к хранилищу — кнопка «Проверить хранилище» покажет, получается ли.",
                    "<b>1. An Xray core with XDRIVE.</b> The transport appeared in the original core 26.9.30 and in fork 26.10.5. Open Xray → versions and pick a suitable core. With an older core the bot will not let you enable XDRIVE, and if you switch to an older core later the XDRIVE inbound turns off by itself while everything else keeps working.\n\n<b>2. A main VLESS inbound.</b> XDRIVE serves the same users as the main Xray inbound: nobody needs to be added separately, and traffic and limits are shared. If a transport with another protocol (e.g. Trojan) is selected, XDRIVE will not turn on.\n\n<b>3. A storage.</b> Any storage with WebDAV access (Yandex Disk, Nextcloud, ownCloud and others) or Google Drive will do. Use <b>a separate account, or at least a separate empty folder</b>, for XDRIVE: the server and clients keep creating and deleting files in it.\n\n<b>4. An Xray client.</b> The user's device needs Xray of the same version or newer (26.9.30+), or an app based on it that accepts a complete JSON config.\n\n<b>5. Internet access from the server to the storage.</b> The server contacts the storage itself; the Check storage button shows whether that works."),
                $t('Настройка: Яндекс Диск и другие WebDAV', 'Setup: Yandex Disk and other WebDAV') => $t(
                    "<b>Подготовка в хранилище.</b>\n1. Создайте в хранилище пустую папку, например <code>vpnbot-xdrive</code>.\n2. Получите пароль для WebDAV. У Яндекса это отдельный <b>пароль приложения</b> (Яндекс ID → Безопасность → Пароли приложений → «Файлы»), обычный пароль от аккаунта не подойдёт. В Nextcloud — пароль приложения из настроек безопасности.\n\n<b>Настройка в боте</b> (Xray → XDRIVE, хранилище «WebDAV»):\n• <b>Адрес WebDAV</b> — без папки. Яндекс Диск: <code>https://webdav.yandex.ru</code>. Nextcloud: <code>https://ваш-сайт/remote.php/dav/files/логин</code>.\n• <b>Папка</b> — имя созданной папки: латинские буквы, цифры, точка, дефис, подчёркивание.\n• <b>Логин</b> и <b>Пароль</b> — учётная запись хранилища и пароль приложения. Сообщение с паролем бот сразу удаляет, в меню значения скрыты.\n\n<b>Проверка и включение.</b>\n1. Нажмите <b>«Проверить хранилище»</b>: бот запишет в папку пробный файл, прочитает, найдёт в списке и удалит. Ответ скажет, что именно не так: адрес, пароль, отсутствующая папка или запрет записи.\n2. Нажмите <b>XDRIVE: выкл</b> — бот создаст ключи шифрования, проверит конфигурацию ядром и перезапустит Xray. Активные подключения к Xray при этом кратко переподключатся.\n3. Откройте <b>«Профили клиентов»</b> и отправьте файлы пользователям.\n\nАдрес должен начинаться с <code>https://</code>. С <code>http://</code> бот работать будет, но пароль хранилища пойдёт по сети открыто — меню об этом предупредит. Адреса внутренней сети и самого сервера бот не принимает.",
                    "<b>Preparing the storage.</b>\n1. Create an empty folder in the storage, e.g. <code>vpnbot-xdrive</code>.\n2. Get a WebDAV password. Yandex needs a separate <b>app password</b> (Yandex ID → Security → App passwords → Files); the ordinary account password does not work. In Nextcloud, use an app password from the security settings.\n\n<b>Setup in the bot</b> (Xray → XDRIVE, storage WebDAV):\n• <b>WebDAV address</b>: without the folder. Yandex Disk: <code>https://webdav.yandex.ru</code>. Nextcloud: <code>https://your-site/remote.php/dav/files/login</code>.\n• <b>Folder</b>: the name of the created folder: Latin letters, digits, dot, hyphen, underscore.\n• <b>Login</b> and <b>Password</b>: the storage account and the app password. The bot deletes the message with the password immediately, and the values are hidden in the menu.\n\n<b>Checking and enabling.</b>\n1. Tap <b>Check storage</b>: the bot writes a test file to the folder, reads it, finds it in the listing and deletes it. The answer says exactly what is wrong: the address, password, a missing folder or no write permission.\n2. Tap <b>XDRIVE: off</b>: the bot creates encryption keys, has the core check the configuration and restarts Xray. Active Xray connections briefly reconnect.\n3. Open <b>Client profiles</b> and send the files to users.\n\nThe address must start with <code>https://</code>. The bot works with <code>http://</code> too, but the storage password then travels over the network in the clear; the menu warns about it. The bot does not accept internal network addresses or the server's own address."),
                $t('Настройка: Google Drive', 'Setup: Google Drive') => $t(
                    "Для Google Drive ядру нужны три значения: <b>Client ID</b>, <b>Client Secret</b> и <b>Refresh Token</b>, а также <b>ID папки</b>.\n\n<b>Как их получить.</b>\n1. В Google Cloud Console создайте проект и включите в нём <b>Google Drive API</b>.\n2. Настройте экран согласия OAuth и переведите приложение в статус <b>«В рабочей среде»</b>. Пока приложение в статусе «Тестирование», Google отзывает Refresh Token через 7 дней, и XDRIVE перестанет работать.\n3. Создайте учётные данные «Идентификатор клиента OAuth» — получите Client ID и Client Secret.\n4. Получите Refresh Token для области доступа <code>https://www.googleapis.com/auth/drive</code>, войдя под той учётной записью Google, чей диск будет использоваться.\n5. Создайте на диске пустую папку. Её ID — часть ссылки после <code>/folders/</code>.\n\n<b>Настройка в боте</b> (хранилище «Google Drive»): задайте ID папки и три значения, нажмите «Проверить хранилище», затем включите XDRIVE.\n\n<b>Что учесть.</b>\n• Client Secret и Refresh Token дают доступ ко всему диску этой учётной записи, и они попадают в профиль каждого клиента. Используйте отдельную учётную запись Google без личных данных.\n• У Google есть ограничения на число запросов. Если в журнале Xray появляются сообщения о превышении лимита, увеличьте «Опрос в простое».\n• Проверка из бота подтверждает вход и доступ к папке; запись и удаление для Google Drive она не пробует.",
                    "For Google Drive the core needs three values, <b>Client ID</b>, <b>Client Secret</b> and <b>Refresh Token</b>, plus the <b>folder ID</b>.\n\n<b>How to get them.</b>\n1. In Google Cloud Console create a project and enable the <b>Google Drive API</b> in it.\n2. Configure the OAuth consent screen and set the app status to <b>In production</b>. While the app is in Testing, Google revokes the Refresh Token after 7 days and XDRIVE stops working.\n3. Create OAuth client ID credentials to get the Client ID and Client Secret.\n4. Get a Refresh Token for the scope <code>https://www.googleapis.com/auth/drive</code>, signing in with the Google account whose drive will be used.\n5. Create an empty folder on the drive. Its ID is the part of the link after <code>/folders/</code>.\n\n<b>Setup in the bot</b> (storage Google Drive): set the folder ID and the three values, tap Check storage, then enable XDRIVE.\n\n<b>What to keep in mind.</b>\n• The Client Secret and Refresh Token give access to the whole drive of that account, and they end up in every client profile. Use a separate Google account without personal data.\n• Google limits the number of requests. If the Xray log shows rate limit messages, increase Idle polling.\n• The bot's check confirms sign-in and access to the folder; for Google Drive it does not try writing and deleting."),
                $t('Настройка: S3 (Yandex Cloud, R2, MinIO)', 'Setup: S3 (Yandex Cloud, R2, MinIO)') => $t(
                    "S3 — объектное хранилище с общим протоколом Amazon: хранилище Yandex Cloud, Cloudflare R2, Backblaze B2, VK Cloud, свой MinIO и другие. Хранилище «S3» появилось в оригинальном ядре <b>26.10.29</b>; форк его пока не поддерживает, а клиентам нужен Xray 26.10.29+.\n\n<b>Подготовка в хранилище.</b>\n1. Создайте бакет, например <code>vpnbot-xdrive-1</code>.\n2. Создайте ключ доступа (Access Key) с правом чтения и записи <b>только в этот бакет</b>: ключ попадёт в профили клиентов. В Yandex Cloud — сервисный аккаунт с ролью <code>storage.editor</code> на бакет и статический ключ.\n\n<b>Настройка в боте</b> (Xray → XDRIVE, хранилище «S3»):\n• <b>Адрес S3</b> — без бакета. Yandex: <code>https://storage.yandexcloud.net</code>; R2: <code>https://&lt;аккаунт&gt;.r2.cloudflarestorage.com</code>; MinIO: адрес вашего сервера.\n• <b>Бакет</b> — его имя. <b>Регион</b> — регион подписи: Yandex <code>ru-central1</code>, R2 <code>auto</code>, MinIO и большинство остальных — <code>us-east-1</code> (по умолчанию; прочерк сбрасывает).\n• <b>path-style</b> — бакет в пути адреса (<code>адрес/бакет/</code>). Включён по умолчанию: так работают Yandex, R2 и MinIO. Выключите, только если хранилище требует бакет в имени узла (<code>бакет.адрес</code>), как новые бакеты Amazon S3.\n• <b>Папка</b> — префикс внутри бакета, например <code>vpnbot-xdrive</code>; создавать заранее не нужно.\n• <b>Ключ доступа</b> и <b>Секретный ключ</b> — сообщения с ними бот сразу удаляет.\n\n<b>Проверка.</b> «Проверить хранилище» подписывает запросы так же, как ядро (AWS SigV4): получает список, пишет, читает и удаляет пробный объект. Ответ подскажет: неверный ключ, нет бакета, не тот регион или нет права записи.",
                    "S3 is object storage with Amazon's common protocol: Yandex Object Storage, Cloudflare R2, Backblaze B2, VK Cloud, your own MinIO and others. The S3 storage appeared in the original core <b>26.10.29</b>; the fork does not support it yet, and clients need Xray 26.10.29+.\n\n<b>Preparing the storage.</b>\n1. Create a bucket, e.g. <code>vpnbot-xdrive-1</code>.\n2. Create an access key with read and write access <b>to this bucket only</b>: the key goes into client profiles. In Yandex Cloud, a service account with the <code>storage.editor</code> role on the bucket and a static key.\n\n<b>Setup in the bot</b> (Xray → XDRIVE, storage S3):\n• <b>S3 address</b>: without the bucket. Yandex: <code>https://storage.yandexcloud.net</code>; R2: <code>https://&lt;account&gt;.r2.cloudflarestorage.com</code>; MinIO: your server address.\n• <b>Bucket</b>: its name. <b>Region</b>: the signature region: Yandex <code>ru-central1</code>, R2 <code>auto</code>, MinIO and most others <code>us-east-1</code> (the default; a dash resets it).\n• <b>path-style</b>: the bucket in the address path (<code>address/bucket/</code>). On by default: Yandex, R2 and MinIO work this way. Turn it off only if the storage needs the bucket in the host name (<code>bucket.address</code>), like new Amazon S3 buckets.\n• <b>Folder</b>: a prefix inside the bucket, e.g. <code>vpnbot-xdrive</code>; nothing has to be created in advance.\n• <b>Access key</b> and <b>Secret key</b>: the bot deletes messages with them immediately.\n\n<b>Checking.</b> Check storage signs requests the way the core does (AWS SigV4): it lists, writes, reads and deletes a test object. The answer points to the problem: a wrong key, a missing bucket, a wrong region or no write permission."),
                $t('Свой шаблон', 'Custom template') => $t(
                    "Если хранилище не WebDAV и не Google Drive, но у него есть HTTP-интерфейс для записи, чтения, удаления и получения списка файлов, его можно описать шаблоном. Это режим для тех, кто готов читать документацию своего сервиса.\n\n<b>Шаблон</b> — объект JSON с четырьмя действиями: <code>put</code>, <code>get</code>, <code>delete</code>, <code>list</code>. У каждого — <code>method</code> и <code>url</code>, при необходимости <code>headers</code> и <code>body</code>. У <code>list</code> обязателен <code>namesRegex</code> — регулярное выражение с одной группой, которая вынимает имена файлов из ответа сервиса.\n\n<b>Подстановки:</b> <code>{folder}</code> — папка, <code>{name}</code> — имя файла, <code>{prefix}</code> — начало имени для списка, <code>{secret0}</code>, <code>{secret1}</code>… — секреты по порядку, <code>{data}</code> — содержимое в base64 (для <code>body</code>).\n\n<b>Вход в сервис</b> задаётся в <code>auth</code>: <code>basic</code> (логин и пароль), <code>static</code> (готовый заголовок) или <code>oauth2</code> (получение токена по адресу <code>tokenUrl</code>).\n\n<code>\"flatten\": true</code> нужен хранилищам без вложенных папок: имена вида <code>streams/…/…</code> записываются одним именем через «~».\n\nВ боте: хранилище «template», затем «Шаблон» (JSON одним сообщением), «Папка» и «Секреты» (по одному на строку). Кнопка «Проверить хранилище» свой шаблон не проверяет: перед включением бот убеждается только в том, что ядро принимает конфигурацию, а работу проверяйте клиентом.",
                    "If the storage is neither WebDAV nor Google Drive but has an HTTP interface to write, read, delete and list files, it can be described with a template. This mode is for those ready to read their service's documentation.\n\n<b>A template</b> is a JSON object with four actions: <code>put</code>, <code>get</code>, <code>delete</code>, <code>list</code>. Each has <code>method</code> and <code>url</code>, and <code>headers</code> and <code>body</code> if needed. <code>list</code> requires <code>namesRegex</code>: a regular expression with one group that extracts file names from the service response.\n\n<b>Placeholders:</b> <code>{folder}</code>: the folder, <code>{name}</code>: the file name, <code>{prefix}</code>: the start of the name for listing, <code>{secret0}</code>, <code>{secret1}</code>…: secrets in order, <code>{data}</code>: the contents in base64 (for <code>body</code>).\n\n<b>Signing in to the service</b> is set in <code>auth</code>: <code>basic</code> (login and password), <code>static</code> (a ready header) or <code>oauth2</code> (a token obtained from <code>tokenUrl</code>).\n\n<code>\"flatten\": true</code> is for storages without nested folders: names like <code>streams/…/…</code> are written as one name joined with \"~\".\n\nIn the bot: storage template, then Template (JSON in one message), Folder and Secrets (one per line). Check storage does not test a custom template: before enabling, the bot only makes sure the core accepts the configuration, so test it with a client."),
                $t('Профили клиентов и как пользоваться', 'Client profiles and usage') => $t(
                    "<b>Выдача.</b> Xray → XDRIVE → «Профили клиентов» → выберите пользователя. Бот пришлёт файл <code>xdrive-имя.json</code> — готовый конфиг Xray именно для него.\n\n<b>Запуск на компьютере.</b>\n1. Установите Xray версии 26.9.30 или новее.\n2. Запустите: <code>xray run -c xdrive-имя.json</code>\n3. В браузере или системе укажите прокси <b>SOCKS5 127.0.0.1:10808</b> или <b>HTTP 127.0.0.1:10809</b>.\n\n<b>Приложения на основе Xray</b> (на телефоне или с графическим интерфейсом) подойдут, если умеют импортировать полный конфиг JSON и собраны на ядре 26.9.30+. Ссылки <code>vless://</code> и QR-кода для XDRIVE нет: настройки хранилища в них не помещаются. sing-box и Mihomo этот транспорт не поддерживают.\n\n<b>Что получает пользователь.</b> Тот же выход в Интернет и те же правила, что через основной вход Xray: блокировка торрентов, фильтры, маршруты. Трафик через XDRIVE добавляется к счётчикам пользователя, лимиты общие.\n\n<b>Первое подключение</b> занимает до нескольких секунд — столько сервер в простое ждёт между проверками папки. Дальше обмен идёт быстрее.\n\n<b>Новый или удалённый пользователь.</b> Список пользователей XDRIVE всегда повторяет основной вход: новому достаточно выдать профиль, у удалённого профиль перестаёт работать сразу.",
                    "<b>Issuing.</b> Xray → XDRIVE → Client profiles → choose a user. The bot sends the file <code>xdrive-name.json</code>: a ready Xray config for that user.\n\n<b>Running on a computer.</b>\n1. Install Xray 26.9.30 or newer.\n2. Run: <code>xray run -c xdrive-name.json</code>\n3. In the browser or system set the proxy to <b>SOCKS5 127.0.0.1:10808</b> or <b>HTTP 127.0.0.1:10809</b>.\n\n<b>Xray-based apps</b> (on a phone or with a GUI) work if they can import a complete JSON config and are built on core 26.9.30+. There is no <code>vless://</code> link or QR code for XDRIVE: the storage settings do not fit into them. sing-box and Mihomo do not support this transport.\n\n<b>What the user gets.</b> The same Internet egress and the same rules as through the main Xray inbound: torrent blocking, filters, routes. XDRIVE traffic adds to the user's counters, and limits are shared.\n\n<b>The first connection</b> takes up to a few seconds: that is how long the idle server waits between folder checks. After that the exchange is faster.\n\n<b>A new or deleted user.</b> The XDRIVE user list always mirrors the main inbound: a new user just needs a profile, and a deleted user's profile stops working at once."),
                $t('Безопасность и ключи', 'Security and keys') => $t(
                    "<b>Что видит хранилище.</b> Владелец хранилища видит файлы обмена, их размер и время. Содержимое он прочитать не может: на входе XDRIVE всегда включено шифрование VLESS (ML-KEM-768), его нельзя выключить. Ключи XDRIVE свои и не связаны с настройкой «VLESS Encryption» основного входа.\n\n<b>Что лежит в профиле.</b> Доступ к хранилищу (логин и пароль либо ключи Google), ключ шифрования и идентификатор пользователя. Поэтому:\n• выдавайте профили только тем, кому доверяете;\n• держите под XDRIVE отдельную учётную запись хранилища без личных файлов — у каждого клиента есть к ней полный доступ;\n• один клиент может мешать другим, удаляя файлы в папке.\n\n<b>Если профиль утёк.</b>\n1. Удалите или пересоздайте пользователя в Xray — его идентификатор перестанет приниматься.\n2. Нажмите <b>«Новые ключи»</b> — все старые профили XDRIVE перестанут работать.\n3. Смените пароль приложения в хранилище и задайте новый в боте.\n4. Раздайте новые профили.\n\n<b>Где это хранится на сервере.</b> Настройки XDRIVE вместе с доступом к хранилищу лежат в настройках бота и входят в резервную копию — храните её так же бережно, как остальные секреты.\n\nСервер не видит IP-адресов клиентов XDRIVE: все они приходят «из хранилища». Ограничение по числу IP для таких подключений не действует.",
                    "<b>What the storage sees.</b> The storage owner sees the exchange files, their size and time. They cannot read the contents: VLESS encryption (ML-KEM-768) is always on for the XDRIVE inbound and cannot be turned off. XDRIVE keys are its own and unrelated to the VLESS Encryption setting of the main inbound.\n\n<b>What the profile contains.</b> Access to the storage (login and password or Google keys), the encryption key and the user ID. Therefore:\n• give profiles only to people you trust;\n• keep a separate storage account without personal files for XDRIVE: every client has full access to it;\n• one client can disturb others by deleting files in the folder.\n\n<b>If a profile has leaked.</b>\n1. Delete or recreate the user in Xray: their ID will no longer be accepted.\n2. Tap <b>New keys</b>: all old XDRIVE profiles stop working.\n3. Change the app password in the storage and set the new one in the bot.\n4. Hand out new profiles.\n\n<b>Where it is stored on the server.</b> XDRIVE settings, including the storage access, are kept in the bot settings and are part of the backup: keep the backup as carefully as your other secrets.\n\nThe server does not see the IP addresses of XDRIVE clients: they all come \"from the storage\". The IP count limit does not apply to such connections."),
                $t('Скорость, опрос и лимиты хранилища', 'Speed, polling and storage limits') => $t(
                    "Скорость XDRIVE определяет хранилище: каждая порция данных — отдельная загрузка и скачивание файла. Для переписки, почты и обычных страниц этого хватает; для видео и больших загрузок канал медленный, а у некоторых хранилищ ещё и ограничен по объёму трафика.\n\n<b>Опрос в простое.</b> Пока подключений нет, сервер периодически спрашивает хранилище, не появился ли новый клиент. По умолчанию — дважды в секунду. Параметр «Опрос в простое» задаёт этот интервал в миллисекундах, от 500 до 10000:\n• <b>меньше</b> — первое подключение быстрее, запросов к хранилищу больше;\n• <b>больше</b> — запросов меньше, но первое подключение ждёт до заданного времени.\n\nВо время обмена данными ядро опрашивает хранилище чаще само, этот параметр на скорость передачи не влияет. Значение записывается и в профили клиентов: после изменения раздайте их заново, иначе старые клиенты продолжат работать с прежним интервалом.\n\n<b>Если хранилище ограничивает запросы.</b> Признаки — подключение то работает, то нет, в журнале Xray ошибки с кодами 403 или 429. Увеличьте интервал до 2000–5000 мс и уменьшите число одновременно работающих клиентов.\n\n<b>Место в хранилище.</b> Файлы обмена удаляются после чтения, а незавершённые сессии сервер убирает через несколько минут. При аварийной остановке в папке могут остаться файлы — их можно удалить вручную, когда XDRIVE выключен.",
                    "XDRIVE speed is set by the storage: every chunk of data is a separate file upload and download. That is enough for messaging, mail and ordinary pages; for video and large downloads the channel is slow, and some storages also cap traffic volume.\n\n<b>Idle polling.</b> While there are no connections, the server periodically asks the storage whether a new client has appeared. By default twice a second. Idle polling sets this interval in milliseconds, from 500 to 10000:\n• <b>lower</b>: the first connection is faster, more requests to the storage;\n• <b>higher</b>: fewer requests, but the first connection waits up to the set time.\n\nDuring data exchange the core polls the storage more often by itself; this parameter does not affect transfer speed. The value is also written into client profiles: after a change hand them out again, otherwise old clients keep the previous interval.\n\n<b>If the storage limits requests.</b> Signs: the connection works on and off, and the Xray log shows errors with codes 403 or 429. Raise the interval to 2000–5000 ms and reduce the number of clients working at once.\n\n<b>Storage space.</b> Exchange files are deleted after reading, and the server cleans up unfinished sessions after a few minutes. After an abnormal stop files may remain in the folder; you can delete them by hand while XDRIVE is off."),
                $t('Если не работает', 'If it does not work') => $t(
                    "<b>Бот не даёт включить.</b> Он пишет причину:\n• «ядро не поддерживает» — выберите ядро 26.9.30+ в Xray → «версии»;\n• «требует основной вход VLESS» — смените транспорт Xray на вариант с VLESS;\n• «ядро отклонило конфигурацию» — чаще всего ошибка в своём шаблоне;\n• не заполнено поле — оно перечислено в меню.\n\n<b>Включён, но в меню «не работает».</b> Ядро переключили на старое или основной вход перестал быть VLESS. Верните подходящее ядро или транспорт — вход включится сам при следующем перезапуске Xray.\n\n<b>Клиент запускается, но сайты не открываются.</b>\n1. Нажмите «Проверить хранилище». Если проверка не проходит — дело в хранилище или пароле.\n2. Убедитесь, что с устройства пользователя открывается само хранилище: XDRIVE работает только там, где оно доступно.\n3. Проверьте версию Xray у клиента: нужна 26.9.30 или новее. Xray 26.10.17+ не запускает профиль, выданный старой версией бота (в нём нет Mux), — выдайте его заново.\n4. Выдайте профиль заново: после «Новых ключей», смены пароля хранилища или папки старые профили не подходят.\n\n<b>Работало и перестало у всех.</b> Истёк или отозван пароль приложения (для Google — Refresh Token, см. страницу про Google Drive), закончилось место или хранилище временно ограничило запросы.\n\n<b>Очень медленно.</b> Это свойство транспорта; попробуйте другое хранилище или используйте XDRIVE только как запасной путь.\n\n<b>Журнал.</b> Сообщения ядра о XDRIVE пишутся в журнал контейнера Xray: ищите строки с <code>transport/internet/xdrive</code>.",
                    "<b>The bot will not let you enable it.</b> It states the reason:\n• the core does not support it: choose core 26.9.30+ in Xray → versions;\n• it requires a main VLESS inbound: switch the Xray transport to a VLESS option;\n• the core rejected the configuration: most often an error in a custom template;\n• a field is empty: it is listed in the menu.\n\n<b>Enabled, but the menu says it is not working.</b> The core was switched to an older one, or the main inbound is no longer VLESS. Restore a suitable core or transport: the inbound turns on by itself at the next Xray restart.\n\n<b>The client starts, but sites do not open.</b>\n1. Tap Check storage. If the check fails, the storage or the password is the problem.\n2. Make sure the storage itself opens from the user's device: XDRIVE works only where it is reachable.\n3. Check the client's Xray version: 26.9.30 or newer is needed. Xray 26.10.17+ does not start a profile issued by an older bot version (it has no Mux): issue it again.\n4. Issue the profile again: after New keys, or a change of the storage password or folder, old profiles do not fit.\n\n<b>Worked, then stopped for everyone.</b> The app password expired or was revoked (for Google, the Refresh Token: see the Google Drive page), the space ran out, or the storage temporarily limited requests.\n\n<b>Very slow.</b> That is how the transport is; try another storage or use XDRIVE only as a fallback.\n\n<b>Log.</b> Core messages about XDRIVE go to the Xray container log: look for lines with <code>transport/internet/xdrive</code>."),
                ]];
            case 'warp':
                return ['WARP', '/warp', [
                    $t('Маршрутизация и выключение', 'Routing and disabling') => $t(
                        "WARP меняет выход в Интернет для трафика, направленного в него правилами бота или настройкой «Выход: warp» отдельного протокола. Само включение WARP не переводит в него автоматически всех пользователей и все протоколы. Сайты видят выходной адрес WARP вместо адреса VPS. Это не анонимность: оператор туннеля остаётся промежуточной стороной.\n\nВнутренний SOCKS-прокси передаёт TCP и UDP через WireGuard. При выключении WARP или потере туннеля направленные в него соединения прекращаются; автоматический прямой обход не включается. Протоколы с прямым выходом продолжают работать по своим правилам. Повторное включение восстанавливает туннель, но старым соединениям может потребоваться переподключение.",
                        "WARP changes Internet egress for traffic selected by routing rules or a protocol's Egress: warp setting. Enabling WARP does not automatically route every user and protocol through it. Websites see WARP's exit address rather than the VPS address. This is not anonymity: the tunnel provider remains an intermediary.\n\nThe internal SOCKS proxy carries TCP and UDP over WireGuard. Disabling WARP or losing the tunnel stops traffic assigned to it, without a direct fallback. Direct-egress protocols keep their own routing. Re-enabling restores the tunnel; existing connections may need to reconnect."),
                    $t('UDP и ограничения доступа', 'UDP and access limits') => $t(
                        "UDP работает там, где его поддерживают входной протокол и клиент. Переключатели UDP в TUIC и ShadowTLS сохраняют своё действие: WARP не включает запрещённый в протоколе UDP.\n\nИсключение — отдельный Shadowsocks-сервис: его параметр upstream-прокси передаёт через WARP только TCP; UDP остаётся прямым. Это описано также в меню Shadowsocks. Не считайте его переключатель WARP защитой всего UDP-трафика.\n\nВыход WARP в этой конфигурации использует IPv4. Доступ через него к loopback, локальным сетям, служебным адресам и другим контейнерам запрещён. SOCKS-порт и диапазон ответных UDP-портов предназначены только для разрешённых контейнеров; открывать их в Интернет не нужно.",
                        "UDP requires support in both the inbound protocol and the client. TUIC and ShadowTLS UDP controls still apply; WARP does not enable UDP that the protocol disables.\n\nThe standalone Shadowsocks service is an exception: its upstream proxy sends only TCP through WARP; UDP remains direct, as described in its menu. Do not treat its WARP switch as protection for all UDP traffic.\n\nThis WARP setup uses IPv4 egress. Loopback, local networks, service addresses and other containers are blocked through it. SOCKS and UDP reply ports are internal and restricted to approved containers; do not publish them to the Internet."),
                    $t('Ключ, профиль и состояние', 'Key, profile and status') => $t(
                        "«set key» задаёт лицензию WARP+; это не ключ пользователя VPN и не настройка шифрования VLESS. Смена лицензии может переподключить трафик через WARP. Если регистрация или обновление у провайдера не удались, бот сохраняет прежние настройки и сообщает об ошибке.\n\nСтатус trace относится к выходу самого контейнера WARP. Он не доказывает, что конкретный клиент попал под правило WARP: проверьте маршрутизацию и внешний IP на клиенте. При недоступном туннеле отображается off. Показанные в меню профиль и аккаунт содержат секреты доступа; не публикуйте сообщение и скриншоты с ними.\n\n<b>Туннель и SOCKS.</b> Строка «туннель» показывает, как давно было последнее рукопожатие с сервером Cloudflare: при рабочем туннеле это не больше двух-трёх минут. «SOCKS для Xray» — прокси, через который в WARP ходят Xray и остальные протоколы; он работает только при живом туннеле, чтобы трафик не ушёл с адреса сервера. Сторож в контейнере сам поднимает пропавший туннель и перезапускает прокси.\n\n<b>Включение.</b> Кнопка считает WARP включённым только после настоящего рукопожатия. Если за 15 секунд сервер Cloudflare не ответил, переключатель остаётся выключенным, а бот сообщает об этом.\n\n<b>Оборванная смена ключа.</b> Если смена ключа прервалась посередине, на сервере остаётся копия прежнего аккаунта. Бот не начнёт новую смену, пока вы не выберете: вернуть прежний аккаунт из копии или удалить копию.",
                        "Set key configures a WARP+ license, not a VPN user key or VLESS encryption. Changing it may reconnect WARP traffic. If provider registration or updating fails, the bot retains previous settings and reports the error.\n\nTrace describes the WARP container's own egress. It does not prove a particular client matches a WARP routing rule: check client routing and its external IP. An unavailable tunnel displays off. The account and profile shown in this menu contain credentials; do not publish the message or screenshots.\n\n<b>Tunnel and SOCKS.</b> The tunnel line shows how long ago the last handshake with the Cloudflare server happened: two or three minutes at most for a working tunnel. SOCKS for Xray is the proxy that Xray and the other protocols use to reach WARP; it runs only while the tunnel is alive, so traffic never leaves from the server address. The watchdog in the container restores a lost tunnel and restarts the proxy by itself.\n\n<b>Switching on.</b> The button counts WARP as on only after a real handshake. If the Cloudflare server does not answer within 15 seconds, the switch stays off and the bot says so.\n\n<b>Interrupted key change.</b> If a key change was interrupted halfway, a copy of the previous account stays on the server. The bot does not start a new change until you choose: restore the previous account from the copy or delete the copy."),
                    $t('Режим: WireGuard или MASQUE', 'Mode: WireGuard or MASQUE') => $t(
                        "WARP можно подключать к Cloudflare двумя способами. Кнопка <b>«режим»</b> в меню WARP переключает между ними.\n\n<b>WireGuard</b> — способ по умолчанию: туннель по UDP на особые порты Cloudflare. Он быстрее, но его рукопожатие легко распознаётся, и у некоторых хостингов и провайдеров он не проходит.\n\n<b>MASQUE</b> — туннель внутри обычного HTTP/3 на порт 443. Снаружи это выглядит как обращение к сайту Cloudflare, поэтому он проходит там, где WireGuard блокируют. Он не быстрее WireGuard: это запасной путь, а не ускорение. Если WireGuard у вас работает, переключаться незачем.\n\n<b>Что не меняется.</b> Режим — это только способ, которым сервер держит связь с Cloudflare. Всё, что вы настраивали, работает по-прежнему:\n• список «warp» в разделе маршрутизации Xray;\n• настройка «Выход: warp» у отдельных протоколов и переключатель «ss через warp»;\n• личные профили WARP у клиентов в шаблонах — они подключаются к Cloudflare сами, со своего устройства, и от режима сервера не зависят.\n\n<b>Как переключить.</b> Нажмите «режим: WireGuard → MASQUE». Бот по шагам:\n1. при первом переключении регистрирует в Cloudflare отдельное устройство для MASQUE (аккаунт WireGuard остаётся нетронутым, поэтому обратно можно вернуться в одно нажатие);\n2. делает пробное подключение по MASQUE, не трогая работающий WireGuard;\n3. только после удачной пробы переключает режим и ждёт ответа WARP через прокси.\n\nЕсли проба не прошла, ничего не меняется и бот сообщает причину. Если новый режим не поднялся уже после переключения, бот сам возвращает прежний. Переключение занимает от нескольких секунд до минуты; соединения, идущие через WARP, в этот момент кратко прерываются.",
                        "WARP can connect to Cloudflare in two ways. The <b>mode</b> button in the WARP menu switches between them.\n\n<b>WireGuard</b> is the default: a UDP tunnel to special Cloudflare ports. It is faster, but its handshake is easy to recognise and it does not get through with some hosting providers and ISPs.\n\n<b>MASQUE</b> is a tunnel inside ordinary HTTP/3 on port 443. From outside it looks like visiting a Cloudflare site, so it gets through where WireGuard is blocked. It is not faster than WireGuard: it is a fallback, not a speed-up. If WireGuard works for you, there is no reason to switch.\n\n<b>What does not change.</b> The mode is only how the server keeps its link to Cloudflare. Everything you have configured works as before:\n• the warp list in Xray routing;\n• the Egress: warp setting of individual protocols and the ss via warp switch;\n• personal WARP profiles of clients in templates: they connect to Cloudflare themselves from their own device and do not depend on the server mode.\n\n<b>How to switch.</b> Tap mode: WireGuard → MASQUE. The bot proceeds step by step:\n1. on the first switch it registers a separate device for MASQUE with Cloudflare (the WireGuard account stays untouched, so you can go back with one tap);\n2. it makes a trial MASQUE connection without touching the working WireGuard;\n3. only after a successful trial does it switch the mode and wait for WARP to answer through the proxy.\n\nIf the trial fails, nothing changes and the bot reports the reason. If the new mode does not come up after the switch, the bot restores the previous one by itself. Switching takes from a few seconds to a minute; connections going through WARP are briefly interrupted at that moment."),
                    $t('MASQUE: транспорт, ключ и неполадки', 'MASQUE: transport, key and troubleshooting') => $t(
                        "<b>Транспорт MASQUE.</b> В режиме MASQUE появляется кнопка <b>«транспорт MASQUE»</b>:\n• <b>HTTP/3</b> — UDP, порт 443. Вариант по умолчанию, быстрее.\n• <b>HTTP/2</b> — TCP, порт 443. Для сетей, где UDP на 443 режут; медленнее.\nПеред сменой транспорта бот так же делает пробное подключение и не меняет его, если проба не прошла.\n\n<b>Ключ WARP+.</b> «set key» действует в обоих режимах. В режиме MASQUE бот перерегистрирует с новым ключом и устройство MASQUE, и аккаунт WireGuard; при любой ошибке возвращает прежние. Если ключ сменили в режиме WireGuard, устройство MASQUE получит его при следующем переключении на MASQUE. Один ключ WARP+ можно привязать не более чем к пяти устройствам: сервер занимает до двух (WireGuard и MASQUE), остальные уходят на личные профили клиентов.\n\n<b>Меню в режиме MASQUE.</b> Строка «устройство MASQUE» показывает начало идентификатора устройства, адрес узла Cloudflare и тариф аккаунта (free — бесплатный). Состояние (trace) бот берёт через сам прокси. Ключи устройства MASQUE в меню не выводятся.\n\n<b>Защита от утечки</b> та же, что и в WireGuard: процессу прокси разрешён выход только к узлу Cloudflare. Если туннель пропал, соединения через WARP отвергаются, а не уходят с адреса сервера.\n\n<b>Если не получается.</b>\n• «Контейнер не поддерживает MASQUE» или «нужно ядро 26.10.10» — обновите бота, чтобы контейнеры пересоздались с новыми образами.\n• «Устройство не зарегистрировано» — Cloudflare отклонил регистрацию: проверьте ключ WARP+ или повторите позже (регистрации с одного адреса ограничены).\n• «Пробное подключение не прошло» — сеть сервера не пропускает UDP 443 до Cloudflare. Останьтесь на WireGuard; если не работает и он, переключитесь на MASQUE и попробуйте транспорт HTTP/2.\n• Причины отказов бот пишет в журнал warp.\n\nПоддержка WARP в MASQUE появилась в ядре Xray 26.10.10 и пока новая; регистрация зависит от Cloudflare и может перестать работать после изменений на их стороне. Уже зарегистрированное устройство от этого не страдает.",
                        "<b>MASQUE transport.</b> In MASQUE mode the <b>MASQUE transport</b> button appears:\n• <b>HTTP/3</b>: UDP, port 443. The default, faster.\n• <b>HTTP/2</b>: TCP, port 443. For networks that cut UDP on 443; slower.\nBefore changing the transport the bot also makes a trial connection and keeps the old one if the trial fails.\n\n<b>WARP+ key.</b> set key works in both modes. In MASQUE mode the bot re-registers both the MASQUE device and the WireGuard account with the new key; on any error it restores the previous ones. If the key was changed in WireGuard mode, the MASQUE device gets it at the next switch to MASQUE. One WARP+ key can be bound to at most five devices: the server takes up to two (WireGuard and MASQUE), the rest go to clients' personal profiles.\n\n<b>The menu in MASQUE mode.</b> The MASQUE device line shows the beginning of the device ID, the Cloudflare endpoint address and the account plan (free means the free tier). The bot takes the status (trace) through the proxy itself. MASQUE device keys are not shown in the menu.\n\n<b>Leak protection</b> is the same as with WireGuard: the proxy process may only reach the Cloudflare endpoint. If the tunnel is gone, connections through WARP are rejected rather than leaving from the server's address.\n\n<b>If it does not work.</b>\n• The container does not support MASQUE, or core 26.10.10 is needed: update the bot so the containers are recreated with the new images.\n• The device is not registered: Cloudflare rejected the registration; check the WARP+ key or retry later (registrations from one address are limited).\n• The trial connection failed: the server's network does not pass UDP 443 to Cloudflare. Stay on WireGuard; if that does not work either, switch to MASQUE and try the HTTP/2 transport.\n• The bot writes failure reasons to the warp log.\n\nWARP over MASQUE appeared in Xray core 26.10.10 and is still new; registration depends on Cloudflare and may stop working after changes on their side. An already registered device is not affected."),
                ]];
            case 'adguard':
                // Справка доступна из главного меню AdGuard, его настроек и
                // статистики; «назад» возвращает туда, откуда она открыта.
                $back = match ($context) {
                    'settings'              => '/adgSettings',
                    'rate', 'qlog', 'stats' => '/adgSettings ' . $context,
                    'statistics'            => '/adgStats',
                    default                 => '/menu adguard',
                };
                return ['AdGuard', $back, [
                $t('Что делает AdGuard в сборке', 'What AdGuard does in the build') => $t(
                    "AdGuard Home — DNS-сервер всей установки. Через него идут DNS-запросы пользователей VPN: он отвечает сам, убирает рекламу и трекеры по спискам фильтров и пересылает остальное на вышестоящие серверы (апстримы).\n\n<b>Кто им пользуется.</b> Клиенты WireGuard, AmneziaWG, OpenVPN, OpenConnect и IPsec получают его как DNS внутри туннеля (внутренний адрес <code>10.10.0.5</code>). Пользователям Xray бот кладёт в профиль личный адрес DoH. Снаружи, без VPN, к нему можно подключиться по DoH и DoT — адреса в меню AdGuard.\n\n<b>Главный экран</b> показывает адрес панели, логин и пароль (под спойлером), адреса DoH и DoT, состояние (<b>status</b> — AdGuard ответил на пробный запрос), безопасный поиск, защиту, число запросов и заблокированных, лимит запросов, версию AdGuardHome и список разрешённых клиентов.\n\nЧто где настраивать: частые настройки — в боте (⚙️ настройки, апстримы, список разрешённых); списки фильтров, свои правила блокировки, блокировку сервисов и личные настройки клиентов — в веб-панели.",
                    "AdGuard Home is the DNS server of the whole installation. DNS queries of VPN users go through it: it answers itself, removes ads and trackers by filter lists and forwards the rest to upstream servers (upstreams).\n\n<b>Who uses it.</b> WireGuard, AmneziaWG, OpenVPN, OpenConnect and IPsec clients get it as DNS inside the tunnel (internal address <code>10.10.0.5</code>). For Xray users the bot puts a personal DoH address into the profile. From outside, without the VPN, it can be reached over DoH and DoT; the addresses are in the AdGuard menu.\n\n<b>The main screen</b> shows the panel address, login and password (under a spoiler), DoH and DoT addresses, the state (<b>status</b>: AdGuard answered a test query), safe search, protection, the number of queries and blocked ones, the rate limit, the AdGuardHome version and the list of allowed clients.\n\nWhat to configure where: frequent settings are in the bot (⚙️ settings, upstreams, allowed list); filter lists, your own blocking rules, service blocking and per-client settings are in the web panel."),
                $t('Веб-панель и пароль', 'Web panel and password') => $t(
                    "<b>web panel</b> открывает панель AdGuard прямо в Telegram. Логин <code>admin</code>, пароль показан в меню под спойлером.\n\n<b>Доступ к панели.</b> Адрес панели открывается только с пропуском: мини-приложение Telegram выдаёт его администратору на 12 часов (подпись Telegram проверяется). Пропуск защищён подписью с ключом бота; без него адрес ведёт на заглушку. Подписчики VPN панели не видят — значит, не могут и подобрать пароль, и не закроют вход: после 5 неверных паролей AdGuard блокирует вход на 15 минут для всех.\n\n<b>Сторонний браузер.</b> Включите его, чтобы открыть панель в обычном браузере: в меню появится кнопка «🔗 Ссылка для браузера». Ссылка действует 15 минут и только один раз, браузер получает пропуск на 7 дней. Не пересылайте ссылку. Выключение режима запрещает новые ссылки; уже выданные пропуска истекают сами, отозвать все сразу можно сменой ключа бота.\n\n<b>Смена пароля.</b> «изменить пароль» — от 8 до 72 символов (в байтах), без переводов строк. AdGuard на время смены перезапускается. Меняйте пароль кнопкой в боте, а не в самой панели: бот входит в API AdGuard с паролем, который знает, и после смены в панели настройки и статистика бота отвечают «пароль в боте не совпадает». Исправляется тем же «изменить пароль».",
                    "<b>web interface</b> opens the AdGuard panel right inside Telegram. Login <code>admin</code>; the password is shown in the menu under a spoiler.\n\n<b>Panel access.</b> The panel address opens only with a pass: the Telegram mini app gives it to an admin for 12 hours (the Telegram signature is checked). The pass is signed with the bot key and cannot be forged; without it the address leads to a placeholder. VPN subscribers do not see the panel, so they cannot guess the password or lock the login: after 5 wrong passwords AdGuard blocks the login for 15 minutes for everyone.\n\n<b>Third-party browser.</b> Turn it on to open the panel in an ordinary browser: the menu gets a “🔗 Browser link” button. The link works for 15 minutes and only once; the browser gets a pass for 7 days. Do not forward the link. Turning the mode off forbids new links; passes already issued expire by themselves, and changing the bot key revokes them all at once.\n\n<b>Changing the password.</b> change password: 8 to 72 characters (in bytes), without line breaks. AdGuard restarts during the change. Change the password with the bot button, not in the panel itself: the bot signs in to the AdGuard API with the password it knows, and after a change in the panel the bot's settings and statistics answer that the password in the bot does not match. The same change password fixes it."),
                $t('DoH, DoT и ClientID', 'DoH, DoT and ClientID') => $t(
                    "Адреса DoH и DoT появляются в меню, когда у сервера есть домен и сертификат. При нескольких доменах (алиасах) адреса даны для каждого: заблокируют один — работает другой.\n\n<b>DoH</b> (DNS-over-HTTPS) — адрес <code>https://домен/dns-query…</code>. Подходит браузерам, Windows 11, iOS/macOS-профилям и большинству приложений.\n<b>DoT</b> (DNS-over-TLS) — <code>tls://домен</code>, порт 853. Это «Частный DNS» в Android: туда вводится имя без <code>tls://</code>. Порт 853 должен быть открыт в настройках портов бота.\n\n<b>ClientID</b> — общий ключ для устройств, которым бот не выдаёт личного профиля (телефон, роутер, браузер). Он дописывается в конец адреса DoH и в начало имени DoT: <code>tls://ключ.домен</code>. Допустимы строчные латинские буквы, цифры и дефис, до 63 символов; «-» убирает ключ. По ключу AdGuard узнаёт эти устройства в журнале и пускает их при включённом списке разрешённых.\n\nПосле задания ключа для DoT нужно ещё: DNS-запись <code>ключ.домен</code> на адрес сервера и «обновить SSL» в настройках домена — иначе имя не попадёт в сертификат и устройство не подключится.\n\nЛичный адрес DoH пользователя Xray бот кладёт в его профиль сам; в нём вместо ключа — идентификатор пользователя <code>doh-…</code>.",
                    "DoH and DoT addresses appear in the menu when the server has a domain and a certificate. With several domains (aliases) addresses are given for each: if one is blocked, another works.\n\n<b>DoH</b> (DNS-over-HTTPS): the address <code>https://domain/dns-query…</code>. Suits browsers, Windows 11, iOS/macOS profiles and most apps.\n<b>DoT</b> (DNS-over-TLS): <code>tls://domain</code>, port 853. This is Private DNS on Android: enter the name without <code>tls://</code> there. Port 853 must be open in the bot's port settings.\n\n<b>ClientID</b> is a shared key for devices the bot does not issue a personal profile to (a phone, router, browser). It is appended to the end of the DoH address and to the start of the DoT name: <code>tls://key.domain</code>. Lowercase Latin letters, digits and hyphens are allowed, up to 63 characters; \"-\" removes the key. By the key AdGuard recognises these devices in the log and lets them in when the allowed list is on.\n\nAfter setting the key, DoT also needs a DNS record <code>key.domain</code> pointing to the server address and renew SSL in the domain settings; otherwise the name is not in the certificate and the device will not connect.\n\nThe bot puts an Xray user's personal DoH address into their profile itself; it carries the user ID <code>doh-…</code> instead of the key."),
                $t('Список разрешённых и пользователи', 'Allowed list and users') => $t(
                    "<b>Пустой список</b> — AdGuard отвечает любому, кто к нему обратился. Если порт DoT опубликован, резолвером может пользоваться кто угодно в Интернете; меню тогда показывает предупреждение.\n\n<b>«заполнить белый список клиентов»</b> собирает список заново: внутренняя сеть контейнеров, подсети WireGuard и OpenConnect, ClientID и идентификаторы <code>doh-…</code> всех пользователей Xray. Всё остальное AdGuard отклоняет. Пока список ведётся, бот сам добавляет в него новых пользователей Xray и убирает удалённых.\n<b>«очистить белый список клиентов»</b> снимает ограничение. Обе кнопки на несколько секунд перезапускают AdGuard.\n\n<b>Как читать список в меню.</b> Подсети и ClientID показаны как есть, у идентификаторов пользователей рядом стоит имя. Записи без <code>doh-</code> из 16 знаков — идентификаторы старого вида: бот сохраняет их на переходный срок, пока пользователи не обновят профили. Если пользователей много, список продолжается следующими сообщениями.\n\n<b>Клиенты в панели.</b> Каждый пользователь Xray заведён в AdGuard клиентом со своим именем: журнал и статистика показывают имя, а в панели (Настройки → Настройки клиентов) ему можно задать свои фильтры, блокировку сервисов и апстримы. Эти настройки и клиенты, заведённые вручную, бот сохраняет при добавлении, удалении и переименовании пользователей.",
                    "<b>An empty list</b>: AdGuard answers anyone who asks. If the DoT port is published, anyone on the Internet can use the resolver; the menu then shows a warning.\n\n<b>fill allowed clients</b> rebuilds the list: the container internal network, WireGuard and OpenConnect subnets, the ClientID and the <code>doh-…</code> IDs of all Xray users. AdGuard rejects everything else. While the list is maintained, the bot adds new Xray users to it and removes deleted ones by itself.\n<b>delete allowed clients</b> removes the restriction. Both buttons restart AdGuard for a few seconds.\n\n<b>How to read the list in the menu.</b> Subnets and the ClientID are shown as they are; user IDs have the name next to them. 16-character entries without <code>doh-</code> are old-style IDs: the bot keeps them for a transition period until users refresh their profiles. With many users the list continues in the following messages.\n\n<b>Clients in the panel.</b> Every Xray user is set up in AdGuard as a client with their name: the log and statistics show the name, and in the panel (Settings → Client settings) you can give them their own filters, service blocking and upstreams. The bot keeps these settings, and clients added by hand, when users are added, deleted and renamed."),
                $t('Настройки: защита, поиск, лимит, режим', 'Settings: protection, search, limit, mode') => $t(
                    "Кнопка «⚙️ настройки». Всё меняется через API AdGuard сразу, без перезапуска и без разрыва DNS.\n\n<b>Защита</b> — фильтрация по спискам и правилам. Выключенная защита не останавливает DNS: AdGuard продолжает отвечать, но ничего не блокирует. <b>⏸ 10 min / 60 min</b> — пауза: защита сама включится через это время. Выключенную защиту главный экран отмечает ⚠️.\n\n<b>Безопасный поиск</b> — принудительно безопасная выдача в Google, Bing, Яндексе, YouTube и других поисковиках. Действует на всех клиентов, у которых в панели не заданы свои настройки.\n\n<b>Лимит запросов</b> — сколько ответов в секунду AdGuard даёт одной подсети /24 (выкл, 20 … 1100). Все клиенты WireGuard — одна подсеть, так же и те, кто приходит через контейнеры: заводские 20/с делятся на всех, и при большом числе пользователей часть запросов теряется (сайты открываются через раз). Для десятков пользователей ставьте 300–500, для сотен — 900–1100 или «выкл».\n\n<b>Режим апстримов</b> (важен, когда их несколько):\n• <b>по очереди</b> — каждый запрос одному серверу, чаще тому, что отвечает быстрее. Режим по умолчанию;\n• <b>параллельно</b> — запрос сразу всем, берётся первый ответ. Быстрее, но нагрузка на апстримы кратно выше;\n• <b>самый быстрый</b> — AdGuard опрашивает все серверы и выбирает из ответов адрес, до которого быстрее соединение. Ответ приходит медленнее.",
                    "The ⚙️ settings button. Everything changes through the AdGuard API at once, without a restart and without a DNS outage.\n\n<b>Protection</b>: filtering by lists and rules. Disabled protection does not stop DNS: AdGuard keeps answering but blocks nothing. <b>⏸ 10 min / 60 min</b> is a pause: protection turns back on by itself after that time. The main screen marks disabled protection with ⚠️.\n\n<b>Safe search</b>: enforced safe results in Google, Bing, Yandex, YouTube and other search engines. Applies to all clients without their own settings in the panel.\n\n<b>Rate limit</b>: how many answers per second AdGuard gives one /24 subnet (off, 20 … 1100). All WireGuard clients are one subnet, and so are those coming through containers: the factory 20/s is shared by everyone, and with many users part of the queries is lost (sites open every other time). For dozens of users set 300–500, for hundreds 900–1100 or off.\n\n<b>Upstream mode</b> (matters when there are several):\n• <b>in turn</b>: each query to one server, more often the one that answers faster. The default;\n• <b>parallel</b>: a query to all at once, the first answer is taken. Faster, but the load on upstreams is several times higher;\n• <b>fastest</b>: AdGuard queries all servers and picks from the answers the address with the fastest connection. The answer arrives more slowly."),
                $t('Журнал запросов и статистика', 'Query log and statistics') => $t(
                    "<b>Журнал запросов</b> — срок хранения каждого DNS-запроса каждого пользователя (выкл, 1, 7, 30, 90 дней). Журнал нужен, чтобы разбираться, что заблокировано и кем, но это и полный список посещённых сайтов. Короче срок — меньше хранимых данных и места на диске. Смотреть журнал — в панели, раздел «Журнал».\n<b>Скрывать IP клиентов</b> — в журнале вместо полного адреса хранится усечённый.\n<b>Статистика</b> — срок хранения счётчиков (выкл, 1, 7, 30, 90 дней). Выключенная статистика перестаёт собираться, и экран «📊 статистика» не пополняется.\n\n<b>Экран «📊 статистика»</b>: период, число запросов, сколько и какая доля заблокирована, среднее время ответа, пять самых блокируемых и самых запрашиваемых доменов и пять самых активных клиентов — с именами пользователей вместо идентификаторов. «🔄 обновить» перечитывает данные.\n\nДоля заблокированного 10–30 % — обычное дело при включённых фильтрах. Высокое среднее время ответа обычно значит медленный апстрим — смените его или режим.",
                    "<b>Query log</b>: how long each DNS query of each user is kept (off, 1, 7, 30, 90 days). The log helps to see what was blocked and for whom, but it is also a full list of visited sites. A shorter period means less stored data and disk space. View the log in the panel, Query Log section.\n<b>Hide client IPs</b>: the log stores a truncated address instead of the full one.\n<b>Statistics</b>: how long counters are kept (off, 1, 7, 30, 90 days). With statistics off nothing is collected, and the 📊 statistics screen is not updated.\n\n<b>The 📊 statistics screen</b>: the period, the number of queries, how many and what share was blocked, the average answer time, the top five blocked and requested domains and the five most active clients, with user names instead of IDs. 🔄 refresh rereads the data.\n\nA blocked share of 10–30% is normal with filters on. A high average answer time usually means a slow upstream: change it or the mode."),
                $t('Апстримы', 'Upstreams') => $t(
                    "Апстримы — серверы, куда AdGuard пересылает запросы, на которые не отвечает сам. По умолчанию <code>tls://1.1.1.1</code> и <code>tls://8.8.8.8</code>: запросы с сервера уходят зашифрованными, хостер их не видит.\n\n<b>«добавить DNS»</b> принимает запись в том виде, что понимает AdGuard:\n• <code>tls://dns.google</code> — DNS-over-TLS;\n• <code>https://dns.cloudflare.com/dns-query</code> — DNS-over-HTTPS (<code>h3://</code> — только HTTP/3);\n• <code>quic://dns.adguard-dns.com</code> — DNS-over-QUIC;\n• <code>sdns://…</code> — DNS-штамп;\n• <code>9.9.9.9</code> или <code>tcp://9.9.9.9</code> — обычный DNS (открытым текстом, не рекомендуется);\n• <code>[/example.lan/]10.0.0.1</code> — апстрим только для указанных доменов; <code>[/example.lan/]#</code> — для этих доменов брать общие апстримы.\n\nПеред добавлением AdGuard сам проверяет сервер: неотвечающий и уже имеющийся не добавляются, причина приходит сообщением. Добавление и удаление (кнопка рядом с апстримом) перезапускают AdGuard на несколько секунд.\n\nДержите два-три апстрима: при одном его отказ оставляет всех без DNS. Как AdGuard выбирает между ними — режим апстримов в ⚙️ настройках.",
                    "Upstreams are servers to which AdGuard forwards queries it does not answer itself. By default <code>tls://1.1.1.1</code> and <code>tls://8.8.8.8</code>: queries leave the server encrypted, and the hosting provider cannot see them.\n\n<b>add upstream</b> accepts an entry in a form AdGuard understands:\n• <code>tls://dns.google</code>: DNS-over-TLS;\n• <code>https://dns.cloudflare.com/dns-query</code>: DNS-over-HTTPS (<code>h3://</code> for HTTP/3 only);\n• <code>quic://dns.adguard-dns.com</code>: DNS-over-QUIC;\n• <code>sdns://…</code>: a DNS stamp;\n• <code>9.9.9.9</code> or <code>tcp://9.9.9.9</code>: plain DNS (in the clear, not recommended);\n• <code>[/example.lan/]10.0.0.1</code>: an upstream only for the listed domains; <code>[/example.lan/]#</code>: use the general upstreams for these domains.\n\nBefore adding, AdGuard checks the server itself: one that does not answer or already exists is not added, and the reason arrives in a message. Adding and deleting (the button next to an upstream) restart AdGuard for a few seconds.\n\nKeep two or three upstreams: with only one, its failure leaves everyone without DNS. How AdGuard chooses between them is the upstream mode in ⚙️ settings."),
                $t('Проверка DNS', 'DNS check') => $t(
                    "«проверить DNS» запрашивает домен у указанного сервера утилитой dnslookup и присылает ответ. Формат: <code>домен сервер [IP сервера]</code>, примеры приходят вместе с запросом.\n\n• <code>example.org ad</code> — проверить свой AdGuard изнутри сервера;\n• <code>example.org tls://dns.google</code> — проверить апстрим перед добавлением;\n• <code>example.org https://домен/dns-query…</code> — проверить свой адрес DoH так, как к нему ходят клиенты.\n\nЕсли status на главном экране «выкл», а <code>example.org ad</code> не отвечает — AdGuard не запущен или не принимает конфиг (см. «Версия, сброс и неполадки»). Если отвечает, но клиенты без DNS — смотрите список разрешённых и лимит запросов.",
                    "check DNS asks the given server for a domain with the dnslookup tool and sends back the answer. Format: <code>domain server [server IP]</code>; examples come with the prompt.\n\n• <code>example.org ad</code>: check your AdGuard from inside the server;\n• <code>example.org tls://dns.google</code>: check an upstream before adding it;\n• <code>example.org https://domain/dns-query…</code>: check your DoH address the way clients use it.\n\nIf status on the main screen is off and <code>example.org ad</code> does not answer, AdGuard is not running or does not accept its config (see Version, reset and troubleshooting). If it answers but clients have no DNS, check the allowed list and the rate limit."),
                $t('Версия, сброс и неполадки', 'Version, reset and troubleshooting') => $t(
                    "<b>Версия.</b> Кнопка «AdGuardHome: …» записывает версию в <code>.env</code>; на главном экране видна работающая версия и пометка, если они расходятся. Образы приходят готовыми из ghcr.io, поэтому сама запись ничего не меняет. Применить: <code>docker compose build ad</code> и <code>make r</code> на сервере, либо закоммитить <code>.env</code> в репозиторий — сборка пересоберёт образ, и обновление подтянет его. Теги — на hub.docker.com/r/adguard/adguardhome/tags. <b>Понижать версию нельзя</b>: AdGuard переводит конфиг на новый формат без обратной совместимости, старая версия его не прочитает.\n\n<b>Сброс настроек</b> (после подтверждения) возвращает заводской конфиг: стираются фильтры, свои правила, клиенты, апстримы и список разрешённых. Пароль из бота сохраняется. После сброса заново заполните список разрешённых, если порт DoT открыт.\n\n<b>Неполадки.</b>\n• «AdGuard не отвечает» в настройках и статистике — контейнер не запущен или перезапускается; подождите и откройте снова.\n• «пароль в боте не совпадает» — пароль сменили в панели; задайте его кнопкой «изменить пароль».\n• «AdGuardHome.yaml не читается» — конфиг повреждён; бот его не трогает. Исправьте файл или сделайте сброс.\n• Сайты открываются через раз у многих сразу — поднимите лимит запросов.\n• Устройство с DoT не подключается — проверьте ClientID, DNS-запись, сертификат и список разрешённых.",
                    "<b>Version.</b> The AdGuardHome: … button writes the version to <code>.env</code>; the main screen shows the running version and a mark if they differ. Images come ready-made from ghcr.io, so the record alone changes nothing. To apply: <code>docker compose build ad</code> and <code>make r</code> on the server, or commit <code>.env</code> to the repository: the build rebuilds the image and the update pulls it. Tags are at hub.docker.com/r/adguard/adguardhome/tags. <b>Do not downgrade</b>: AdGuard converts its config to a new format without backward compatibility, and an older version cannot read it.\n\n<b>reset settings</b> (after confirmation) restores the factory config: filters, your rules, clients, upstreams and the allowed list are erased. The password from the bot is kept. After a reset fill in the allowed list again if the DoT port is open.\n\n<b>Troubleshooting.</b>\n• AdGuard does not respond in settings and statistics: the container is not running or is restarting; wait and open it again.\n• The password in the bot does not match: the password was changed in the panel; set it with change password.\n• AdGuardHome.yaml cannot be read: the config is damaged; the bot does not touch it. Fix the file or reset.\n• Sites open every other time for many users at once: raise the rate limit.\n• A DoT device does not connect: check the ClientID, the DNS record, the certificate and the allowed list."),
                ]];
            case 'xray':
                return ['Xray', '/xray', [
                    $t('Транспорт и домены', 'Transport and domains') => $t(
                        "<b>RLTY</b> (REALITY) — подключение прямо к серверу на порт 443 без своего сертификата: снаружи оно выглядит как обращение к чужому сайту («фейковый домен»). Вариант по умолчанию; устойчивость зависит от сети и выбранной маски.\n\n<b>WS</b>, <b>XHTTP</b> и <b>Trojan-gRPC</b> идут через nginx бота по вашему домену с настоящим сертификатом: нужен домен, направленный на сервер, и SSL в настройках. Их можно пустить через CDN. gRPC и XHTTP требуют HTTP/2.\n\n<b>домен CDN</b> — имя, которое бот подставляет в ссылки и подписки вместо основного домена (например, домен за Cloudflare). Пустой ответ убирает его.\n\nСмена транспорта перезапускает Xray: соединения кратко прервутся, клиентам нужно обновить подписку — старые ссылки другого транспорта не подключатся.",
                        "<b>RLTY</b> (REALITY) connects straight to the server on port 443 without a certificate of your own: from outside it looks like a visit to someone else's site (the fake domain). The default option; resistance depends on the network and the chosen cover site.\n\n<b>WS</b>, <b>XHTTP</b> and <b>Trojan-gRPC</b> go through the bot's nginx on your domain with a real certificate: you need a domain pointing to the server and SSL in the settings. They can be routed through a CDN. gRPC and XHTTP need HTTP/2.\n\n<b>CDN domain</b> is the name the bot puts into links and subscriptions instead of the main domain (for example, a domain behind Cloudflare). An empty answer removes it.\n\nChanging the transport restarts Xray: connections briefly drop and clients must refresh the subscription; old links of another transport will not connect."),
                    $t('Маска REALITY и ключи', 'REALITY mask and keys') => $t(
                        "<b>фейковый домен</b> — сайт, под который маскируется сервер: посторонний, обратившийся к порту 443, получит его настоящий ответ. Нужен крупный сайт с TLS 1.3 и HTTP/2; первая строка меню показывает домен и его ALPN.\n\n<b>маска своим сайтом</b> — маской становится nginx бота на вашем домене (нужен домен и сертификат).\n\n<b>🔍 проверить</b> — бот подключается к маске и проверяет, что она годится текущему ядру. Xray 26.10.17+ и форк 26.10.28+ отвергают всех клиентов, если маска отвечает без ALPN. Поэтому бот не поставит такую маску и не переключит на такое ядро, пока маска без ALPN, а маску без TLS 1.3 не поставит ни на каком ядре; маску без ALPN принимают только ядра старше этих. Если маска испортится позже, бот пришлёт уведомление.\n\n<b>🔑 pbk+sid</b> меняет ключ и shortId REALITY: перестают работать ссылки всех пользователей, UUID остаются. <b>🔄 ротация всего</b> меняет ещё и UUID каждого пользователя. После любой ротации обновите ссылки у клиентов. Для узлов выхода с подпиской «Профиля для узла» новая ссылка скачивается автоматически; ручную проверку можно запустить в настройках узла.",
                        "<b>fake domain</b> is the site the server imitates: a stranger knocking on port 443 gets its real answer. Use a large site with TLS 1.3 and HTTP/2; the first menu line shows the domain and its ALPN.\n\n<b>steal from yourself</b> makes the bot's own nginx on your domain the mask (a domain and certificate are needed).\n\n<b>🔍 check</b> makes the bot connect to the mask and check that it suits the current core. Xray 26.10.17+ and the fork 26.10.28+ reject every client if the mask answers without ALPN. So the bot will not set such a mask or switch to such a core while the mask lacks ALPN, and will not set a mask without TLS 1.3 on any core; only cores older than these accept a mask without ALPN. If the mask breaks later, the bot sends a notification.\n\n<b>🔑 pbk+sid</b> replaces the REALITY key and shortId: every user's link stops working, UUIDs stay. <b>🔄 rotate all</b> also replaces each user's UUID. After any rotation refresh client links. Exit nodes using a Node profile subscription fetch the new link automatically; a manual refresh is available in node settings."),
                    $t('Пользователи', 'Users') => $t(
                        "<b>добавить</b> — имя пользователя (латиница, цифры, точка, дефис); несколько через запятую. Можно задать свой UUID: <code>имя:uuid</code>.\n\nСписок ниже — пользователи с расходом трафика; нажатие открывает карточку (у неё своя справка). <b>🟢 N</b> и <b>🔴 N</b> переключают список между включёнными и выключенными. <b>👥 онлайн</b> — кто подключён сейчас, с адресами и страной.\n\nУчётки <code>node-…</code> — служебные «Профили для узла» (Узлы выхода): их трафик никогда не уходит на узлы этого сервера.",
                        "<b>add</b>: a user name (Latin letters, digits, dot, hyphen); several separated by commas. You can set your own UUID: <code>name:uuid</code>.\n\nThe list below shows users with their traffic; tapping opens the card (it has its own help). <b>🟢 N</b> and <b>🔴 N</b> switch the list between enabled and disabled users. <b>👥 online</b> shows who is connected now, with addresses and country.\n\n<code>node-…</code> accounts are service Node profiles (Exit nodes): their traffic never goes to this server's nodes."),
                    $t('Лимиты и защита', 'Limits and protection') => $t(
                        "<b>лимит IP</b> — сколько разных адресов один пользователь может использовать за окно времени, формат <code>секунды:количество</code>, например <code>300:2</code>; <code>0</code> выключает. При превышении бот присылает уведомление с кнопкой отключения — сам никого не блокирует.\n\n<b>HWID лимит</b> и <b>количество HWID устройств</b> — ограничение числа устройств по их идентификатору (HWID). Срабатывает только при добавлении и обновлении подписки в приложении, которое передаёт HWID.\n\n<b>🚫 торренты</b> — Xray блокирует BitTorrent у всех пользователей.\n\n<b>🔒 строгий токен подписки</b> — подписки открываются только по личному токену, старые ссылки по UUID перестают работать. <b>🔄 сменить ссылки подписок</b> выдаёт всем новые токены (сам VPN-доступ не меняется).\n\n<b>сбросить статистику</b> обнуляет счётчики всех пользователей; <b>ежемесячный сброс</b> делает это автоматически в начале месяца.",
                        "<b>IP limit</b>: how many different addresses one user may use within a time window, format <code>seconds:count</code>, e.g. <code>300:2</code>; <code>0</code> turns it off. When exceeded, the bot sends a notification with a disable button; it blocks nobody by itself.\n\n<b>HWID limit</b> and <b>set HWID devices count</b> limit the number of devices by their identifier (HWID). They apply only when an app that sends HWID adds or refreshes the subscription.\n\n<b>🚫 torrents</b>: Xray blocks BitTorrent for all users.\n\n<b>🔒 strict sub token</b>: subscriptions open only by the personal token, old UUID links stop working. <b>🔄 rotate sub links</b> gives everyone new tokens (VPN access itself does not change).\n\n<b>reset stats</b> zeroes all users' counters; <b>monthly reset</b> does it automatically at the start of each month."),
                    $t('Подписки, шаблоны и маршруты', 'Subscriptions, templates and routes') => $t(
                        "<b>шаблоны v2ray / sing-box / mihomo</b> — заготовки клиентских конфигов, из которых бот собирает подписки. <code>origin</code> — штатный шаблон; можно добавить свой (JSON/YAML с метками вроде <code>~outbound~</code>, <code>~domain~</code>, <code>~fingerprint~</code>), сделать его шаблоном по умолчанию или выбрать отдельному пользователю в карточке.\n\nВ комплект входят <code>15_direct</code>, <code>15_dns_google</code>, <code>15_relay</code> для sing-box и <code>mihomo_cust_warp</code> для Mihomo. Бот добавляет их один раз, сохраняя ваши правки и выбор. Метки <code>~relay_hosts~</code>, <code>~relay_ips~</code>, <code>~relay_domains~</code> получают адреса из раздела Relay; IPv4 доменов обновляются в фоне раз в 10 минут. Без Relay пустые правила удаляются.\n\n<b>имя основного аутбаунда</b> — тег узла VPN в шаблонах (по умолчанию <code>proxy</code>); менять, только если ваш шаблон ссылается на другое имя.\n\n<b>routes</b> — какие сайты, адреса и приложения идут через VPN, блокируются или уходят в WARP (своя справка). <b>списки tun</b> — приложения Android и процессы для режима TUN клиента: включить только их (include) или все, кроме них (exclude).\n\n<b>relay</b> — подписки через промежуточные серверы: в них меняется только адрес и порт, а пересылку на этот сервер relay делает сам.\n\nОстальные пункты — отпечаток, маскировка DPI, ядро, VLESS Encryption, XDRIVE, SMUX, узлы выхода — открывают свои меню со своей справкой.",
                        "<b>v2ray / sing-box / mihomo templates</b> are client config blanks the bot builds subscriptions from. <code>origin</code> is the standard template; you can add your own (JSON/YAML with markers such as <code>~outbound~</code>, <code>~domain~</code>, <code>~fingerprint~</code>), make it the default or pick it for one user in their card.\n\nBundled templates: <code>15_direct</code>, <code>15_dns_google</code>, <code>15_relay</code> for sing-box and <code>mihomo_cust_warp</code> for Mihomo. They are added once, preserving your edits and selection. <code>~relay_hosts~</code>, <code>~relay_ips~</code>, <code>~relay_domains~</code> use addresses from Relay; domain IPv4 addresses refresh in the background every 10 minutes. Empty Relay rules are removed.\n\n<b>main outbound name</b> is the VPN node tag in templates (default <code>proxy</code>); change it only if your template refers to another name.\n\n<b>routes</b>: which sites, addresses and apps go through the VPN, are blocked or go to WARP (its own help). <b>tun lists</b>: Android apps and processes for the client's TUN mode: only these (include) or all except these (exclude).\n\n<b>relay</b>: subscriptions through intermediate servers; only the address and port change, and the relay forwards to this server by itself.\n\nThe other items (fingerprint, DPI masking, core, VLESS Encryption, XDRIVE, SMUX, exit nodes) open their own menus with their own help."),
                ]];
            case 'xray_user':
                if (!preg_match('~^\d{1,6}$~D', $context)) return [];
                return ['Xray → ' . $t('пользователь', 'user'), '/userXr ' . $context, [
                    $t('Доступ, срок и трафик', 'Access, expiry and traffic') => $t(
                        "Строка <b>Доступ</b> показывает итог: доступен, выключен, срок истёк или трафик исчерпан.\n\n<b>🟢 / 🔴</b> — включить или выключить пользователя; выключенный не подключается, его ссылки и подписки сохраняются.\n<b>установить время действия</b> — дата окончания доступа; после неё пользователь выключается сам.\n<b>📊 лимит трафика</b> — объём, после которого пользователь выключается; <b>сбросить статистику</b> обнуляет его расход.\n<b>переименовать</b> меняет имя (оно же email в Xray и подпись в журналах); <b>удалить</b> отзывает доступ навсегда.",
                        "The <b>Access</b> line shows the result: available, disabled, expired or traffic used up.\n\n<b>🟢 / 🔴</b> enables or disables the user; a disabled user cannot connect, their links and subscriptions are kept.\n<b>set timer</b>: the access end date; after it the user is disabled automatically.\n<b>📊 traffic limit</b>: the volume after which the user is disabled; <b>reset stats</b> zeroes their usage.\n<b>rename</b> changes the name (it is also the email in Xray and the label in logs); <b>delete</b> revokes access for good."),
                    $t('Ссылки, подписки и QR', 'Links, subscriptions and QR') => $t(
                        "<b>Подключение</b> — ссылка <code>vless://</code> для ручного импорта. <b>Импорт в приложения</b> — кнопки, которые сразу открывают подписку в выбранном клиенте.\n\n<b>Подписки</b> (xray, sing-box, mihomo, v2rayNG) обновляются в приложении сами и несут маршруты и шаблоны бота — им стоит отдавать предпочтение. Файлы <b>⬇️</b> и <b>Mihomo JSON</b> — разовый снимок той же настройки; файлы временные, сохраните их до следующего нажатия.\n\n<b>QR</b>: короткая ссылка, QR подписки v2ray и sing-box.\n\n<b>🔁 сменить ссылку подписки</b> отзывает старые адреса подписки этого пользователя (если они утекли), VPN-доступ сохраняется. <b>🆔 новый clientID</b> меняет UUID: перестают работать все его ссылки и подписки, выдайте новые.\n\n<b>🧩 внешние ссылки</b> подмешивают в его подписку v2rayNG сторонние ссылки и подписки других серверов.",
                        "<b>Connection</b> is the <code>vless://</code> link for manual import. <b>Import into apps</b> buttons open the subscription right in the chosen client.\n\n<b>Subscriptions</b> (xray, sing-box, mihomo, v2rayNG) refresh in the app by themselves and carry the bot's routes and templates, so prefer them. The <b>⬇️</b> files and <b>Mihomo JSON</b> are a one-time snapshot of the same setup; files are temporary, save them before the next tap.\n\n<b>QR</b>: QR (short link) and QR codes of the v2ray and sing-box subscriptions.\n\n<b>🔁 rotate sub link</b> revokes this user's old subscription addresses (if they leaked); VPN access stays. <b>🆔 new clientID</b> replaces the UUID: all their links and subscriptions stop working, hand out new ones.\n\n<b>🧩 external links</b> mix third-party links and other servers' subscriptions into their v2rayNG subscription."),
                    $t('Шаблоны пользователя', 'User templates') => $t(
                        "Кнопки <b>v2ray / sing-box / mihomo: …</b> выбирают, из какого шаблона собирается подписка этого пользователя. <code>default(…)</code> — общий шаблон по умолчанию из меню Xray; можно выбрать конкретный, например свой с особыми маршрутами для одного человека. После смены пользователю достаточно обновить подписку.",
                        "The <b>v2ray / sing-box / mihomo: …</b> buttons choose which template this user's subscription is built from. <code>default(…)</code> is the shared default template from the Xray menu; you can pick a specific one, for example your own with special routes for one person. After a change the user only needs to refresh the subscription."),
                    $t('Устройства, журнал и другие протоколы', 'Devices, log and other protocols') => $t(
                        "<b>HWID лимит</b> — сколько устройств этого пользователя принимает подписка (работает в приложениях, передающих HWID, при добавлении и обновлении подписки). В меню видны устройства, которые уже отметились.\n\n<b>📜 лог подключений</b> — с каких адресов и когда пользователь подключался.\n\n<b>Протоколы в готовой подписке</b> добавляют в его общую подписку другие протоколы бота (AnyTLS, TUIC, ShadowTLS, Mieru и т. п.). <b>Отдельные подключения</b> — ссылки и файлы этих протоколов по отдельности. <b>🌍 Узлы выхода</b> — включить ему маршрут через другой сервер.",
                        "<b>HWID limit</b>: how many of this user's devices the subscription accepts (works in apps that send HWID, when the subscription is added or refreshed). The menu lists devices that have already checked in.\n\n<b>📜 connection log</b>: from which addresses and when the user connected.\n\n<b>Protocols in the ready subscription</b> add the bot's other protocols (AnyTLS, TUIC, ShadowTLS, Mieru and so on) to their shared subscription. <b>Separate connections</b> gives links and files of those protocols one by one. <b>🌍 Exit nodes</b> enables a route through another server for them."),
                ]];
            case 'ss':
                return ['Shadowsocks', '/menu ss', [
                    $t('Подключение и пароль', 'Connection and password') => $t(
                        "Shadowsocks — простой шифрованный прокси. Меню показывает адрес и порт, текущий транспорт, DNS для клиентов, метод шифрования, пароль (под спойлером) и ссылку <code>ss://</code>; <b>показать QR</b> выдаёт её картинкой.\n\n<b>изменить пароль</b> задаёт свой, <b>сгенерировать пароль</b> — случайный. Пароль общий для всех: после смены старые ссылки перестают работать у всех, раздайте новую.\n\nБез дополнительных транспортов Shadowsocks легко распознаётся DPI; там, где блокируют, включите один из транспортов ниже.",
                        "Shadowsocks is a simple encrypted proxy. The menu shows the address and port, the current transport, the DNS for clients, the cipher, the password (under a spoiler) and the <code>ss://</code> link; <b>show QR</b> gives it as an image.\n\n<b>change password</b> sets your own, <b>generate password</b> a random one. The password is shared by everyone: after a change old links stop working for all, hand out the new one.\n\nWithout an extra transport Shadowsocks is easy for DPI to recognise; where it is blocked, enable one of the transports below."),
                    $t('Транспорты: v2ray, Cloak, simple-tls', 'Transports: v2ray, Cloak, simple-tls') => $t(
                        "Включается один транспорт за раз; включение другого выключает прежний. После переключения ссылка меняется — раздайте её заново.\n\n<b>v2ray</b> (v2ray-plugin) — Shadowsocks внутри WebSocket с TLS на порту 443 вашего домена: снаружи похоже на обычный сайт. Нужен домен и сертификат.\n\n<b>cloak</b> — свой порт; посторонним Cloak отвечает как сайт-маска (<b>cloak маска</b>), клиент с ключом получает прокси. <b>cloak метод</b> — шифрование, <b>новые ключи cloak</b> отзывают все прежние ссылки, <b>пользователи cloak</b> — отдельные UID для людей.\n\n<b>simple-tls</b> — Shadowsocks внутри обычного TLS на своём порту (<b>stls порт</b>) с именем сервера <b>stls SNI</b>.\n\nКлиенту нужен соответствующий плагин: v2ray-plugin, ck-client или simple-tls.",
                        "One transport at a time; enabling another turns the previous one off. After switching the link changes: hand it out again.\n\n<b>v2ray</b> (v2ray-plugin): Shadowsocks inside WebSocket with TLS on port 443 of your domain; from outside it looks like an ordinary site. A domain and certificate are needed.\n\n<b>cloak</b>: its own port; Cloak answers strangers as the mask site (<b>cloak masq</b>), a client with the key gets the proxy. <b>cloak method</b> is the cipher, <b>regen cloak keys</b> revoke all previous links, <b>cloak users</b> are separate UIDs for people.\n\n<b>simple-tls</b>: Shadowsocks inside ordinary TLS on its own port (<b>stls port</b>) with the server name <b>stls SNI</b>.\n\nThe client needs the matching plugin: v2ray-plugin, ck-client or simple-tls."),
                    $t('ss через warp', 'ss via warp') => $t(
                        "Выход TCP-соединений Shadowsocks в Интернет идёт через WARP (сайты видят адрес Cloudflare). UDP так не умеет: QUIC и DNS по UDP по-прежнему уходят с адреса сервера. Если WARP недоступен, TCP не переключается на прямой выход, а перестаёт работать — проверьте состояние WARP в его меню.",
                        "Shadowsocks TCP connections reach the Internet through WARP (sites see a Cloudflare address). UDP cannot do this: QUIC and DNS over UDP still leave from the server address. If WARP is down, TCP does not fall back to direct but stops working; check WARP's state in its menu."),
                ]];
            case 'oc':
                return ['OpenConnect', '/menu oc', [
                    $t('Что это и подключение', 'What it is and connecting') => $t(
                        "OpenConnect (ocserv) — VPN, совместимый с Cisco AnyConnect: клиенты есть для Windows, macOS, Linux, Android и iOS (Cisco Secure Client, OpenConnect). Работает поверх HTTPS на порту 443 вашего домена через nginx бота, поэтому нужен домен и сертификат.\n\n<b>добавить клиента</b> — логин и пароль пользователя; клиенты перечислены в меню, у каждого своя карточка. <b>сменить поддомен</b> — имя, по которому подключаются клиенты (входит в адрес сервера в меню).",
                        "OpenConnect (ocserv) is a VPN compatible with Cisco AnyConnect: clients exist for Windows, macOS, Linux, Android and iOS (Cisco Secure Client, OpenConnect). It runs over HTTPS on port 443 of your domain through the bot's nginx, so a domain and certificate are needed.\n\n<b>add peer</b>: the user's login and password; clients are listed in the menu, each with its own card. <b>change subdomain</b>: the name clients connect to (part of the server address in the menu)."),
                    $t('Маскировка и настройки', 'Masking and settings') => $t(
                        "<b>секретное слово</b> включает маскировку ocserv: без этого слова в адресе (<code>https://домен/?слово</code>) сервер отвечает как обычный сайт, и сканер не видит VPN. Слово входит в адрес из меню — раздавайте адрес целиком.\n\n<b>днс</b> — DNS-серверы, которые получают клиенты (по умолчанию AdGuard бота).\n\n<b>список подсетей</b> — какие сети клиент направляет в VPN; пустой список — весь трафик. Есть калькулятор для исключений.\n\n<b>изоляция клиентов</b> — могут ли клиенты VPN обращаться друг к другу по внутренним адресам.",
                        "<b>change secret</b> turns on ocserv camouflage: without this word in the address (<code>https://domain/?word</code>) the server answers like an ordinary site, and a scanner does not see a VPN. The word is part of the address in the menu: hand out the full address.\n\n<b>dns</b>: the DNS servers clients get (the bot's AdGuard by default).\n\n<b>subnet list</b>: which networks the client sends into the VPN; an empty list means all traffic. A calculator helps with exclusions.\n\n<b>client isolation</b>: whether VPN clients can reach each other by internal addresses."),
                ]];
            case 'ipsec':
                if (!in_array($context, ['l2tp', 'ikev2'], true)) return [];
                return [$context === 'l2tp' ? 'L2TP/IPsec' : 'IKEv2', '/menu ' . $context, [
                    $t('L2TP и IKEv2', 'L2TP and IKEv2') => $t(
                        "Оба протокола встроены в Windows, macOS, iOS и Android (IKEv2 — в Android 11+; нативного L2TP в Android 12+ нет) и работают без сторонних приложений. Их обслуживает один контейнер IPsec (strongswan; для L2TP ещё xl2tpd).\n\n<b>L2TP/IPsec</b> — логин, пароль и общий ключ PSK из меню. Устаревший протокол, проще в настройке. <b>IKEv2</b> — логин и пароль с проверкой сертификата сервера; для Windows сначала установите сертификат <b>CA (Windows)</b>, для iOS и macOS бот выдаёт готовый профиль <code>.mobileconfig</code>.\n\nIPsec легко распознаётся DPI: это вариант для удобства на сетях без блокировок, а не для обхода.",
                        "Both protocols are built into Windows, macOS, iOS and Android (IKEv2 in Android 11+; Android 12+ has no native L2TP) and work without third-party apps. One IPsec container serves them (strongswan; plus xl2tpd for L2TP).\n\n<b>L2TP/IPsec</b>: login, password and the shared PSK from the menu. An old protocol, easier to set up. <b>IKEv2</b>: login and password with server certificate verification; on Windows install the <b>CA (Windows)</b> certificate first, for iOS and macOS the bot issues a ready <code>.mobileconfig</code> profile.\n\nIPsec is easy for DPI to recognise: it is for convenience on networks without blocking, not for getting around blocks."),
                    $t('Клиенты, порты и журналы', 'Clients, ports and logs') => $t(
                        "<b>добавить клиента</b> — имя пользователя (до 40 символов); у каждого клиента своя карточка с данными для подключения.\n\n<b>IKE port</b> и <b>NAT-T port</b> — внешние порты IPsec (500 и 4500). Встроенные клиенты ждут именно стандартные порты; нестандартный порт требует ручного DNAT в nft на сервере, а профиль L2TP для iOS/macOS тогда не выдаётся. Порты общие для L2TP и IKEv2.\n\n<b>журнал</b> и <b>подключения</b> — события сервера и история входов. <b>♻️ перезагрузка</b> перезапускает контейнер IPsec: все сессии L2TP и IKEv2 прервутся.",
                        "<b>add peer</b>: a user name (up to 40 characters); each client has its own card with the connection data.\n\n<b>IKE port</b> and <b>NAT-T port</b> are the external IPsec ports (500 and 4500). Built-in clients expect exactly the standard ports; a non-standard port needs a manual DNAT in nft on the server, and the L2TP profile for iOS/macOS is then not issued. The ports are shared by L2TP and IKEv2.\n\n<b>log tail</b> and <b>connections</b>: server events and login history. <b>♻️ restart</b> restarts the IPsec container: all L2TP and IKEv2 sessions drop."),
                ]];
            case 'naive':
                return ['NaiveProxy', '/menu naive', [
                    $t('Что это и настройка', 'What it is and setup') => $t(
                        "NaiveProxy — прокси внутри настоящего HTTPS: клиент использует сетевой стек Chrome, поэтому его соединение почти неотличимо от браузера. Сервер — Caddy с плагином forwardproxy на вашем поддомене, на порту 443 через nginx бота.\n\n1. <b>сменить поддомен</b> — имя, на котором работает прокси (DNS-запись должна указывать на сервер, имя должно войти в сертификат).\n2. <b>изменить логин</b> и <b>изменить пароль</b> (или <b>сгенерировать пароль</b>) — без них ссылки нет.\n3. Раздайте ссылку <code>naive+https://</code> из меню; клиенты — NekoBox, Karing, официальный naive.\n\nЛогин и пароль общие для всех пользователей: смена отзывает старые ссылки.",
                        "NaiveProxy is a proxy inside real HTTPS: the client uses Chrome's network stack, so its connection is nearly indistinguishable from a browser. The server is Caddy with the forwardproxy plugin on your subdomain, on port 443 through the bot's nginx.\n\n1. <b>change subdomain</b>: the name the proxy runs on (its DNS record must point to the server and the name must be in the certificate).\n2. <b>change login</b> and <b>change password</b> (or <b>generate password</b>): without them there is no link.\n3. Hand out the <code>naive+https://</code> link from the menu; clients are NekoBox, Karing and the official naive.\n\nThe login and password are shared by all users: changing them revokes old links."),
                    $t('Версия caddy', 'caddy version') => $t(
                        "Кнопка <b>caddy</b> записывает в <code>.env</code> только проверенную версию Caddy вместе с совместимой ревизией forwardproxy. Список доступных версий показан в запросе ввода. Образы приходят готовыми, поэтому сама запись ничего не обновляет. Для обновления измените пины и контрольные суммы в репозитории, соберите и проверьте комплект CI, затем обновите бот. Самостоятельная сборка требует отдельной рабочей копии без активного манифеста выпуска; порядок описан в readme.",
                        "The <b>caddy</b> button writes only a tested Caddy version and its compatible forwardproxy revision to <code>.env</code>. The input prompt lists the available versions. Images arrive ready-made, so writing the pin does not update anything. Update pins and source checksums in the repository, build and test the CI bundle, then update the bot. A local build requires a separate working copy without an active release manifest; see the readme."),
                ]];
            case 'fingerprint':
                return [$t('Xray → Отпечаток', 'Xray → Fingerprint'), '/fingerprintMenu', [
                    $t('Что такое отпечаток', 'What a fingerprint is') => $t(
                        "Отпечаток (uTLS fingerprint) — под какой браузер клиент маскирует своё первое TLS-сообщение ClientHello (JA3/JA4). Это настройка <b>клиента</b>: бот кладёт её в ссылки и подписки, сервер её не хранит и не сверяет. Клиент с другим отпечатком подключится так же, если сервер примет его ClientHello.\n\nОдин выбор доезжает до трёх клиентских ядер под их именами: Mihomo не знает <code>randomized</code> и получает <code>random</code> — меню показывает, во что превратился выбор.\n\n<b>chrome</b> — самый безопасный выбор: работает со всеми ядрами, транспортами и клиентами бота. Отпечатки с ⚠ при текущих ядре и транспорте не подключатся; бот выбор не подменяет, только предупреждает.\n\nВсё ниже — замер 2026-10-20 на тогдашних ядрах (Xray 26.10.17, 26.10.10, форк 26.10.13) с клиентами Xray всех этих версий, Mihomo 1.19.32 и sing-box 1.14.3.",
                        "A fingerprint (uTLS fingerprint) is the browser whose first TLS message, the ClientHello (JA3/JA4), the client imitates. It is a <b>client</b> setting: the bot puts it into links and subscriptions, the server neither stores nor checks it. A client with another fingerprint connects just the same if the server accepts its ClientHello.\n\nOne choice reaches three client cores under their own names: Mihomo does not know <code>randomized</code> and gets <code>random</code>; the menu shows what the choice became.\n\n<b>chrome</b> is the safest choice: it works with all of the bot's cores, transports and clients. Fingerprints marked ⚠ will not connect with the current core and transport; the bot does not replace your choice, it only warns.\n\nEverything below was measured on 2026-10-20 on the cores available at that time (Xray 26.10.17, 26.10.10, fork 26.10.13) with Xray clients of all these versions, Mihomo 1.19.32 and sing-box 1.14.3."),
                    $t('REALITY: какие отпечатки на каком ядре', 'REALITY: fingerprints per core') => $t(
                        "Решает ядро <b>сервера</b> (Xray → Ядро / версия).\n\n<b>Ядро требует ML-KEM</b> — оригинальный Xray 26.10.31 и 26.9.30 (все версии с 26.9.8) и форк с «Требовать ML-KEM» (Xray → 🛡 маскировка DPI). Сервер принимает только ClientHello с гибридной группой X25519MLKEM768:\n• клиенты Xray — <b>chrome, firefox, safari</b>;\n• Mihomo — только <b>chrome</b> (бот сам ставит ему support-x25519mlkem768);\n• sing-box — не подключается ни с одним отпечатком.\n\n<b>Ядро 26.7.28 и форк без «Требовать ML-KEM»</b> принимают любой отпечаток с TLS 1.3: <b>chrome, firefox, safari, ios, edge, qq</b> и random — у Xray, Mihomo и sing-box.\n\n<b>android</b> и <b>360</b> не работают с REALITY ни на одном ядре: в этих образцах нет TLS 1.3.\n\nИтак, на 26.7.28 и на форке без флага доступны все отпечатки, кроме android и 360; на форке с флагом и на ядрах 26.9.30 и 26.10.29 — только chrome, firefox и safari.",
                        "The <b>server</b> core decides (Xray → Core / version).\n\n<b>The core requires ML-KEM</b>: original Xray 26.10.31 and 26.9.30 (every version since 26.9.8) and the fork with Require ML-KEM (Xray → 🛡 DPI masking). The server accepts only a ClientHello with the hybrid group X25519MLKEM768:\n• Xray clients: <b>chrome, firefox, safari</b>;\n• Mihomo: only <b>chrome</b> (the bot sets support-x25519mlkem768 for it);\n• sing-box: does not connect with any fingerprint.\n\n<b>Core 26.7.28 and the fork without Require ML-KEM</b> accept any fingerprint with TLS 1.3: <b>chrome, firefox, safari, ios, edge, qq</b> and random, for Xray, Mihomo and sing-box.\n\n<b>android</b> and <b>360</b> never work with REALITY on any core: these samples have no TLS 1.3.\n\nSo on 26.7.28 and on the fork without the flag every fingerprint except android and 360 is available; on the fork with the flag and on cores 26.9.30 and 26.10.29 only chrome, firefox and safari."),
                    $t('Постквантовое шифрование', 'Post-quantum encryption') => $t(
                        "В боте два независимых постквантовых слоя, и путать их не нужно.\n\n<b>ML-KEM в рукопожатии REALITY</b> — группа X25519MLKEM768 в ClientHello. Именно она определяет, какие отпечатки примет сервер (предыдущая страница); на оригинальном ядре она обязательна, на форке — по флагу «Требовать ML-KEM».\n\n<b>VLESS Encryption</b> (Xray → VLESS Encryption, ML-KEM-768) — шифрование внутри VLESS, поверх TLS или REALITY. На отпечатки оно <b>не влияет</b>: замер с ним и без него дал одинаковый набор работающих отпечатков на всех ядрах и транспортах. Оно меняет другое — круг клиентов: VLESS Encryption понимают Xray и Mihomo, sing-box не поддерживает его вовсе.\n\nВывод: включённое VLESS Encryption отпечатки не сужает, но лишает подключения клиентов sing-box; «Требовать ML-KEM» на форке сужает отпечатки до chrome/firefox/safari и тоже отключает sing-box.",
                        "The bot has two independent post-quantum layers; do not mix them up.\n\n<b>ML-KEM in the REALITY handshake</b> is the X25519MLKEM768 group in the ClientHello. It is what decides which fingerprints the server accepts (previous page); the original core requires it, the fork does so with the Require ML-KEM flag.\n\n<b>VLESS Encryption</b> (Xray → VLESS Encryption, ML-KEM-768) is encryption inside VLESS, on top of TLS or REALITY. It does <b>not</b> affect fingerprints: measurements with and without it gave the same set of working fingerprints on every core and transport. It changes something else, the set of clients: Xray and Mihomo understand VLESS Encryption, sing-box does not support it at all.\n\nIn short: VLESS Encryption does not narrow fingerprints but cuts off sing-box clients; Require ML-KEM on the fork narrows fingerprints to chrome/firefox/safari and also cuts off sing-box."),
                    $t('WS, gRPC и XHTTP (обычный TLS)', 'WS, gRPC and XHTTP (ordinary TLS)') => $t(
                        "С транспортами через nginx бота отпечаток проверяет обычный TLS, а не REALITY, и ядро Xray на него не влияет.\n\n<b>WebSocket</b> — работают все отпечатки у всех клиентов.\n<b>gRPC</b> и <b>XHTTP</b> — работают все, кроме <b>android</b> и <b>360</b>: их образцы не предлагают HTTP/2, а эти транспорты идут только по нему.\n\nsing-box не поддерживает XHTTP — с ним такой транспорт в подписке sing-box не заработает при любом отпечатке.",
                        "With transports through the bot's nginx the fingerprint meets ordinary TLS, not REALITY, and the Xray core does not affect it.\n\n<b>WebSocket</b>: every fingerprint works with every client.\n<b>gRPC</b> and <b>XHTTP</b>: everything except <b>android</b> and <b>360</b>, whose samples do not offer HTTP/2, which these transports require.\n\nsing-box does not support XHTTP: with it that transport will not work in a sing-box subscription with any fingerprint."),
                    $t('random и randomized', 'random and randomized') => $t(
                        "<b>random</b> при каждом запуске клиента выбирает один из образцов браузеров. С обычным TLS и с REALITY на форке без флага он работает всегда (5 из 5 запусков). На ядре, требующем ML-KEM, подходит лишь часть образцов: клиент подключается через раз (0–4 из 5).\n\n<b>randomized</b> собирает случайный ClientHello. Он нестабилен даже с обычным TLS у Xray 26.10.x (1–5 из 5); у клиента на форке Xray он стабилен (5 из 5, включая ядро с ML-KEM). Mihomo его не знает и получает random.\n\nСлучайный отпечаток, который меняется на каждом подключении, для браузера нетипичен. Для постоянной работы выбирайте именованный отпечаток — chrome, firefox или safari.",
                        "<b>random</b> picks one of the browser samples at every client start. With ordinary TLS and with REALITY on the fork without the flag it always works (5 of 5 starts). On a core that requires ML-KEM only some samples fit: the client connects every other time (0–4 of 5).\n\n<b>randomized</b> builds a random ClientHello. It is unstable even with ordinary TLS on Xray 26.10.x (1–5 of 5); with a client on the Xray fork it is stable (5 of 5, including the ML-KEM core). Mihomo does not know it and gets random.\n\nA random fingerprint that changes with every connection is unusual for a browser. For steady use pick a named fingerprint: chrome, firefox or safari."),
                ]];
            case 'awg':
                if (!preg_match('~^[01]_-?\d{1,8}$~D', $context)) return [];
                return ['WireGuard → AWG 3', '/awg3 ' . str_replace('_', ' ', $context), [
                    $t('Поля и обновление клиентов', 'Fields and client updates') => $t(
                        'Все поля, кроме HeaderProtectionKey, задаются числом или диапазоном <code>LO-HI</code>; <code>0</code> возвращает значение по умолчанию. После изменения клиенты должны заново скачать конфиги. Header protection требует S1–S4 ≥ ' . self::AWG_HPK_MIN_S . '.',
                        'Fields other than HeaderProtectionKey accept a number or <code>LO-HI</code> range; <code>0</code> restores defaults. Clients must download updated profiles after changes. Header protection requires S1–S4 ≥ ' . self::AWG_HPK_MIN_S . '.'),
                    'RandomTrailers / DisableCookies' => $t(
                        '<b>RandomTrailers</b> добавляет случайный хвост к пакетам; клиент должен использовать то же значение. При диапазонах H1–H3 включение запрещено: текущий AWG может терять пакеты. Если опция уже была включена, отключите её в меню AWG и обновите конфиги клиентов; чтение подписки само по себе сервер не меняет. <b>DisableCookies</b> отключает cookie-reply и штатную защиту WireGuard от потока поддельных запросов подключения. Эти параметры требуют AWG 3.1 на обеих сторонах.',
                        '<b>RandomTrailers</b> adds random packet trailers and requires the same client setting. Enabling it with H1–H3 ranges is blocked because current AWG can drop packets. If already enabled, disable it in AWG settings and refresh client profiles; reading a subscription does not change the live server. <b>DisableCookies</b> disables cookie replies and WireGuard flood protection. Both require AWG 3.1 on both ends.'),
                    'mihomo awg3' => $t(
                        'Включает блок AWG 3.0 в подписке Mihomo: <code>amnezia-wg-option</code> и <code>version: 3</code>. Нужен совместимый клиент. Старый клиент может игнорировать эти поля и не подключиться к серверу AWG 3.0.',
                        'Includes <code>amnezia-wg-option</code> and <code>version: 3</code> in Mihomo subscriptions. Older clients may ignore these fields and fail to connect to AWG 3.0.'),
                ]];
            case 'relay':
                if ($context !== '' && !preg_match('~^[\w.-]{1,32}$~D', $context)) return [];
                return ['Vless → Relay', $context === '' ? '/relayMenu' : '/relayEdit ' . $context, [
                    $t('Что такое relay', 'What a relay is') => $t(
                        "<b>Relay</b> — промежуточный сервер между клиентом и этим сервером. Клиент подключается к relay, а relay пересылает соединение сюда (DNAT, «проброс порта»). Помогает, когда адрес сервера заблокирован или до него плохой маршрут из сети пользователя, а до relay — хороший.\n\n<b>Что делает бот:</b> только подставляет адрес и порт relay в ссылки, подписки и конфиги. Ключи, UUID, SNI, serverName, Host, DNS и маршруты остаются прежними: TLS и REALITY завершаются здесь, на основном сервере, relay видит только зашифрованный поток.\n\n<b>Чего бот не делает:</b> не ставит ПО на relay, не настраивает на нём пересылку и не открывает порты — это делаете вы (пример — на странице «Пересылка на relay»).\n\n<b>Порядок работы:</b>\n1. Настройте пересылку на relay.\n2. «➕ добавить relay» — имя: латиница, цифры, «.», «-», «_», до 32 символов. Имя видно в ссылках, менять его нельзя.\n3. В карточке relay задайте каналы нужных протоколов.\n4. Выдайте пользователю relay-подписку: карточка пользователя → «relay-подписки».",
                        "A <b>relay</b> is an intermediate server between the client and this server. The client connects to the relay, and the relay forwards the connection here (DNAT, \"port forwarding\"). It helps when the server address is blocked or badly routed from the user's network while the relay is reachable well.\n\n<b>What the bot does:</b> it only puts the relay address and port into links, subscriptions and configs. Keys, UUID, SNI, serverName, Host, DNS and routes stay the same: TLS and REALITY end here, on the main server; the relay sees only an encrypted stream.\n\n<b>What the bot does not do:</b> it does not install software on the relay, set up forwarding there or open ports. You do that (an example is on the \"Forwarding on the relay\" page).\n\n<b>Workflow:</b>\n1. Set up forwarding on the relay.\n2. \"➕ add relay\": a name of Latin letters, digits, \".\", \"-\", \"_\", up to 32 characters. The name appears in links and cannot be changed.\n3. In the relay card, set the channels of the protocols you need.\n4. Give the user a relay subscription: user card → \"relay subscriptions\"."),
                    $t('Каналы: где используется каждый', 'Channels: where each one is used') => $t(
                        "Один relay может пересылать разные протоколы на разные порты, поэтому у каждого протокола свой <b>канал</b> — адрес и порт на relay. Пустой канал значит «этот протокол через relay не идёт».\n\n<b>VLESS</b> (TCP) — relay-подписки пользователей (Xray JSON, sing-box, Mihomo, v2rayNG), «relay одной подпиской» и проверка статуса. Пересылать нужно TCP 443 сервера.\n\n<b>WireGuard / AWG</b> (UDP) — выбирается в меню WireGuard / AmneziaWG → relay и меняет Endpoint в выдаваемых конфигах и QR; ещё подставляется в прокси <code>awg</code> пользовательских шаблонов Mihomo. Пересылать нужно UDP-порт WireGuard.\n\n<b>Hysteria</b> (UDP) — ссылки hy2:// в меню Hysteria → relay. Пересылать нужно UDP-порт и диапазон port hopping, если он включён.\n\n<b>NaiveProxy</b> (TCP) — ссылки в меню NaiveProxy → relay. Адрес — <b>домен</b> из сертификата сервера с A-записью на relay: клиент проверяет сертификат по имени из ссылки.\n\n<b>AnyTLS, Mieru, TUIC, ShadowTLS, snolc, MASQUE</b> — адрес и порт одной строкой, например <code>relay.example.com 8443</code>. Используются в relay-подписках sing-box и Mihomo (кроме snolc и MASQUE) и в списке relay каждого протокола; <code>0</code> выключает канал.\n\nMTProxy (TeleMT) пользуется своим списком relay: меню TeleMT → relay.",
                        "One relay may forward different protocols to different ports, so each protocol has its own <b>channel</b>: an address and a port on the relay. An empty channel means \"this protocol does not go through the relay\".\n\n<b>VLESS</b> (TCP): users' relay subscriptions (Xray JSON, sing-box, Mihomo, v2rayNG), \"relays in one sub\" and the status check. Forward TCP 443 of the server.\n\n<b>WireGuard / AWG</b> (UDP): selected in the WireGuard / AmneziaWG menu → relay and changes the Endpoint in issued configs and QR codes; it is also put into the <code>awg</code> proxy of custom Mihomo templates. Forward the WireGuard UDP port.\n\n<b>Hysteria</b> (UDP): hy2:// links in the Hysteria menu → relay. Forward the UDP port and the port hopping range, if enabled.\n\n<b>NaiveProxy</b> (TCP): links in the NaiveProxy menu → relay. The address must be a <b>domain</b> from the server certificate with an A record pointing to the relay: the client checks the certificate against the name in the link.\n\n<b>AnyTLS, Mieru, TUIC, ShadowTLS, snolc, MASQUE</b>: address and port on one line, e.g. <code>relay.example.com 8443</code>. Used in sing-box and Mihomo relay subscriptions (except snolc and MASQUE) and in each protocol's relay list; <code>0</code> turns the channel off.\n\nMTProxy (TeleMT) uses its own relay list: TeleMT menu → relay."),
                    $t('Адрес, порт и карта портов', 'Address, port and port map') => $t(
                        "<b>Адрес</b> — домен или IP relay, без <code>https://</code> и без порта. <code>0</code> очищает поле. Неверный ввод не сохраняется: бот покажет причину.\n\n<b>Карта портов</b> — пары «порт сервера:порт relay» через запятую. Пример: relay принимает VLESS на 8443 и пересылает на 443 сервера — введите <code>443:8443</code>. Для WireGuard на UDP 443 relay: <code>51820:443</code>. Порт, которого нет в карте, остаётся как у сервера. Порты 1–65535; одна неверная пара отменяет весь ввод, прежняя карта остаётся.\n\n<b>Порт</b> (Hysteria, NaiveProxy) — одно число. У Hysteria он важнее карты и сводит диапазон port hopping в ссылке к одному порту: relay обычно слушает один UDP-порт. У NaiveProxy без порта используется 443.\n\nПорядок выбора порта: явный порт → карта → порт сервера.\n\n«🧹 Очистить канал» удаляет адрес и порты канала сразу.",
                        "<b>Address</b>: a relay domain or IP, without <code>https://</code> and without a port. <code>0</code> clears the field. Invalid input is not saved: the bot shows the reason.\n\n<b>Port map</b>: \"server port:relay port\" pairs separated by commas. Example: the relay accepts VLESS on 8443 and forwards it to 443 of the server, so enter <code>443:8443</code>. For WireGuard on relay UDP 443: <code>51820:443</code>. A port missing from the map stays as on the server. Ports 1–65535; one invalid pair cancels the whole input and the old map stays.\n\n<b>Port</b> (Hysteria, NaiveProxy): one number. For Hysteria it beats the map and collapses the port hopping range in the link to one port, since a relay usually listens on one UDP port. NaiveProxy without a port uses 443.\n\nPort choice order: explicit port → map → server port.\n\n\"🧹 Clear the channel\" removes the channel's address and ports at once."),
                    $t('Relay одной подпиской', 'Relays in one sub') => $t(
                        "Общий переключатель для всех пользователей.\n\n<b>Выключен</b> (по умолчанию): обычная подписка пользователя ведёт только на этот сервер; relay выдаются отдельными relay-подписками.\n\n<b>Включён</b>: подписка <b>v2rayNG (base64)</b> каждого пользователя содержит несколько серверов: этот сервер и по одному узлу на каждый relay с адресом VLESS. Пользователь сам выбирает узел в приложении или пингует их. Имя узла relay начинается с флагов страны relay и страны сервера.\n\nRelay, чья последняя проверка ответила ⛔, из общей подписки временно убирается и возвращается после удачной проверки. Relay, которые ещё ни разу не проверялись, включаются.\n\n<b>Где действует:</b> только base64-подписка (кнопка «v2rayNG (base64)» и импорт в Shadowrocket, Streisand, Hiddify). Xray JSON, sing-box и Mihomo по-прежнему содержат один основной узел — для них есть отдельные relay-подписки. Отдельная relay-подписка всегда содержит только свой relay, независимо от переключателя.",
                        "A shared switch for all users.\n\n<b>Off</b> (default): a user's normal subscription leads only to this server; relays are issued as separate relay subscriptions.\n\n<b>On</b>: every user's <b>v2rayNG (base64)</b> subscription holds several servers: this server and one node for each relay with a VLESS address. The user picks a node in the app or pings them. A relay node name starts with the flags of the relay's country and the server's country.\n\nA relay whose last check answered ⛔ is temporarily left out of the shared subscription and returns after a successful check. Relays that were never checked are included.\n\n<b>Where it applies:</b> only the base64 subscription (the \"v2rayNG (base64)\" button and the Shadowrocket, Streisand, Hiddify import). Xray JSON, sing-box and Mihomo still hold one main node; separate relay subscriptions exist for them. A separate relay subscription always holds only its own relay, whatever the switch."),
                    $t('Статус relay', 'Relay status') => $t(
                        "Раз в минуту служба бота открывает TCP-соединение с адресом и портом канала VLESS (порт 443 через карту) и отдельно — канала NaiveProxy, если он другой. Данные не отправляются.\n\n<b>✅ 42ms</b> — соединение принято за 42 мс; рядом — сколько времени прошло с проверки.\n<b>⛔ …</b> — соединение не установилось (текст ошибки системы).\nПусто — проверки ещё не было или канал не задан.\n\n✅ говорит, что relay принимает соединения; полную работу пересылки подтверждает только подключение клиента. UDP-каналы (WireGuard, Hysteria) так не проверить, поэтому у них статуса нет.\n\nСтатус используется в «relay одной подпиской»: relay с ⛔ туда не попадает.",
                        "Once a minute the bot service opens a TCP connection to the address and port of the VLESS channel (port 443 through the map) and, separately, of the NaiveProxy channel if it differs. No data is sent.\n\n<b>✅ 42ms</b>: the connection was accepted in 42 ms; next to it is the time since the check.\n<b>⛔ …</b>: the connection failed (the system error text).\nEmpty: no check yet, or the channel is not set.\n\n✅ means the relay accepts connections; only a client connection proves the forwarding fully works. UDP channels (WireGuard, Hysteria) cannot be checked this way, so they have no status.\n\nThe status is used by \"relays in one sub\": a relay with ⛔ is left out."),
                    $t('Пересылка на relay', 'Forwarding on the relay') => $t(
                        "Пример для relay на Linux с nftables: VLESS на TCP 443 и WireGuard на UDP 51820, <code>SERVER</code> — адрес этого сервера.\n<pre><code>sysctl -w net.ipv4.ip_forward=1\nnft add table ip relay\nnft 'add chain ip relay pre { type nat hook prerouting priority -100; }'\nnft 'add chain ip relay post { type nat hook postrouting priority 100; }'\nnft add rule ip relay pre tcp dport 443 dnat to SERVER:443\nnft add rule ip relay pre udp dport 51820 dnat to SERVER:51820\nnft add rule ip relay post ip daddr SERVER masquerade</code></pre>\nПравила nft живут до перезагрузки: сохраните их в конфиг nftables relay. Подойдут и iptables, socat, haproxy — важно лишь, чтобы порт relay вёл на нужный порт сервера.\n\n<b>Обратите внимание:</b>\n• Межсетевой экран этого сервера должен пускать адрес relay. Если вход разрешён только списку адресов, добавьте туда relay.\n• С masquerade сервер видит адрес relay вместо адреса клиента: лимит IP и журнал подключений считают всех клиентов relay одним адресом.\n• Пересылайте только нужные порты, а не весь трафик: открытый relay станет прокси для посторонних.",
                        "An example for a Linux relay with nftables: VLESS on TCP 443 and WireGuard on UDP 51820, <code>SERVER</code> is this server's address.\n<pre><code>sysctl -w net.ipv4.ip_forward=1\nnft add table ip relay\nnft 'add chain ip relay pre { type nat hook prerouting priority -100; }'\nnft 'add chain ip relay post { type nat hook postrouting priority 100; }'\nnft add rule ip relay pre tcp dport 443 dnat to SERVER:443\nnft add rule ip relay pre udp dport 51820 dnat to SERVER:51820\nnft add rule ip relay post ip daddr SERVER masquerade</code></pre>\nnft rules live until a reboot: save them in the relay's nftables config. iptables, socat or haproxy also work; what matters is that the relay port leads to the right server port.\n\n<b>Note:</b>\n• This server's firewall must accept the relay address. If only a list of addresses may connect, add the relay to it.\n• With masquerade the server sees the relay address instead of the client's: the IP limit and the connection log count all relay clients as one address.\n• Forward only the needed ports, not all traffic: an open relay becomes a proxy for strangers."),
                    $t('Удаление relay', 'Deleting a relay') => $t(
                        "«🗑 удалить relay» сначала спрашивает подтверждение.\n\nПосле удаления:\n• relay-подписки через него перестают обновляться: сервер отвечает «Relay not found», пользователю нужна новая подписка (другой relay или обычная);\n• relay пропадает из «relay одной подпиской» и из выбора в меню WireGuard, Hysteria, NaiveProxy и протоколов-модулей; выбор в WireGuard возвращается к прямому адресу сервера;\n• маршрут SNI для домена NaiveProxy убирается из nginx;\n• уже скачанные конфиги и ссылки с адресом relay работают, пока relay пересылает трафик.\n\nЧтобы временно убрать relay из выдачи, не удаляя его, очистите нужные каналы.",
                        "\"🗑 delete relay\" asks for confirmation first.\n\nAfter deletion:\n• relay subscriptions through it stop refreshing: the server answers \"Relay not found\", the user needs a new subscription (another relay or the normal one);\n• the relay disappears from \"relays in one sub\" and from the choice in the WireGuard, Hysteria, NaiveProxy and module protocol menus; the WireGuard choice returns to the direct server address;\n• the SNI route for the NaiveProxy domain is removed from nginx;\n• configs and links already downloaded with the relay address work while the relay forwards traffic.\n\nTo take a relay out of issuing temporarily without deleting it, clear the needed channels."),
                ]];
            case 'relay_user':
                if (!preg_match('~^\d{1,6}$~D', $context)) return [];
                return ['Vless → ' . $t('relay-подписки', 'relay subscriptions'), '/userRelay ' . $context, [
                    $t('Что это', 'What it is') => $t(
                        "Relay-подписка — та же подписка пользователя, но приложение подключается не к этому серверу, а к выбранному relay. Бот меняет в ней только адрес и порт; ключи, SNI, шаблон, маршруты, DNS, срок, лимит трафика и лимит устройств (HWID) остаются общими с обычной подпиской.\n\nСписок показывает relay, у которых задан хотя бы один канал для подписок: VLESS, WG/AWG или протокол-модуль. Рядом — статус последней проверки канала VLESS.\n\nНа экране relay первые строки показывают, что пойдёт через него:\n• <b>VLESS</b> — через relay или напрямую, если у relay нет адреса VLESS;\n• <b>WG/AWG</b> — только для прокси <code>awg</code> в своих шаблонах Mihomo;\n• <b>протоколы-модули</b> (AnyTLS, Mieru, TUIC, ShadowTLS) — в sing-box и Mihomo входят только те, у которых есть канал на этом relay; остальные в relay-подписку не попадают, чтобы не вести клиента мимо relay.\n\n<b>Важно:</b> саму подписку приложение скачивает и обновляет не через relay, а с домена этого сервера (при WS/XHTTP/gRPC — с домена для ссылок, если он задан). Если этот домен у пользователя недоступен, подписка не обновится, но подключение через relay продолжит работать с последним скачанным конфигом.",
                        "A relay subscription is the same user subscription, but the app connects to the chosen relay instead of this server. The bot changes only the address and port in it; keys, SNI, template, routes, DNS, expiry, traffic limit and device limit (HWID) stay shared with the normal subscription.\n\nThe list shows relays with at least one channel for subscriptions: VLESS, WG/AWG or a module protocol. Next to it is the status of the last VLESS channel check.\n\nOn a relay screen the first lines show what goes through it:\n• <b>VLESS</b>: through the relay, or directly if the relay has no VLESS address;\n• <b>WG/AWG</b>: only for the <code>awg</code> proxy in custom Mihomo templates;\n• <b>module protocols</b> (AnyTLS, Mieru, TUIC, ShadowTLS): sing-box and Mihomo include only those with a channel on this relay; the rest are left out of the relay subscription so the client is not led around the relay.\n\n<b>Note:</b> the app downloads and refreshes the subscription itself not through the relay but from this server's domain (with WS/XHTTP/gRPC, from the link domain if set). If that domain is unreachable for the user, the subscription does not refresh, but the connection through the relay keeps working with the last downloaded config."),
                    $t('Какую ссылку выбрать', 'Which link to choose') => $t(
                        "<b>import://…</b> — открыть подписку сразу в приложении:\n• v2rayNG, INCY — Xray JSON (с маршрутами бота);\n• Shadowrocket, Streisand, Hiddify — base64-список ссылок;\n• sing-box, Karing — sing-box;\n• mihomo, Rabbit Hole — Mihomo.\n\nАдреса ниже вставляются в приложение вручную как URL подписки:\n• <b>v2rayNG (base64)</b> — список ссылок vless://; сюда же добавляются внешние ссылки пользователя;\n• <b>xray (json)</b> — полный конфиг Xray;\n• <b>sing-box</b>, <b>Mihomo YAML</b>, <b>Mihomo JSON</b> — полные конфиги этих ядер.\n\nВсе ссылки содержат имя relay. Приложение само обновляет подписку — изменения адреса и порта relay доходят до клиента при следующем обновлении.",
                        "<b>import://…</b> opens the subscription right in the app:\n• v2rayNG, INCY: Xray JSON (with the bot's routes);\n• Shadowrocket, Streisand, Hiddify: a base64 list of links;\n• sing-box, Karing: sing-box;\n• mihomo, Rabbit Hole: Mihomo.\n\nThe addresses below are pasted into the app by hand as a subscription URL:\n• <b>v2rayNG (base64)</b>: a list of vless:// links; the user's external links are added here too;\n• <b>xray (json)</b>: a full Xray config;\n• <b>sing-box</b>, <b>Mihomo YAML</b>, <b>Mihomo JSON</b>: full configs of these cores.\n\nAll links carry the relay name. The app refreshes the subscription by itself, so changes of the relay address and port reach the client at the next refresh."),
                    $t('Если relay удалён или не работает', 'If the relay is deleted or down') => $t(
                        "Если relay удалили, сервер отвечает на его подписку «Relay not found», и приложение оставляет последний скачанный конфиг. Выдайте пользователю подписку через другой relay или обычную.\n\nЕсли relay не отвечает (⛔), отдельная relay-подписка всё равно выдаётся: бот не подменяет relay сервером сам. Для автоматического выбора включите «relay одной подпиской» — тогда в base64-подписке будут и сервер, и все рабочие relay.\n\nВыключенный пользователь, истёкший срок или исчерпанный трафик закрывают и relay-подписки.",
                        "If the relay was deleted, the server answers its subscription with \"Relay not found\", and the app keeps the last downloaded config. Give the user a subscription through another relay or the normal one.\n\nIf the relay does not answer (⛔), the separate relay subscription is still served: the bot does not replace the relay with the server on its own. For automatic choice turn on \"relays in one sub\": the base64 subscription then holds the server and every working relay.\n\nA disabled user, an expired term or used-up traffic also close relay subscriptions."),
                    $t('Безопасность подписки', 'Subscription security') => $t(
                        "• <b>Шифрование.</b> При выпущенном сертификате все адреса подписок начинаются с https://: и токен, и содержимое (ключи, UUID) идут внутри TLS. Сервер добавляет HSTS, поэтому приложение, однажды скачавшее подписку по https, не перейдёт на http. Без сертификата бот выдаёт http://-адреса и предупреждает об этом в карточке пользователя.\n• <b>Токен.</b> Ссылку на подписку задаёт случайный токен из 128 бит, отдельный от UUID. Хвост адреса (base64) — это не шифр, а упаковка параметров: в нём только токен, формат и имя relay. «Строгий токен подписки» в меню Vless отключает старые ссылки по UUID; «сменить ссылку подписки» в карточке пользователя делает прежние ссылки недействительными, в том числе relay-подписки.\n• <b>Журналы.</b> Путь подписки в журнал nginx не пишется, ответы запрещено кешировать (no-store), Referer не передаётся.\n• <b>Перебор.</b> Запросы ограничены по адресу (по умолчанию 30 за 5 минут, неверные токены — 20); можно включить лимит устройств HWID.\n• <b>Relay</b> видит только зашифрованный поток и не может прочитать подписку или трафик.\n• При «relay одной подпиской» каждый пользователь видит адреса всех рабочих relay с каналом VLESS.",
                        "• <b>Encryption.</b> With a certificate issued, every subscription address starts with https://: both the token and the content (keys, UUID) travel inside TLS. The server adds HSTS, so an app that once downloaded the subscription over https will not fall back to http. Without a certificate the bot issues http:// addresses and warns about it in the user card.\n• <b>Token.</b> The subscription link is set by a random 128-bit token separate from the UUID. The base64 tail of the address is not a cipher but packed parameters: only the token, the format and the relay name. \"Strict sub token\" in the Vless menu turns off old links by UUID; \"rotate sub link\" in the user card invalidates the old links, relay subscriptions included.\n• <b>Logs.</b> The subscription path is not written to the nginx log, responses must not be cached (no-store), and no Referer is sent.\n• <b>Guessing.</b> Requests are limited per address (by default 30 per 5 minutes, wrong tokens 20); an HWID device limit can be turned on.\n• <b>A relay</b> sees only an encrypted stream and cannot read the subscription or the traffic.\n• With \"relays in one sub\" every user sees the addresses of all working relays with a VLESS channel."),
                ]];
            case 'ext':
                if (!preg_match('~^\d{1,6}$~D', $context)) return [];
                return ['Vless → ' . $t('внешние ссылки', 'external links'), '/extUser ' . $context, [
                    $t('Что это и куда попадает', 'What it is and where it goes') => $t(
                        "Внешние ссылки — подключения к <b>другим серверам</b> (не этому боту), которые выдаются пользователю вместе с его подпиской. Так одна подписка содержит и этот сервер, и, например, запасной сервер другой панели.\n\n<b>Где появляются:</b> только в подписке <b>v2rayNG (base64)</b> — её берут кнопки импорта Shadowrocket, Streisand, Hiddify и адрес «v2rayNG (base64)», в том числе в relay-подписках. В Xray JSON, sing-box и Mihomo внешних ссылок нет: это готовые конфиги одного ядра.\n\nСписок у каждого пользователя свой. Строка списка: номер, ✅ или ⛔ (включена или выключена), 🔗 ссылка или 📥 подписка, имя. Кнопки строки: нажатие на имя — включить или выключить, ✏️ — переименовать, 🗑 — удалить. Выключенная строка хранится, но в подписку не попадает.\n\nКнопки адресуют строку с проверкой: если список уже изменился (например, строку удалили в другом сообщении), бот ничего не сделает и попросит нажать ещё раз.",
                        "External links are connections to <b>other servers</b> (not this bot) that the user gets together with their subscription. One subscription then holds this server and, for example, a backup server of another panel.\n\n<b>Where they appear:</b> only in the <b>v2rayNG (base64)</b> subscription, used by the Shadowrocket, Streisand, Hiddify import buttons and the \"v2rayNG (base64)\" address, relay subscriptions included. Xray JSON, sing-box and Mihomo have no external links: they are ready configs of one core.\n\nEach user has their own list. A list line: number, ✅ or ⛔ (on or off), 🔗 link or 📥 subscription, name. Line buttons: tapping the name turns it on or off, ✏️ renames, 🗑 deletes. An off line is kept but not added to the subscription.\n\nButtons address a line with a check: if the list has changed (for example, the line was deleted in another message), the bot does nothing and asks you to tap again."),
                    $t('Внешняя ссылка', 'External link') => $t(
                        "«🔗 добавить внешнюю ссылку» — одна или несколько ссылок, по одной на строку: <code>vless://</code>, <code>vmess://</code>, <code>trojan://</code>, <code>ss://</code>, <code>ssr://</code>, <code>hysteria2://</code>, <code>hy2://</code>, <code>tuic://</code>, <code>wireguard://</code>, <code>anytls://</code>, <code>snell://</code>, <code>socks://</code>. Другие строки не принимаются, бот сообщит, сколько отклонено. Повтор уже добавленной ссылки пропускается.\n\nСсылка выдаётся как есть. Бот не проверяет, жив ли сервер в ней, и не меняет её адрес — relay на внешние ссылки не действует.\n\n✏️ задаёт имя, которое увидит пользователь (до 64 символов; для vmess оно пишется в поле <code>ps</code>, для остальных — после <code>#</code>). <code>0</code> возвращает исходное имя ссылки.",
                        "\"🔗 add external link\": one or several links, one per line: <code>vless://</code>, <code>vmess://</code>, <code>trojan://</code>, <code>ss://</code>, <code>ssr://</code>, <code>hysteria2://</code>, <code>hy2://</code>, <code>tuic://</code>, <code>wireguard://</code>, <code>anytls://</code>, <code>snell://</code>, <code>socks://</code>. Other lines are rejected and the bot says how many. A repeat of a link already added is skipped.\n\nThe link is issued as is. The bot does not check whether its server is alive and does not change its address: relays do not apply to external links.\n\n✏️ sets the name the user sees (up to 64 characters; for vmess it goes into the <code>ps</code> field, for the rest after <code>#</code>). <code>0</code> restores the link's original name."),
                    $t('Внешняя подписка', 'External subscription') => $t(
                        "«📥 добавить внешнюю подписку» — адрес подписки другого сервиса, только <code>https://</code>. Можно несколько, по одному на строку.\n\n<b>Как обновляется:</b> бот скачивает её сам — сразу при добавлении и затем раз в 5 минут. Пользователь получает узлы из последней удачной загрузки; в момент запроса подписки бот никуда не обращается, поэтому чужой сервис не замедляет и не ломает подписку.\n\nОтвет может быть base64 или списком ссылок по строкам. Берутся только ссылки поддерживаемых схем, до 200 узлов на пользователя; ответ больше 2 МиБ отклоняется. Имена узлов — как у источника; ✏️ у подписки меняет только подпись строки в меню.\n\nЕсли загрузка не удалась, в подписке остаются узлы прошлой удачной загрузки — до следующей удачной. Сам список строк входит в резервную копию; скачанные узлы — нет: после восстановления бот загрузит подписки заново.",
                        "\"📥 add external subscription\": a subscription address of another service, <code>https://</code> only. Several are allowed, one per line.\n\n<b>How it refreshes:</b> the bot downloads it itself, right after adding and then every 5 minutes. The user gets the nodes of the last successful download; the bot contacts nothing while serving the subscription, so a foreign service neither slows down nor breaks it.\n\nThe answer may be base64 or a list of links by lines. Only links of supported schemes are taken, up to 200 nodes per user; an answer over 2 MiB is rejected. Node names stay as in the source; ✏️ on a subscription changes only the line label in the menu.\n\nIf a download fails, the subscription keeps the nodes of the last successful one until the next success. The list of lines is part of the backup; downloaded nodes are not: after a restore the bot downloads the subscriptions again."),
                    $t('Статусы и ошибки', 'Statuses and errors') => $t(
                        "У строки подписки показывается состояние:\n• <b>узлов: N · 5m</b> — последняя загрузка удачна, N ссылок, столько минут (m) или часов (h) назад;\n• <b>ещё не загружено</b> — загрузки ещё не было;\n• <b>⚠️ ошибка</b> — последняя попытка не удалась; если раньше была удачная, рядом число её узлов.\n\nЧастые ошибки:\n• <code>blocked: non-https or private/unresolvable host</code> — не https, имя не разрешается или указывает на внутренний адрес;\n• <code>http 403/404</code> — сервис отказал: проверьте адрес и User-Agent;\n• <code>no supported links in response</code> — пришла страница или конфиг (YAML/JSON), а не список ссылок: смените User-Agent;\n• <code>connection/timeout error</code> — сервис не ответил за 6 секунд;\n• <code>response too large</code>, <code>unsafe redirect target</code>, <code>too many redirects</code> — ответ больше 2 МиБ, переадресация не на https или больше 3 переадресаций.",
                        "A subscription line shows its state:\n• <b>nodes: N · 5m</b>: the last download succeeded, N links, that many minutes (m) or hours (h) ago;\n• <b>not fetched yet</b>: no download yet;\n• <b>⚠️ error</b>: the last attempt failed; if an earlier one succeeded, its node count is next to it.\n\nCommon errors:\n• <code>blocked: non-https or private/unresolvable host</code>: not https, the name does not resolve or points to an internal address;\n• <code>http 403/404</code>: the service refused: check the address and the User-Agent;\n• <code>no supported links in response</code>: a page or a config (YAML/JSON) came instead of a list of links: change the User-Agent;\n• <code>connection/timeout error</code>: the service did not answer within 6 seconds;\n• <code>response too large</code>, <code>unsafe redirect target</code>, <code>too many redirects</code>: an answer over 2 MiB, a redirect not to https, or more than 3 redirects."),
                    $t('User-Agent загрузки', 'Fetch User-Agent') => $t(
                        "<b>User-Agent</b> — название программы, которым бот представляется, когда скачивает внешние подписки. Панели (3x-ui, Marzban, Remnawave и другие) по нему решают, что отдать: список ссылок, конфиг Clash/Mihomo или sing-box, конфиг Xray JSON либо страницу для браузера.\n\nБот разбирает только <b>список ссылок</b> (обычный или base64). Поэтому по умолчанию он представляется старой версией v2rayNG — <code>v2rayNG/1.8.5</code>: такой клиент получает ссылки почти в любой панели. Новым версиям v2rayNG (с 1.8.18), v2rayN (с 6.40) и Happ (с 1.63.1) Marzban и Remnawave могут отдавать JSON — его бот не примет.\n\n<b>Когда менять:</b> сервис отвечает 403 или пустым списком, в строке подписки ошибка <code>no supported links in response</code>, либо сервис пускает только определённое приложение. Готовые значения — на странице «Список User-Agent» и в сообщении, которое бот присылает по кнопке.\n\n<b>Как менять:</b> кнопка «🕵️ User-Agent загрузки» → нажмите на значение в сообщении, оно скопируется → отправьте его ответом. <code>-</code> возвращает <code>v2rayNG/1.8.5</code>. Допустимы печатные латинские символы, до 200.\n\nЗначение одно на весь бот: действует на все внешние подписки всех пользователей, хотя кнопка находится в карточке пользователя. После изменения подписки этого пользователя скачиваются заново сразу, остальные — в течение 5 минут. На подписки, которые бот выдаёт сам, User-Agent не влияет.",
                        "The <b>User-Agent</b> is the program name the bot presents when it downloads external subscriptions. Panels (3x-ui, Marzban, Remnawave and others) use it to decide what to return: a list of links, a Clash/Mihomo or sing-box config, an Xray JSON config, or a page for a browser.\n\nThe bot parses only a <b>list of links</b> (plain or base64). So by default it presents itself as an old v2rayNG version, <code>v2rayNG/1.8.5</code>: such a client gets links from almost any panel. Newer versions of v2rayNG (from 1.8.18), v2rayN (from 6.40) and Happ (from 1.63.1) may get JSON from Marzban and Remnawave, which the bot does not accept.\n\n<b>When to change it:</b> the service answers 403 or an empty list, the subscription line shows <code>no supported links in response</code>, or the service lets in only a specific app. Ready values are on the \"User-Agent list\" page and in the message the bot sends from the button.\n\n<b>How to change it:</b> the \"🕵️ Fetch User-Agent\" button → tap a value in the message to copy it → send it as a reply. <code>-</code> restores <code>v2rayNG/1.8.5</code>. Printable Latin characters are allowed, up to 200.\n\nThere is one value for the whole bot: it applies to all external subscriptions of all users, even though the button is in a user card. After a change this user's subscriptions are downloaded again at once, the rest within 5 minutes. The User-Agent does not affect the subscriptions the bot serves itself."),
                    $t('Список User-Agent', 'User-Agent list') => $t('Подходят — сервис отдаёт на них список ссылок (нажмите, чтобы скопировать):', 'Suitable: the service returns a list of links for them (tap to copy):')
                        . "\n" . implode("\n", $this->extSubUserAgentPresetLines()) . "\n\n" . $t(
                        "Версия в значении важна только для v2rayNG, v2rayN и Happ: панели (например, Marzban) сравнивают её с порогами выше. У Streisand и Shadowrocket проверяется лишь название; Streisand тоже может получить JSON, если в панели включён такой режим — тогда выберите другое значение.\n\n<b>Не подходят</b> — сервисы отдают на них конфиг, а не ссылки:\n• <code>clash-verge</code>, <code>ClashMeta</code>, <code>FlClash</code>, <code>mihomo</code>, <code>Stash</code> — YAML Clash/Mihomo;\n• <code>SFA</code>, <code>SFI</code>, <code>SFM</code> (sing-box), <code>Karing</code>, <code>HiddifyNext</code> — JSON sing-box;\n• новые <code>v2rayNG</code>, <code>v2rayN</code>, <code>Happ</code> — в некоторых панелях Xray JSON;\n• браузер (<code>Mozilla/…</code>) — HTML-страница подписки.\n\nСервисы, которые привязывают подписку к устройству (HWID) или требуют свои заголовки, по одному User-Agent могут не отдать узлы: бот такие заголовки не отправляет.",
                        "The version in a value matters only for v2rayNG, v2rayN and Happ: panels (for example, Marzban) compare it with the thresholds above. For Streisand and Shadowrocket only the name is checked; Streisand may also get JSON if the panel has that mode on, so pick another value then.\n\n<b>Not suitable</b>: services return a config for them, not links:\n• <code>clash-verge</code>, <code>ClashMeta</code>, <code>FlClash</code>, <code>mihomo</code>, <code>Stash</code>: Clash/Mihomo YAML;\n• <code>SFA</code>, <code>SFI</code>, <code>SFM</code> (sing-box), <code>Karing</code>, <code>HiddifyNext</code>: sing-box JSON;\n• new <code>v2rayNG</code>, <code>v2rayN</code>, <code>Happ</code>: Xray JSON in some panels;\n• a browser (<code>Mozilla/…</code>): the subscription HTML page.\n\nServices that bind a subscription to a device (HWID) or require their own headers may not return nodes for a User-Agent alone: the bot does not send such headers."),
                    $t('Безопасность', 'Security') => $t(
                        "• Бот скачивает подписки только по https и только с публичных адресов: внутренние сети, localhost и адреса Docker запрещены, адрес проверяется на каждой переадресации и закрепляется на время соединения.\n• Скачанные узлы содержат чужие ключи и пароли: кэш хранится в файле с доступом только для владельца и в резервную копию не входит.\n• Из ответа берутся только ссылки поддерживаемых схем: страницы, скрипты и прочие строки отбрасываются.\n• Внешние ссылки видит каждый, у кого есть подписка пользователя. Добавляйте только серверы, которыми готовы поделиться с этим пользователем.",
                        "• The bot downloads subscriptions only over https and only from public addresses: internal networks, localhost and Docker addresses are forbidden; the address is checked on every redirect and pinned for the connection.\n• Downloaded nodes carry foreign keys and passwords: the cache is kept in an owner-only file and is not part of the backup.\n• Only links of supported schemes are taken from an answer: pages, scripts and other lines are dropped.\n• Anyone with the user's subscription sees the external links. Add only servers you are ready to share with this user."),
                ]];
            case 'naive_relay':
                if ($context !== '' && !preg_match('~^[\w.-]{1,32}$~D', $context)) return [];
                return ['NaiveProxy → Relay', $context === '' ? '/npRelay' : '/npRelaySub ' . $context, [$t('Адрес, SNI и сертификат', 'Address, SNI and certificate') => $this->i18n('naive relay hint')]];
        }
        if (str_starts_with($topic, 'ps_')) {
            $protocol = substr($topic, 3);
            if (!isset(ManagedProtocol::NAMES[$protocol]) || !preg_match('~^([a-f0-9]{16})\.(direct|[a-f0-9]{16})$~D', $context, $m)) return [];
            $pages = $this->protocolHelpPages($protocol);
            if (!in_array($protocol, ['snolc', 'masque'], true)) {
                $pages[$this->t('Форматы подписок', 'Subscription formats')] = $this->t(
                    'Ссылки в этом меню относятся к отдельному доступу. Общая подписка в меню VLESS сохраняет DNS и маршрутизацию выбранного шаблона, включая TUN. Provider подключает только список прокси к существующему Mihomo / XKeen.',
                    'Links in this menu belong to the separate access. The shared subscription in the VLESS menu keeps the DNS and routing of the selected template, including TUN. Provider adds only the proxy list to an existing Mihomo / XKeen.')
                    . ($protocol === 'mieru'
                        ? $this->t("\n\nНативный Mieru: скачайте JSON и выполните <code>mieru apply config</code>. CLI не обновляет HTTP-подписки автоматически. Для автообновления используйте Mihomo.",
                            "\n\nNative Mieru: download the JSON and run <code>mieru apply config</code>. The CLI does not refresh HTTP subscriptions automatically. Use Mihomo for auto-update.")
                        : $this->t("\n\nsing-box JSON отдельного доступа создаёт локальный SOCKS/HTTP на <code>127.0.0.1:1080</code>. Это отличается от полной общей подписки пользователя VLESS.",
                            "\n\nThe sing-box JSON of the separate access creates a local SOCKS/HTTP on <code>127.0.0.1:1080</code>. This differs from the full shared subscription of the VLESS user."));
            }
            return [ManagedProtocol::NAMES[$protocol] . ' → ' . $this->t('Подписки', 'Subscriptions'), "/ps $protocol {$m[1]} {$m[2]}", $pages];
        }
        if (str_starts_with($topic, 'p_')) {
            $protocol = substr($topic, 2);
            if (!isset(ManagedProtocol::NAMES[$protocol])) return [];
            if ($context === '') $back = '/protocol ' . $protocol;
            elseif (preg_match('~^page_(\d{1,6})$~D', $context, $m)) $back = "/protocol $protocol page {$m[1]}";
            elseif (preg_match('~^[a-f0-9]{16}$~D', $context)) $back = "/protocol $protocol user $context";
            else return [];
            return [ManagedProtocol::NAMES[$protocol], $back, $this->protocolHelpPages($protocol)];
        }
        return [];
    }

    private function protocolHelpPages(string $protocol): array
    {
        $t = fn(string $ru, string $en) => $this->t($ru, $en);
        $about = match ($protocol) {
            'snolc' => $t('Экспериментальный snolc: SSH + Noise на отдельном TCP-порту. UDP приложений передаётся внутри SSH. TLS-сертификат и SNI не требуются. Нативный клиент — Linux x86_64. Импорт SSH-режима в snolcNG пока не поддерживается.',
                'Experimental snolc: SSH + Noise on a separate TCP port. Application UDP is carried inside SSH. No TLS certificate or SNI is needed. The native client is Linux x86_64. Importing the SSH mode into snolcNG is not supported yet.'),
            'mieru' => $t('Mieru использует отдельный порт без TLS. Транспорт TCP/UDP относится к соединению с сервером; оба передают TCP и UDP приложений. В общих подписках бот добавляет Mieru только в Mihomo.',
                'Mieru uses a separate port without TLS. The TCP/UDP transport refers to the connection to the server; both carry application TCP and UDP. In shared subscriptions the bot adds Mieru only to Mihomo.'),
            'shadowtls' => $t('SNI — домен сайта прикрытия с действительным TLS 1.3. Сертификат этого сайта на VPS не устанавливается. Внутренний SS2022 закрыт от внешних подключений. UDP доступен через UoT v2 внутри TCP, если включён соответствующий переключатель.',
                'SNI is the domain of a cover site with valid TLS 1.3. That site\'s certificate is not installed on the VPS. The inner SS2022 is closed to outside connections. UDP is available through UoT v2 inside TCP when the corresponding switch is on.'),
            'tuic' => $t('TUIC v5 использует UDP-порт. Блокировка UDP прерывает и TCP, и UDP приложений. Проверка TLS включена; нужен действительный сертификат на SNI. После добавления имени обновите SSL в настройках.',
                'TUIC v5 uses a UDP port. Blocking UDP interrupts both application TCP and UDP. TLS verification is on; a valid certificate for the SNI is required. After adding a name, renew SSL in the settings.'),
            'masque' => $t('MASQUE CONNECT-IP: HTTP/3 по UDP и HTTP/2 по TCP на одном отдельном порту. Клиент — Xray 26.9.30+. Нужен действительный сертификат SNI. Клиенты изолированы; доступ к внутренним адресам запрещён. UDP-маскировка действует только на HTTP/3; HTTP/2 её не использует.',
                'MASQUE CONNECT-IP: HTTP/3 over UDP and HTTP/2 over TCP on one separate port. The client is Xray 26.9.30+. A valid SNI certificate is required. Clients are isolated; access to internal addresses is denied. UDP masking applies only to HTTP/3; HTTP/2 does not use it.'),
            default => $t('AnyTLS требует действительный сертификат на SNI. При выборе собственного сайта поддомен создаётся в настройках бота, но DNS-запись необходимо направить на сервер самостоятельно. После добавления имени обновите SSL в настройках.',
                'AnyTLS requires a valid certificate for the SNI. When you choose your own site, the subdomain is created in the bot settings, but you must point its DNS record to the server yourself. After adding a name, renew SSL in the settings.'),
        };
        $export = match ($protocol) {
            'masque' => $t('Скачайте JSON и запустите Xray 26.9.30+: <code>xray run -config profile.json</code>. Локальный SOCKS5: <code>127.0.0.1:1080</code>. После изменения настроек скачайте профиль заново: CLI не обновляет его автоматически.',
                'Download the JSON and run Xray 26.9.30+: <code>xray run -config profile.json</code>. Local SOCKS5: <code>127.0.0.1:1080</code>. After a settings change download the profile again: the CLI does not update it automatically.'),
            'snolc' => $t('Архив содержит профиль, установщик клиента Linux x86_64 и инструкцию. SSH и Noise проверяют ключи сервера; личный ключ управляет доступом. После изменения параметров скачайте архив заново; CLI не обновляет его автоматически.',
                'The archive contains the profile, the Linux x86_64 client installer and instructions. SSH and Noise verify the server keys; the personal key controls access. After a parameter change download the archive again; the CLI does not update it automatically.'),
            default => $t('«Полный профиль» — готовый конфиг клиента. «Запись прокси» — блок для раздела <code>proxies</code> существующего Mihomo/XKeen; порты, DNS и правила остаются вашими. Файлы и QR временные: сохраните их до следующего нажатия в меню.',
                'Full profile is a ready client config. Proxy entry is a block for the <code>proxies</code> section of an existing Mihomo/XKeen; ports, DNS and rules stay yours. Files and QR codes are temporary: save them before the next tap in the menu.'),
        };
        return [
            $t('Протокол и подключение', 'Protocol and connection') => $about,
            $t('Доступы, лимиты и WARP', 'Access, limits and WARP') => $t(
                'Новые доступы связаны с пользователями VLESS: срок, выключатель и лимит общие. Профиль находится в карточке пользователя → Отдельные подключения. MASQUE и snolc не включаются в общие подписки старых клиентов.'
                . "\n\nAnyTLS, TUIC и ShadowTLS включаются в полную подписку Mihomo / sing-box; Mieru — только в Mihomo."
                . "\n\nСрок проверяется каждую секунду, расход — каждые 5 секунд. Отзыв завершает соединения этого протокола. Изменение настроек сервера тоже перезапускает его соединения.",
                'New access entries are tied to VLESS users: expiry, the switch and the limit are shared. The profile is in the user card → Separate connections. MASQUE and snolc are not included in the shared subscriptions of old clients.'
                . "\n\nAnyTLS, TUIC and ShadowTLS are included in the full Mihomo / sing-box subscription; Mieru only in Mihomo."
                . "\n\nExpiry is checked every second, usage every 5 seconds. Revoking closes this protocol's connections. Changing the server settings also restarts its connections.")
                . ($protocol === 'mieru' ? $t("\n\nСброс общего расхода не сбрасывает историю периодической квоты ядра Mieru.", "\n\nResetting the shared usage does not reset the history of the Mieru core's periodic quota.") : '')
                . ($protocol === 'snolc' ? '' : $t("\n\nВыход через WARP передаёт TCP и поддерживаемый этим протоколом UDP. Переключатели UDP сохраняют своё действие. При отказе WARP прямой обход не включается.",
                    "\n\nEgress through WARP carries TCP and the UDP this protocol supports. UDP switches keep their effect. If WARP fails, no direct bypass is enabled.")),
            $t('Профили и подписки', 'Profiles and subscriptions') => $export . $t(
                "\n\nСсылки содержат личный токен доступа: не публикуйте их. «Сменить секрет» отзывает старые ссылки и пароль. Отключение, срок и квота закрывают выдачу профиля и VPN-доступ.",
                "\n\nLinks contain a personal access token: do not publish them. Rotate secret revokes the old links and password. Disabling, expiry and quota close both profile issuing and VPN access."),
        ];
    }
}
